# ---------------------------------------------------------------------------
#  Logging (console + lore.log, so auto-start runs are debuggable)
# ---------------------------------------------------------------------------
def _here():
    # When bundled by PyInstaller, files live next to the .exe (the install
    # folder); in dev they live next to this .py. The BUNDLED, read-only files
    # (ffmpeg, lore.ico) are found relative to this.
    if getattr(sys, "frozen", False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))


def _data_dir():
    """User-writable folder for settings, log, games list and lock/IPC files.
    The app itself can live in a read-only place (e.g. C:\\Program Files), so these
    must NOT be written next to the .exe or saving fails with a permission error."""
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
    d = os.path.join(base, "Lore") if base else _here()
    try:
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        return _here()


_JOB = [None]


def _job_object():
    """ONE Windows Job Object with KILL_ON_JOB_CLOSE: every child bound to
    it dies when this process dies - however it dies. Tonight's orphaned
    model servers (15 GB of VRAM surviving the app, then silently adopted
    by the next run) are impossible once children live here."""
    if _JOB[0] is not None or os.name != "nt":
        return _JOB[0]
    try:
        import ctypes
        import ctypes.wintypes as wt

        class _IOC(ctypes.Structure):
            _fields_ = [("ReadOperationCount", ctypes.c_ulonglong),
                        ("WriteOperationCount", ctypes.c_ulonglong),
                        ("OtherOperationCount", ctypes.c_ulonglong),
                        ("ReadTransferCount", ctypes.c_ulonglong),
                        ("WriteTransferCount", ctypes.c_ulonglong),
                        ("OtherTransferCount", ctypes.c_ulonglong)]

        class _BASIC(ctypes.Structure):
            _fields_ = [("PerProcessUserTimeLimit", wt.LARGE_INTEGER),
                        ("PerJobUserTimeLimit", wt.LARGE_INTEGER),
                        ("LimitFlags", wt.DWORD),
                        ("MinimumWorkingSetSize", ctypes.c_size_t),
                        ("MaximumWorkingSetSize", ctypes.c_size_t),
                        ("ActiveProcessLimit", wt.DWORD),
                        ("Affinity", ctypes.POINTER(wt.ULONG)),
                        ("PriorityClass", wt.DWORD),
                        ("SchedulingClass", wt.DWORD)]

        class _EXT(ctypes.Structure):
            _fields_ = [("BasicLimitInformation", _BASIC),
                        ("IoInfo", _IOC),
                        ("ProcessMemoryLimit", ctypes.c_size_t),
                        ("JobMemoryLimit", ctypes.c_size_t),
                        ("PeakProcessMemoryUsed", ctypes.c_size_t),
                        ("PeakJobMemoryUsed", ctypes.c_size_t)]

        k32 = ctypes.windll.kernel32
        h = k32.CreateJobObjectW(None, None)
        info = _EXT()
        info.BasicLimitInformation.LimitFlags = 0x2000  # KILL_ON_JOB_CLOSE
        if h and k32.SetInformationJobObject(h, 9, ctypes.byref(info),
                                             ctypes.sizeof(info)):
            _JOB[0] = h
        else:
            _JOB[0] = 0
    except Exception:
        _JOB[0] = 0
    return _JOB[0]


_ERRMODE_SET = [False]


def _popen(*a, **k):
    """subprocess.Popen + bind the child to the kill-on-close job.

    SEM_NOGPFAULTERRORBOX first, once: children inherit the parent's
    error mode, and without it a model server that dies on the graphics
    driver throws a Windows crash dialog onto HIS SCREEN mid-game. The
    crash still logs and still retries - it just stops shouting."""
    if os.name == "nt" and not _ERRMODE_SET[0]:
        try:
            import ctypes
            ctypes.windll.kernel32.SetErrorMode(0x8003)
            _ERRMODE_SET[0] = True
        except Exception:
            pass
    pr = subprocess.Popen(*a, **k)
    try:
        j = _job_object()
        if j:
            import ctypes
            ctypes.windll.kernel32.AssignProcessToJobObject(
                j, int(pr._handle))
    except Exception:
        pass
    return pr


_LOG_WHY = [False, False]      # each fallback names its cause ONCE


def log(msg):
    line = f"[{_dt.datetime.now():%H:%M:%S}] {msg}"
    try:
        print(line, flush=True)        # no-op in the windowed build (no console)
    except Exception:
        pass
    try:
        lp = os.path.join(_data_dir(), "lore.log")
        try:
            if os.path.getsize(lp) > 4_000_000:   # keep one past life
                os.replace(lp, lp + ".1")
        except OSError:
            pass
        with open(lp, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")
    except Exception as e_log:
        # THE BEACON. The 4:04 instance of 2.93 ran for hours writing
        # opened.json into this very folder while lore.log gained not one
        # line - and every recorder mystery since (the Bazaar's self-stop
        # included) has been undiagnosable for it. If the main log write
        # fails, the line goes to a second file instead of nowhere, and
        # the failure itself is written down once.
        wrote = False
        try:
            lb = os.path.join(_data_dir(), "lore.log.b")
            with open(lb, "a", encoding="utf-8") as fh:
                if not _LOG_WHY[0]:
                    _LOG_WHY[0] = True
                    fh.write("[the main log failed: %r]\n" % (e_log,))
                fh.write(line + "\n")
            wrote = True
        except Exception:
            pass
        if not wrote:
            # THE THIRD CHANNEL. 3.01's main instance lost every line
            # with BOTH channels above failing together (same folder,
            # same invisible cause) - while its sidecar writes to the
            # Records volume never missed. The last resort lives where
            # the writes provably work, and it writes down WHY the
            # healthy channels failed - the fact every dead-log hunt
            # has been missing. Engages only on double failure; a
            # healthy install never creates this file.
            try:
                d3 = _thumb_dir(SETTINGS.get("output_dir", ""))
                with open(os.path.join(d3, "lore.log.c"), "a",
                          encoding="utf-8") as fh:
                    if not _LOG_WHY[1]:
                        _LOG_WHY[1] = True
                        fh.write("[log AND beacon failed: %r]\n"
                                 % (e_log,))
                    fh.write(line + "\n")
            except Exception:
                pass


# ---------------------------------------------------------------------------
#  Single-instance lock + "show the window" IPC
#  (stops "Start" from launching a second recorder on top of the first, and lets a
#   second launch pop the running instance's window instead of starting a new copy)
# ---------------------------------------------------------------------------
def _lock_path():
    return os.path.join(_data_dir(), "lore.lock")


def _show_flag_path():
    return os.path.join(_data_dir(), "show.flag")


def _watcher_running_pid():
    """PID of a live OTHER Lore instance, or None.

    Critically, we confirm the PID belongs to an ACTUAL Lore process - not just
    that *some* process has that number. After a freeze/crash or a reboot the lock
    file can be left behind pointing at an old PID, and the OS routinely reuses that
    PID for an unrelated program. The old check only asked 'does any process with
    this PID exist?', so a reused PID made Lore think a copy was already running
    and refuse to start (double-click did nothing). Matching the executable fixes
    that, and a stale lock simply gets reclaimed."""
    try:
        with open(_lock_path()) as fh:
            pid = int(fh.read().strip())
    except Exception:
        return None
    if pid == os.getpid():
        return None
    try:
        if not psutil.pid_exists(pid):
            return None
        p = psutil.Process(pid)
        pname = (p.name() or "").lower()
        # Frozen build: the process is Lore.exe. Exact-match on the name -
        # a substring test would false-positive on e.g. explorer.exe ('lore').
        if pname == "lore.exe" or pname.startswith("lore."):
            return pid
        # Running from source: same interpreter (python/pythonw) - only count it if
        # it's actually running our script, otherwise an unrelated python is not us.
        me_name = (psutil.Process(os.getpid()).name() or "").lower()
        if pname == me_name:
            try:
                cl = " ".join(p.cmdline()).lower()
                if "lore.py" in cl:
                    return pid
            except Exception:
                return pid    # can't read its command line; assume same-name is us
        return None           # PID reused by something unrelated -> stale lock
    except Exception:
        return None


def _signal_show():
    """Ask an already-running tray instance to pop its settings window."""
    try:
        open(_show_flag_path(), "w").close()
    except Exception:
        pass


_SINGLETON_MUTEX = None
_MUTEX_NAME = "Lore_SingleInstance_Gate"   # must match installer.iss AppMutex


def _hold_singleton_mutex():
    """Create/hold a named Windows mutex for our whole lifetime AND report whether
    we are the FIRST instance. This is the authoritative, OS-atomic singleton gate:
    the lock file alone has a check-then-write race where two launches fired within
    a few milliseconds (a common double-click) both read 'no lock' and both start,
    ending up with two recorders writing into the same folder. CreateMutexW is
    atomic in the kernel, so exactly one launch wins. The installer declares the
    same name via AppMutex to detect a running copy during an update.

    Returns True if we are the first instance (also True off-Windows, or on any
    error - we never block startup on a mutex hiccup). Idempotent: a second call in
    the SAME process (e.g. tray -> console fallback) returns True."""
    global _SINGLETON_MUTEX
    if os.name != "nt":
        return True
    if _SINGLETON_MUTEX:
        return True                       # already acquired by us this process
    try:
        import ctypes
        ERROR_ALREADY_EXISTS = 183
        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        h = k32.CreateMutexW(None, False, _MUTEX_NAME)
        err = ctypes.get_last_error()
        _SINGLETON_MUTEX = h
        if not h:
            return True                   # couldn't create it; don't block on that
        return err != ERROR_ALREADY_EXISTS
    except Exception:
        _SINGLETON_MUTEX = None
        return True


# ---------------------------------------------------------------------------
#  Settings
# ---------------------------------------------------------------------------
def _settings_path():
    return os.path.join(_data_dir(), "settings.json")


def _migrate_legacy_data():
    """One-time: inherit everything Records (LORE's previous incarnation) knew,
    so the tome opens already filled - settings, the games/ignore lists, the
    file-ownership manifest (the storage cap keeps managing old recordings)
    and any pending HDR->SDR conversions. Best-effort, silent, and it never
    overwrites anything LORE has already written."""
    newp = _settings_path()
    if os.path.exists(newp):
        return
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or ""
    candidates = [os.path.join(base, "Records") if base else "", _here()]
    for old in candidates:
        try:
            if not (old and os.path.isfile(os.path.join(old, "settings.json"))):
                continue
            for name in ("settings.json", "games.txt", "ignore.txt",
                         "created_files.json", "finish_queue.json"):
                src = os.path.join(old, name)
                dst = os.path.join(_data_dir(), name)
                if os.path.isfile(src) and not os.path.exists(dst):
                    shutil.copy2(src, dst)
            log(f"Inherited existing setup from {old}")
            return
        except Exception:
            pass


def _migrate_settings_shape():
    """Bring older settings.json shapes up to date in memory (saved back on the
    next Save). Best-effort and silent: never raises, never overwrites a value the
    user has clearly set on the new shape."""
    s = SETTINGS
    # hdr_mode history: checkbox (bool) -> auto|on|off -> auto|tonemap|off ->
    # auto|off (1.24: the live tone-map path is gone - the 8/10-bit sources it
    # read were proven clipped at capture, so it could never look right). Any
    # legacy value that meant "handle HDR" maps to auto; only "off" stays off.
    hm = s.get("hdr_mode")
    if isinstance(hm, bool):
        s["hdr_mode"] = "auto"
    elif isinstance(hm, str):
        if hm.lower() not in ("auto", "off"):
            s["hdr_mode"] = "auto"
    # retired with the live tone-map path (1.24)
    s.pop("hdr_input", None)
    s.pop("hdr_peak_nits", None)
    # Start and Stop used to be two separate hotkeys; they are now one record
    # toggle. If the new key isn't present, inherit the old Start key so nobody's
    # muscle memory breaks.
    if not s.get("hotkey_record"):
        legacy = (s.get("hotkey_start") or "").strip()
        s["hotkey_record"] = legacy or DEFAULTS["hotkey_record"]
    # Drop the retired keys so they don't linger in settings.json.
    s.pop("hotkey_start", None)
    s.pop("hotkey_stop", None)


def _sanitize_settings(d):
    """Coerce/clamp values loaded from settings.json so a corrupt or hand-edited file
    can't feed a bad value (e.g. framerate 0, bitrate -5) straight into ffmpeg. Each
    numeric key falls back to its DEFAULT on a bad type/range; a few small enums fall
    back if not in their allowed set. 'encoder' is deliberately NOT whitelisted - a
    power user may hand-set one the GUI doesn't list, and resolve_encoder already
    validates it by probing. hdr_mode is left for _migrate_settings_shape (it maps a
    legacy boolean)."""
    INT_BOUNDS = {
        "framerate": (1, 1000), "bitrate_mbps": (1, 1000), "monitor_index": (-1, 64),
        "poll_interval": (1, 60), "segment_seconds": (2, 60), "replay_seconds": (1, 3600),
        "min_keep_seconds": (0, 3600),
        "audio_offset_ms": (-60000, 60000),
        "max_storage_gb": (0, 1000000), "sfx_volume": (0, 100),
        "clip_hotkey_seconds": (1, 3600), "discord_max_mb": (1, 1000),
        "discord_clip_seconds": (1, 3600), "discord_quality_mbps": (1, 1000),
        "sdr_finish_max_min": (1, 600), "afk_minutes": (1, 120),
    }
    for k, (lo, hi) in INT_BOUNDS.items():
        try:
            d[k] = max(lo, min(hi, int(d.get(k, DEFAULTS.get(k, lo)))))
        except Exception:
            d[k] = DEFAULTS.get(k, lo)
    ENUMS = {
        "amf_quality": ("speed", "balanced", "quality"),
        "audio_mode": ("mix", "separate"),
        "detection_mode": ("auto", "list"),
        "popup_style": ("slide", "rise", "pop", "glow", "sweep", "off"),
        "popup_size": ("small", "medium", "large", "huge"),
        "capture_scope": ("screen", "window"),
        "capture_backend": ("auto", "ddagrab"),
        "seek_step": ("frame", "1", "5", "10"),
    }
    # (hdr_mode is normalised by _migrate_settings_shape, which also maps legacy values)
    for k, allowed in ENUMS.items():
        v = d.get(k)
        d[k] = v.lower() if (isinstance(v, str) and v.lower() in allowed) else DEFAULTS[k]
    # vault pins: a list of chapter keys; anything malformed collapses to []
    try:
        d["cap_pinned_games"] = [str(x).strip().lower()
                                 for x in (d.get("cap_pinned_games") or [])
                                 if str(x).strip()][:500]
    except Exception:
        d["cap_pinned_games"] = []


def load_settings():
    global SETTINGS
    with _SETTINGS_LOCK:
        _migrate_legacy_data()
        new = dict(DEFAULTS)
        if os.path.isfile(_settings_path()):
            try:
                with open(_settings_path(), encoding="utf-8") as fh:
                    new.update(json.load(fh))
            except Exception as e:
                log(f"Could not read settings.json ({e}); using defaults.")
        _sanitize_settings(new)
        # Single rebind: a concurrent reader (the watcher) never sees a half-built
        # dict that's momentarily back at DEFAULTS.
        SETTINGS = new
        _migrate_settings_shape()
        _resolve_ffmpeg_paths()
        return SETTINGS


def _resolve_ffmpeg_paths():
    """Prefer a bundled ffmpeg (so friends don't install anything). An explicit
    path is respected ONLY while it actually exists: settings inherited from
    Records carry Records' bundled path, and the moment Records is uninstalled
    that path dies - which used to greet every launch with 'can't find its
    video tool' even though LORE ships its own copy right next to the exe.
    A dead explicit path now heals itself: bundled -> old Records installs ->
    PATH, and the fix is persisted so it never has to heal twice."""
    exp = SETTINGS.get("ffmpeg_path", "ffmpeg")
    explicit = exp not in ("ffmpeg", "", None)
    if explicit and os.path.isfile(exp):
        return                        # user's explicit path, alive - respect it
    if explicit:
        log(f"Configured ffmpeg not reachable ({exp}); using another copy this run.")
    cands = [os.path.join(_here(), "ffmpeg", "bin", "ffmpeg.exe")]
    for pf in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")):
        if pf:
            cands.append(os.path.join(pf, "Lore", "ffmpeg", "bin", "ffmpeg.exe"))
            cands.append(os.path.join(pf, "Records", "ffmpeg", "bin", "ffmpeg.exe"))
    for cand in cands:
        if os.path.isfile(cand):
            # Heal IN MEMORY ONLY. We deliberately never rewrite an explicit
            # ffmpeg_path: a path on a merely-disconnected network/USB drive is
            # indistinguishable from a permanently-dead one, and silently
            # discarding the user's choice would lose it for good. Recording
            # uses this copy for the session; when the drive returns next
            # launch, the user's own path is respected again.
            SETTINGS["ffmpeg_path"] = cand
            return
    if explicit:
        SETTINGS["ffmpeg_path"] = "ffmpeg"     # last hope: PATH (in-memory only)


def _atomic_write_json(path, obj):
    """Write JSON to `path` so a crash or power loss can never leave a truncated,
    unreadable file: write a sibling temp file, flush it to disk, then atomically
    replace the real one. Raises on failure (callers decide how loud to be)."""
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(obj, fh, indent=2)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except Exception:
            pass
    os.replace(tmp, path)   # atomic on Windows and POSIX


def save_settings(data):
    # Never persist runtime-internal keys (e.g. _encoder_resolved): they're
    # re-derived each launch, and saving a stale one would skip GPU re-detection.
    clean = {k: v for k, v in data.items() if not k.startswith("_")}
    with _SETTINGS_LOCK:
        _atomic_write_json(_settings_path(), clean)


# ---------------------------------------------------------------- the key
# NOT in settings.json. That file is plain JSON, gets copied around, and shows
# up in a screenshot the moment anyone opens it. This one is encrypted by
# Windows against this user on this machine, and nothing in LORE ever reads it
# back to the interface - the closest you can get is "yes, there is one".
def _key_path():
    return os.path.join(_data_dir(), "claude.key")


def _dpapi(data, unprotect=False):
    """Windows DPAPI. Returns None if it cannot be done, and the caller then
    refuses to store anything rather than writing a key in the clear."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes

        class BLOB(ctypes.Structure):
            _fields_ = [("cbData", wintypes.DWORD),
                        ("pbData", ctypes.POINTER(ctypes.c_char))]

        buf = ctypes.create_string_buffer(data, len(data))
        src = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_char)))
        out = BLOB()
        fn = (ctypes.windll.crypt32.CryptUnprotectData if unprotect
              else ctypes.windll.crypt32.CryptProtectData)
        args = ([ctypes.byref(src), None, None, None, None, 0,
                 ctypes.byref(out)] if not unprotect else
                [ctypes.byref(src), None, None, None, None, 0,
                 ctypes.byref(out)])
        if not fn(*args):
            return None
        try:
            return ctypes.string_at(out.pbData, out.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(out.pbData)
    except Exception:
        return None


def _key_save(raw):
    """Store a key. Returns (ok, why)."""
    raw = (raw or "").strip()
    if not raw:
        return False, "nothing to save"
    if not raw.startswith("sk-ant-"):
        return False, "that does not look like an Anthropic key"
    blob = _dpapi(raw.encode("utf-8"))
    if blob is None:
        return False, "this PC will not encrypt it, so it will not be stored"
    try:
        os.makedirs(os.path.dirname(_key_path()), exist_ok=True)
        with open(_key_path(), "wb") as fh:
            fh.write(blob)
        # remember only what is safe to show: when it went in, and the last
        # four characters, so you can tell one key from another
        when = _dt.datetime.now().strftime("%d %B %Y")
        SETTINGS["claude_key_added"] = when
        SETTINGS["claude_key_tail"] = raw[-4:]
        _persist_setting("claude_key_added", when)
        _persist_setting("claude_key_tail", raw[-4:])
        log("Claude key stored (encrypted to this Windows account).")
        return True, ""
    except Exception as e:
        return False, str(e)


def _key_read():
    """The key itself, for LORE's own use only. Never returned over the API."""
    try:
        with open(_key_path(), "rb") as fh:
            blob = fh.read()
    except OSError:
        return None
    out = _dpapi(blob, unprotect=True)
    return out.decode("utf-8", "replace") if out else None


def _key_forget():
    try:
        os.remove(_key_path())
    except OSError:
        pass
    for k in ("claude_key_added", "claude_key_tail"):
        _persist_setting(k, "")      # also clears the live SETTINGS copy
    log("Claude key forgotten.")
    return True


def _persist_setting(key, value):
    """Update a single key in settings.json on disk without disturbing the live
    SETTINGS or other keys. Used by the watcher to remember a discovered fix."""
    try:
        with _SETTINGS_LOCK:
            d = {}
            if os.path.isfile(_settings_path()):
                with open(_settings_path(), encoding="utf-8") as fh:
                    d = json.load(fh)
            d[key] = value
            _atomic_write_json(_settings_path(), d)
            SETTINGS[key] = value
    except Exception as e:
        log(f"Could not persist setting '{key}': {e}")


# ---------------------------------------------------------------------------
#  Game detection
# ---------------------------------------------------------------------------
def running_process_names():
    names = set()
    for p in psutil.process_iter(["name"]):
        n = p.info.get("name")
        if n:
            names.add(n.lower())
    return names


def _looks_gone(current):
    """The three-agreements gone test in ONE place: a game reads as
    closed only when a TRUSTWORTHY process walk lacks it AND no window
    of its answers. Four separate sites used to trust a single raw walk
    - the active-recording check among them, which is precisely how a
    16-minute Bazaar saved itself and restarted while he was playing:
    two short walks in a row, debounce of two, recording gone."""
    if not current:
        return False
    names = running_process_names()
    return (_process_walk_trustworthy(names)
            and current not in names
            and not _exe_has_any_window(current))


def _process_walk_trustworthy(names):
    """Did that walk actually see the machine?

    Windows is never running twelve processes. A list that short means the
    walk was refused or cut off, and a recording must never be ended on the
    strength of a question that failed to be asked. Idle Windows sits around
    a hundred; twenty is generous."""
    return len(names) >= 20


def load_game_list():
    names = set()
    path = os.path.join(_data_dir(), "games.txt")
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    if not line.lower().endswith(".exe"):
                        line += ".exe"
                    names.add(line.lower())
    return names


def read_games_lines():
    """Raw game names from games.txt (as the user typed them, no .exe forced)."""
    path = os.path.join(_data_dir(), "games.txt")
    out = []
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    out.append(line)
    return out


def write_games_lines(lines):
    path = os.path.join(_data_dir(), "games.txt")
    with open(path + ".tmp", "w", encoding="utf-8") as fh:
        fh.write("# Games Lore always captures (one name per line, e.g. eldenring).\n")
        for ln in lines:
            ln = ln.strip()
            if ln:
                fh.write(ln + "\n")
    os.replace(path + ".tmp", path)   # a crash mid-write keeps the old list


def _ignore_path():
    return os.path.join(_data_dir(), "ignore.txt")


def read_ignore_lines():
    """User-added 'never auto-record' names from ignore.txt (as typed)."""
    out = []
    path = _ignore_path()
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    out.append(line)
    return out


def write_ignore_lines(lines):
    """Save the user's extra never-record list. The built-in list always applies on
    top of this, so games keep recording even if the user empties this file."""
    with open(_ignore_path(), "w", encoding="utf-8") as fh:
        fh.write("# Extra apps Lore should NEVER auto-record when full-screen\n")
        fh.write("# (one .exe name per line, e.g. photoshop.exe). Games are still\n")
        fh.write("# always recorded - your games list and full-screen game detection\n")
        fh.write("# take priority over this list.\n")
        for ln in lines:
            ln = ln.strip()
            if ln:
                if not ln.lower().endswith(".exe"):
                    ln += ".exe"
                fh.write(ln + "\n")


def load_ignore_list():
    """The effective never-auto-record set: the built-in baseline UNION the user's
    ignore.txt additions. Always lower-case, .exe forced."""
    names = set(IGNORE_PROCESSES)
    for ln in read_ignore_lines():
        ln = ln.strip().lower()
        if ln:
            if not ln.endswith(".exe"):
                ln += ".exe"
            names.add(ln)
    return names


def _window_monitor_rect(hwnd):
    """(left, top, right, bottom) of the monitor the given window is on, or None.
    Lets borderless-fullscreen be detected on ANY screen, not just the primary."""
    if os.name != "nt" or not hwnd:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        MONITOR_DEFAULTTONEAREST = 2
        hmon = user32.MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST)
        if not hmon:
            return None

        class MONITORINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]

        mi = MONITORINFO()
        mi.cbSize = ctypes.sizeof(MONITORINFO)
        if user32.GetMonitorInfoW(ctypes.c_void_p(hmon), ctypes.byref(mi)):
            r = mi.rcMonitor
            return (r.left, r.top, r.right, r.bottom)
    except Exception:
        return None
    return None


def _watched_monitor_rect():
    """rcMonitor of the screen Lore is set to record (the monitor_index setting;
    0 = the primary screen). Full-screen DETECTION only fires for windows on this
    monitor - a game or app going fullscreen on any OTHER screen is deliberately
    ignored, because Lore would end up recording the watched screen anyway (the
    'it recorded my second monitor's fullscreen app' complaint). Monitors are ranked
    by display number, the same contract build_video_cmd uses for ddagrab output_idx.
    Returns None when monitors can't be enumerated (then any monitor is accepted)."""
    try:
        mons = _monitors_ranked()
        if not mons:
            return None
        idx = min(max(0, _resolve_capture_monitor()), len(mons) - 1)
        return tuple(mons[idx]["rect"])
    except Exception:
        return None


# ---------------------------------------------------------------------------
#  Game recognition v2 (Lore 1.1) - ShadowPlay-style, three signals instead of
#  one guess:
#    1. the WINDOW  - a real, visible, decent-sized top-level window
#    2. the OS      - Windows' own game database (GameConfigStore: the Game
#                     Bar has watched every game launch for years; 142 titles
#                     strong on the dev machine, zero chat apps or browsers)
#    3. the GPU     - sustained per-process 3D-engine load via PDH counters
#                     (the same numbers Task Manager's GPU column shows; games
#                     render at 30-100%, Claude/Discord/browsers idle at ~0-1%)
#  A window whose exe Windows already knows as a game records at once -
#  windowed or fullscreen, any monitor. An UNKNOWN exe must earn it:
#  fullscreen on the watched screen AND real 3D load on consecutive polls -
#  then it's learned, so the next launch is instant. Fullscreen alone never
#  starts a recording again (that's what recorded a fullscreened chat app).
# ---------------------------------------------------------------------------
_GAMEDB = {"set": None, "t": 0.0}


def _windows_game_db():
    """Exe basenames Windows itself has recognised as games - read from
    HKCU\\System\\GameConfigStore\\Children (each entry's MatchedExeFullPath;
    the Game Bar writes one per game it detects). Cached for 5 minutes.
    Crash-handler style entries are filtered; the user's ignore list still
    outranks whatever remains."""
    now = time.time()
    if _GAMEDB["set"] is not None and now - _GAMEDB["t"] < 300:
        return _GAMEDB["set"]
    names = set()
    try:
        import winreg
        root = r"System\GameConfigStore\Children"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, root) as k:
            count = winreg.QueryInfoKey(k)[0]
            for i in range(count):
                try:
                    sub = winreg.EnumKey(k, i)
                    with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                        root + "\\" + sub) as sk:
                        p, _ = winreg.QueryValueEx(sk, "MatchedExeFullPath")
                except OSError:
                    continue
                b = os.path.basename(str(p)).strip().lower()
                if not b.endswith(".exe"):
                    continue
                # junk that rides along in the store: crash reporters put up
                # small dialogs and must never look like the game itself
                if any(t in b for t in ("crash", "crs-handler", "report",
                                        "helper", "launcher", "setup",
                                        "unins", "redist")):
                    continue
                names.add(b)
    except Exception:
        pass
    if names or _GAMEDB["set"] is None:
        _GAMEDB["set"] = names
        _GAMEDB["t"] = now
        if names:
            log(f"Windows game database: {len(names)} titles recognised.")
    return _GAMEDB["set"] or set()


_GPU_PDH = {"q": None, "c": None, "t": 0.0, "map": {}}


def _gpu3d_usage(max_age=2.0):
    """{pid: percent} of 3D-engine GPU utilization, summed over a process's
    3D engine instances - via PDH 'GPU Engine' counters on pdh.dll (pure
    ctypes, no dependencies; exactly what Task Manager's GPU column reads).
    ONE query is kept open for the app's lifetime: PDH rates are deltas
    between collects, so each call measures activity since the previous call
    (results younger than max_age are served from cache). Any PDH hiccup
    closes the query and self-heals on the next call; failures mean {} -
    the caller then simply can't confirm a GPU signal, never crashes."""
    now = time.time()
    if _GPU_PDH["q"] is not None and now - _GPU_PDH["t"] < max_age:
        return _GPU_PDH["map"]
    try:
        import ctypes
        from ctypes import wintypes
        pdh = ctypes.windll.pdh

        class _FMT(ctypes.Structure):
            _fields_ = [("CStatus", wintypes.DWORD), ("pad", wintypes.DWORD),
                        ("doubleValue", ctypes.c_double)]

        class _ITEM(ctypes.Structure):
            _fields_ = [("szName", ctypes.c_wchar_p), ("FmtValue", _FMT)]

        if _GPU_PDH["q"] is None:
            q = ctypes.c_void_p()
            if pdh.PdhOpenQueryW(None, None, ctypes.byref(q)) != 0:
                return {}
            c = ctypes.c_void_p()
            if pdh.PdhAddEnglishCounterW(
                    q, r"\GPU Engine(*engtype_3D)\Utilization Percentage",
                    None, ctypes.byref(c)) != 0:
                pdh.PdhCloseQuery(q)
                return {}
            pdh.PdhCollectQueryData(q)      # baseline; rates need two collects
            _GPU_PDH.update({"q": q, "c": c, "t": now, "map": {}})
            return {}
        q, c = _GPU_PDH["q"], _GPU_PDH["c"]
        if pdh.PdhCollectQueryData(q) != 0:
            raise OSError("collect failed")
        sz = wintypes.DWORD(0)
        cnt = wintypes.DWORD(0)
        r = pdh.PdhGetFormattedCounterArrayW(
            c, 0x00000200, ctypes.byref(sz), ctypes.byref(cnt), None) & 0xFFFFFFFF
        if r != 0x800007D2:                 # PDH_MORE_DATA
            raise OSError(f"size {r:#x}")
        buf = (ctypes.c_byte * sz.value)()
        if pdh.PdhGetFormattedCounterArrayW(
                c, 0x00000200, ctypes.byref(sz), ctypes.byref(cnt), buf) != 0:
            raise OSError("array failed")
        items = ctypes.cast(buf, ctypes.POINTER(_ITEM * cnt.value)).contents
        per = {}
        for it in items:
            name = it.szName or ""
            if it.FmtValue.CStatus not in (0, 1):
                continue
            i = name.find("pid_")
            if i < 0:
                continue
            j = name.find("_", i + 4)
            try:
                pid = int(name[i + 4:j])
            except Exception:
                continue
            per[pid] = per.get(pid, 0.0) + it.FmtValue.doubleValue
        _GPU_PDH["map"] = per
        _GPU_PDH["t"] = now
        return per
    except Exception:
        try:
            if _GPU_PDH["q"] is not None:
                ctypes.windll.pdh.PdhCloseQuery(_GPU_PDH["q"])
        except Exception:
            pass
        _GPU_PDH.update({"q": None, "c": None, "map": {}})
        return {}


_LEARNED = {"set": None}


def _learned_games_path():
    return os.path.join(_data_dir(), "learned_games.json")


_WATCH_NOTE = {"fail_at": 0.0, "fail_g": "",
               "learn_at": 0.0, "learn_g": ""}


def _learned_games():
    """Exes the GPU+fullscreen heuristic has already proven to be games -
    persisted, so every future launch records instantly (windowed too),
    exactly how ShadowPlay 'knows' your library. Ignore-listed names are
    dropped on load, so un-learning is one Settings click away."""
    if _LEARNED["set"] is None:
        s = set()
        try:
            with open(_learned_games_path(), encoding="utf-8") as fh:
                s = {str(x).lower() for x in json.load(fh) if str(x).strip()}
        except Exception:
            pass
        _LEARNED["set"] = s
    return _LEARNED["set"] - load_ignore_list()


def _learn_game_exe(name):
    name = (name or "").strip().lower()
    if not name or name in _learned_games():
        return
    s = _LEARNED["set"] if _LEARNED["set"] is not None else set()
    s.add(name)
    _LEARNED["set"] = s
    try:
        _atomic_write_json(_learned_games_path(), sorted(s))
    except Exception:
        pass
    log(f"Learned a new game: {name} (recognised by GPU + fullscreen).")


# ---------------------------------------------------------------------------
#  AFK detection (Lore 2.0) - "is the user actually here?"
#  Two signals, combined: GetLastInputInfo (keyboard+mouse; the OS's own idle
#  clock) and XInput controller state diffs (pads do NOT touch the OS idle
#  clock - a controller-only session would look AFK without this). Controller
#  changes are dead-zone filtered: an untouched pad's stick jitter increments
#  the packet counter forever and would defeat AFK pause entirely.
# ---------------------------------------------------------------------------
_PAD = {"xi": None, "tried": False, "last": {}, "conn": set(),
        "rescan_t": 0.0, "active_t": 0.0}


def _kbms_idle_ms():
    """Milliseconds since the last keyboard/mouse input in this session.
    0 (= active) on any failure - AFK must fail toward 'user is here'."""
    if os.name != "nt":
        return 0
    try:
        import ctypes
        from ctypes import wintypes

        class LII(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.UINT), ("dwTime", wintypes.DWORD)]
        lii = LII()
        lii.cbSize = ctypes.sizeof(LII)
        if not ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii)):
            return 0
        return (ctypes.windll.kernel32.GetTickCount() - lii.dwTime) & 0xFFFFFFFF
    except Exception:
        return 0


def _pad_check():
    """Note controller activity into _PAD['active_t']. Dead-zone filtered
    (official XInput thresholds); connected pads polled every call, empty
    slots rescanned every ~5s (Microsoft's own guidance - empty-slot probes
    cost milliseconds each). Safe no-op when XInput is unavailable."""
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes
        if _PAD["xi"] is None and not _PAD["tried"]:
            _PAD["tried"] = True
            for dll in ("xinput1_4.dll", "xinput1_3.dll", "xinput9_1_0.dll"):
                try:
                    _PAD["xi"] = ctypes.WinDLL(dll)
                    break
                except OSError:
                    pass
        xi = _PAD["xi"]
        if xi is None:
            return

        class GP(ctypes.Structure):
            _fields_ = [("wButtons", wintypes.WORD),
                        ("bLeftTrigger", ctypes.c_ubyte),
                        ("bRightTrigger", ctypes.c_ubyte),
                        ("sThumbLX", ctypes.c_short), ("sThumbLY", ctypes.c_short),
                        ("sThumbRX", ctypes.c_short), ("sThumbRY", ctypes.c_short)]

        class ST(ctypes.Structure):
            _fields_ = [("dwPacketNumber", wintypes.DWORD), ("Gamepad", GP)]
        now = time.time()
        rescan = now - _PAD["rescan_t"] > 5.0
        if rescan:
            _PAD["rescan_t"] = now
        slots = range(4) if rescan else list(_PAD["conn"])
        for i in slots:
            st = ST()
            if xi.XInputGetState(i, ctypes.byref(st)) == 0:
                _PAD["conn"].add(i)
                g, prev = st.Gamepad, _PAD["last"].get(i)
                # THE STATE must differ - never the packet counter alone.
                # Emulated XInput pads (Steam Input / DS4Windows, a
                # DualSense on USB) bump dwPacketNumber at their report
                # rate, hundreds per poll, with the pad flat on the desk:
                # the old bare packet test read that as a human forever
                # and silently defeated the AFK pause.
                if prev is not None and (
                        g.wButtons != prev[0]
                        or g.bLeftTrigger > 30 or g.bRightTrigger > 30
                        or abs(g.sThumbLX) > 7849 or abs(g.sThumbLY) > 7849
                        or abs(g.sThumbRX) > 8689 or abs(g.sThumbRY) > 8689):
                    _PAD["active_t"] = now
                _PAD["last"][i] = (g.wButtons, g.bLeftTrigger,
                                   g.bRightTrigger, st.dwPacketNumber)
            else:
                _PAD["conn"].discard(i)
                _PAD["last"].pop(i, None)
    except Exception:
        pass


def _cursor_pos():
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes

        class PT(ctypes.Structure):
            _fields_ = [("x", wintypes.LONG), ("y", wintypes.LONG)]
        pt = PT()
        ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))
        return (pt.x, pt.y)
    except Exception:
        return None


# breadcrumb state: the last idle reading, where the cursor was, and when
# the log last spoke (>=10 min between lines - never a log storm)
_AFK_CLK = {"prev": 0.0, "pos": None, "said": 0.0}


def _afk_idle_seconds():
    """Seconds since the user last did ANYTHING - keyboard, mouse, or a
    real (state-changing, dead-zone-beating) controller input. When a
    countdown that had passed two quiet minutes is reset, the log says by
    WHAT - so a defeated AFK pause (30 silent minutes recorded on
    2026-08-15) is a named culprit next time, not a mystery."""
    _pad_check()
    now = time.time()
    idle = _kbms_idle_ms() / 1000.0
    pad_ago = now - _PAD["active_t"] if _PAD["active_t"] else 1e9
    got = min(idle, pad_ago)
    prev = _AFK_CLK["prev"]
    if prev > 120 and got < 5 and now - _AFK_CLK["said"] > 600:
        _AFK_CLK["said"] = now
        pos, ppos = _cursor_pos(), _AFK_CLK["pos"]
        moved = (abs(pos[0] - ppos[0]) + abs(pos[1] - ppos[1])
                 if pos and ppos else -1)
        src = ("the controller" if pad_ago < 5 else
               f"keyboard/mouse (cursor travelled {moved} px)"
               if moved >= 0 else "keyboard/mouse")
        log(f"AFK countdown reset at {int(prev // 60)} min by {src}.")
    _AFK_CLK["prev"] = got
    _AFK_CLK["pos"] = _cursor_pos()
    return got


def _inp_beat(session):
    """THE INPUT CHRONICLE: one cheap sample per healthy watcher beat -
    how many keys/buttons are held and how far the mouse moved - kept on
    the session and written as an .inp sidecar at save. The clock is
    ACTIVE capture time (pauses excluded), so the curve lines up with the
    footage within a rotation's slack. Counts only - never WHICH keys."""
    try:
        now = time.time()
        last = getattr(session, "_inp_wall", 0.0)
        session._inp_wall = now
        if getattr(session, "suspended", False):
            return
        dt = (now - last) if (last and now - last < 5.0) else 0.0
        session._inp_t = getattr(session, "_inp_t", 0.0) + dt
        down = 0
        try:
            import ctypes
            gaks = ctypes.windll.user32.GetAsyncKeyState
            for vk in range(1, 224):
                if gaks(vk) & 0x8000:      # held NOW - never the since-bit
                    down += 1
        except Exception:
            pass
        pos = _cursor_pos()
        prev = getattr(session, "_inp_pos", None)
        px = (abs(pos[0] - prev[0]) + abs(pos[1] - prev[1]))             if (pos and prev) else 0
        session._inp_pos = pos
        buf = getattr(session, "_inp", None)
        if buf is None:
            buf = session._inp = []
        buf.append([round(session._inp_t, 1), down, min(4000, px)])
        if len(buf) > 90000:               # ~15h of beats - never unbounded
            del buf[:len(buf) - 90000]
    except Exception:
        pass


def _afk_track(ctl, session, current):
    """Auto-pause the recording when the user has been away for the set
    time, and resume the moment they're back - hands-off, like the rest of
    the tome. Reuses the pause/resume machinery (footage kept, same file).
    Never pauses over the window-minimise auto-pause, and a USER pause is
    never touched. Called once per watcher poll."""
    if not SETTINGS.get("afk_pause", True):
        return
    try:
        thresh = max(60, int(SETTINGS.get("afk_minutes", 4)) * 60)
    except Exception:
        thresh = 240
    idle = _afk_idle_seconds()
    if getattr(session, "afk_paused", False):
        if idle < 5.0:
            # They're back. ONLY clear the flag - the watcher's suspended
            # branch owns the actual resume, because it re-aims the window
            # first (the window may have vanished, moved screens, or the
            # display flipped HDR while they were away). Resuming here
            # skipped those checks and could record the wrong thing.
            session.afk_paused = False
            log("AFK: you're back - resuming.")
        return
    if session.suspended:
        return                             # user/window pause: not ours
    if idle >= thresh:
        session.afk_paused = True
        _loop_sound(ctl, "off")            # chime symmetry with the resume
        session.suspend()
        ctl.set_status("paused")
        log(f"AFK for {int(idle // 60)} min - recording paused (it resumes "
            "when you're back).")
        ctl.notify("Recording paused",
                   "You seem to be away - it continues when you're back.")


def _exe_has_any_window(pname):
    """Does this process own ANY top-level window - visible or not? An
    alt-tabbed exclusive-fullscreen game HIDES its window (it still exists);
    a wedged crash or exit-to-tray resident has none. The gone-pause
    backstop uses this to tell 'long alt-tab, keep waiting' apart from
    'never coming back, save the footage'. Errors report False, so footage
    is saved rather than held hostage."""
    if os.name != "nt" or not pname:
        return False
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        pids = set()
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    pids.add(pr.info["pid"])
            except Exception:
                pass
        if not pids:
            return False
        found = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if pid.value in pids:
                    if not (user32.GetWindowLongW(h, -20) & 0x00000080):
                        found.append(h)     # any non-tool top-level counts
                        return 0
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return bool(found)
    except Exception:
        return False


_GPU_HITS = {}   # exe -> (streak, last-hit wallclock) for the unknown-exe path


def detect_game_smart():
    """The auto-detection heart of Lore 1.1 (see the banner comment above).
    Returns the exe name to record, or None. The user/builtin lists are
    checked by find_active_game BEFORE this runs - this function decides
    about what's on screen right now. LEARNED games are checked here (not
    by process presence): a machine-curated entry must show a real window,
    or a lingering background process would claim recordings forever."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        # Prune stale GPU streaks FIRST - before any early return can skip
        # it. A streak only counts as 'consecutive' if its last hit is
        # within ~two polls; anything older is a dead spike, not a game.
        try:
            poll = float(SETTINGS.get("poll_interval", 3) or 3)
        except Exception:
            poll = 3.0
        now = time.time()
        for k in list(_GPU_HITS):
            if now - _GPU_HITS[k][1] > max(8.0, poll * 2.5):
                del _GPU_HITS[k]
        ignore = load_ignore_list()
        gamedb = _windows_game_db() | _learned_games()
        watched = _watched_monitor_rect()
        cands = []                   # (exe, pid, fullscreen-ish, on_watched)

        def _consider(h):
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
            if not pid.value or pid.value == os.getpid():
                return
            try:
                if user32.GetWindow(h, 4):                    # GW_OWNER
                    return
                ex = user32.GetWindowLongW(h, -20)            # GWL_EXSTYLE
                if ex & 0x00000080:                           # TOOLWINDOW
                    return
                buf = ctypes.create_unicode_buffer(64)
                user32.GetClassNameW(h, buf, 64)
                if buf.value in ("Progman", "WorkerW", "Shell_TrayWnd",
                                 "Windows.UI.Core.CoreWindow"):
                    return
                cloaked = ctypes.c_int(0)
                if ctypes.windll.dwmapi.DwmGetWindowAttribute(
                        h, 14, ctypes.byref(cloaked),
                        ctypes.sizeof(cloaked)) == 0 and cloaked.value:
                    return
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                w, hh = r.right - r.left, r.bottom - r.top
                if w < 480 or hh < 320:
                    return                                    # dialogs, stubs
                mrect = _window_monitor_rect(h)
                fs = False
                if mrect:
                    mw, mh = mrect[2] - mrect[0], mrect[3] - mrect[1]
                    caption = user32.GetWindowLongW(h, -16) & 0x00C00000
                    fs = (not caption and w >= mw - 2 and hh >= mh - 2)
                on_watched = (watched is None
                              or (mrect is not None and tuple(mrect) == watched))
                try:
                    pr = psutil.Process(pid.value)
                    exe = pr.name().lower()
                except psutil.Error:
                    return
                if exe in ignore:
                    return
                # a window whose exe lives in a game-store library is a
                # game until proven otherwise - browsers and editors do
                # not live in steamapps\common. The TOOLS that live in
                # there beside the games (crash reporters, prelaunchers,
                # setup stubs) are named like tools, and a mislearn is
                # permanent - so they never earn.
                gamey = False
                try:
                    pth = (pr.exe() or "").lower()
                    gamey = ("\\steamapps\\common\\" in pth
                             or "\\epic games\\" in pth
                             or "\\gog galaxy\\games\\" in pth
                             or "\\xboxgames\\" in pth)
                    if gamey and any(t in exe for t in (
                            "launcher", "crashreport", "helper",
                            "setup", "install", "updater", "unins",
                            "redist", "dxsetup", "easyanticheat",
                            "battleye", "report", "config")):
                        gamey = False
                except (psutil.Error, OSError):
                    pass
                cands.append((exe, pid.value, fs, on_watched, gamey))
            except Exception:
                pass

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if user32.IsWindowVisible(h) and not user32.IsIconic(h):
                    _consider(h)
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)

        # Signal 2: the OS already calls it a game -> record, windowed or
        # not, whatever monitor it's on (window scope follows it there).
        for exe, pid, fs, onw, gamey in cands:
            if exe in gamedb:
                return exe

        # Unknown exe: it must EARN recording. Fullscreen-ish on the watched
        # screen AND real 3D load across two consecutive polls -> game;
        # remember it so next time it's instant. (QUNS_RUNNING_D3D_FULL_SCREEN
        # marks exclusive fullscreen even when the window rect lies.)
        excl = None
        try:
            state = ctypes.c_int(0)
            ctypes.windll.shell32.SHQueryUserNotificationState(ctypes.byref(state))
            if state.value == 3:
                fh = user32.GetForegroundWindow()
                fp = wintypes.DWORD()
                user32.GetWindowThreadProcessId(fh, ctypes.byref(fp))
                if fp.value and fp.value != os.getpid():
                    try:
                        e = psutil.Process(fp.value).name().lower()
                        if e not in ignore:
                            excl = (e, fp.value)
                    except psutil.Error:
                        pass
        except Exception:
            pass
        # who is HE looking at - a store-library game earns windowed,
        # but only the one in front (a launcher idling in the back must
        # not learn its way into the library)
        fg_pid = 0
        try:
            _fh = user32.GetForegroundWindow()
            _fp = wintypes.DWORD()
            user32.GetWindowThreadProcessId(_fh, ctypes.byref(_fp))
            fg_pid = _fp.value or 0
        except Exception:
            pass
        hopefuls = {}
        for exe, pid, fs, onw, gamey in cands:
            if fs and onw:
                hopefuls[exe] = (pid, 12.0)
            elif gamey and onw and pid == fg_pid \
                    and exe not in hopefuls:
                # WINDOWED GAMES EXIST. The fullscreen requirement made
                # a windowed indie invisible forever (Hearth and Hamlet,
                # a whole session unrecorded). A store-library exe in
                # the FOREGROUND earns by the same two-poll GPU streak,
                # at a threshold a cozy indie on a big card can clear.
                # Never overwriting means a fullscreen sibling window
                # keeps its stricter bar.
                hopefuls[exe] = (pid, 3.0)
        if excl and excl[0] not in hopefuls:
            hopefuls[excl[0]] = (excl[1], 12.0)
        if hopefuls:
            # cache no longer than the poll gap, or two 'consecutive' polls
            # would read the SAME GPU sample and one spike could pass for two
            usage = _gpu3d_usage(max_age=min(2.0, max(0.5, poll * 0.8)))
            for exe, (pid, thresh) in hopefuls.items():
                if usage.get(pid, 0.0) >= thresh:
                    n = _GPU_HITS.get(exe, (0, 0.0))[0] + 1
                    _GPU_HITS[exe] = (n, now)
                    if n >= 2:
                        _learn_game_exe(exe)
                        _WATCH_NOTE["learn_at"] = time.time()
                        _WATCH_NOTE["learn_g"] = exe
                        return exe
                else:
                    _GPU_HITS.pop(exe, None)   # streak broke: GPU went idle
    except Exception:
        return None
    return None


def detect_fullscreen_game():
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        shell32 = ctypes.windll.shell32
        ignore = load_ignore_list()
        watched = _watched_monitor_rect()

        def _name_if_game(hwnd, require_borderless):
            """Process name if hwnd covers its monitor and isn't Lore / an ignored
            app / (when require_borderless) an ordinary titled or owned window. The
            cheap geometry + style checks run BEFORE the psutil lookup so scanning all
            windows stays light."""
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            if not pid.value or pid.value == os.getpid():
                return None
            if require_borderless:
                # A borderless-fullscreen game is a caption-less, un-owned, plain
                # top-level window. Excluding WS_CAPTION skips a merely-maximized
                # browser/editor (which also fills its monitor); excluding owned
                # windows skips tool popups; excluding TRANSPARENT / TOOLWINDOW /
                # NOACTIVATE ex-styles skips click-through overlays (crosshairs,
                # OSDs); excluding the shell's Progman/WorkerW skips the desktop and
                # live-wallpaper hosts; and excluding DWM-cloaked windows skips
                # suspended UWP apps that keep an invisible full-screen frame alive.
                try:
                    if user32.GetWindowLongW(hwnd, -16) & 0x00C00000:   # GWL_STYLE & WS_CAPTION
                        return None
                    if user32.GetWindow(hwnd, 4):                       # GW_OWNER
                        return None
                    ex = user32.GetWindowLongW(hwnd, -20)               # GWL_EXSTYLE
                    if ex & (0x00000020 | 0x00000080 | 0x08000000):     # TRANSPARENT|TOOLWINDOW|NOACTIVATE
                        return None
                    buf = ctypes.create_unicode_buffer(64)
                    user32.GetClassNameW(hwnd, buf, 64)
                    if buf.value in ("Progman", "WorkerW", "Shell_TrayWnd"):
                        return None
                    cloaked = ctypes.c_int(0)
                    if ctypes.windll.dwmapi.DwmGetWindowAttribute(
                            hwnd, 14, ctypes.byref(cloaked),
                            ctypes.sizeof(cloaked)) == 0 and cloaked.value:
                        return None                                    # DWMWA_CLOAKED
                except Exception:
                    return None
            rect = wintypes.RECT()
            user32.GetWindowRect(hwnd, ctypes.byref(rect))
            mrect = _window_monitor_rect(hwnd)
            # Only the WATCHED monitor counts: a window filling any other screen is
            # ignored entirely (Lore would be capturing the watched screen anyway).
            if watched is not None:
                if mrect is None or tuple(mrect) != watched:
                    return None
            if mrect:
                mon_w, mon_h = (mrect[2] - mrect[0]), (mrect[3] - mrect[1])
            else:
                mon_w, mon_h = user32.GetSystemMetrics(0), user32.GetSystemMetrics(1)
            w, h = rect.right - rect.left, rect.bottom - rect.top
            if not (w > 0 and h > 0 and w >= mon_w - 2 and h >= mon_h - 2):
                return None
            try:
                name = psutil.Process(pid.value).name().lower()
            except psutil.Error:
                return None
            return None if name in ignore else name

        # 1) Foreground window: D3D exclusive fullscreen (a global foreground state),
        # or a borderless window covering its monitor. The user focused it, so we don't
        # require it to be caption-less here.
        hwnd = user32.GetForegroundWindow()
        if hwnd:
            fpid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(fpid))
            if fpid.value and fpid.value != os.getpid():
                try:
                    fname = psutil.Process(fpid.value).name().lower()
                except psutil.Error:
                    fname = None
                if fname and fname not in ignore:
                    # D3D exclusive fullscreen - but only if it's happening on the
                    # monitor Lore actually watches/records.
                    on_watched = True
                    if watched is not None:
                        fmr = _window_monitor_rect(hwnd)
                        on_watched = (fmr is not None and tuple(fmr) == watched)
                    if on_watched:
                        state = ctypes.c_int(0)
                        try:
                            shell32.SHQueryUserNotificationState(ctypes.byref(state))
                            if state.value == 3:           # QUNS_RUNNING_D3D_FULL_SCREEN
                                return fname
                        except Exception:
                            pass
            n = _name_if_game(hwnd, require_borderless=False)
            if n:
                return n

        # 2) Nothing in the foreground qualifies: scan top-level windows so a
        # borderless game on the WATCHED monitor is still caught while the user is
        # focused elsewhere (game on the primary, clicked into Discord on screen 2).
        # _name_if_game rejects windows on other monitors, and the caption/owner/
        # ignore guards prevent grabbing a maximized browser or a media player.
        found = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _lparam):
            try:
                if user32.IsWindowVisible(h) and not user32.IsIconic(h):
                    nm = _name_if_game(h, require_borderless=True)
                    if nm:
                        found.append(nm)
                        return 0                           # first match: stop enumerating
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        if found:
            return found[0]
    except Exception:
        return None
    return None


# The tome ships with its own knowledge of games (known_games.txt, bundled
# read-only next to the app): any of these launching starts a recording even
# WINDOWED - no fullscreen needed, nothing for the user to add by hand. The
# user's ignore list always outranks it.
_BUILTIN_GAMES = {"set": None}


def load_builtin_games():
    if _BUILTIN_GAMES["set"] is not None:
        return _BUILTIN_GAMES["set"]
    names = set()
    for base in (_here(), getattr(sys, "_MEIPASS", None)):
        if not base:
            continue
        p = os.path.join(base, "known_games.txt")
        if os.path.isfile(p):
            try:
                with open(p, encoding="utf-8") as fh:
                    for line in fh:
                        line = line.strip().lower()
                        if line and not line.startswith("#"):
                            if not line.endswith(".exe"):
                                line += ".exe"
                            names.add(line)
                log(f"Known-games list loaded: {len(names)} titles.")
            except Exception:
                pass
            break
    if not names:
        # Say so ONCE - otherwise a missing/unreadable bundle makes windowed
        # auto-detect silently inert with no clue in the log.
        log("No known_games.txt bundled; windowed games auto-record only "
            "when they're in your own games list.")
    _BUILTIN_GAMES["set"] = names
    return names


def _listed_game_by_window(listed):
    """A listed game found by its WINDOW, for when the process walk
    misses it. The walk lied before (the Bazaar's self-stop) and it
    lied again tonight: hearth and hamlet.exe ran, listed, foreground -
    and the walk-based check read blank for a whole session while a
    per-window PID lookup saw it instantly. Windows are enumerated and
    each owner is asked by PID - a different road entirely, so one
    flaky snapshot cannot blind both checks at once."""
    if os.name != "nt" or not listed:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        hits = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p,
                            ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if not user32.IsWindowVisible(h) or user32.IsIconic(h):
                    return 1
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                if (r.right - r.left) < 480 or (r.bottom - r.top) < 320:
                    return 1               # dialogs, stubs
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if not pid.value or pid.value == os.getpid():
                    return 1
                try:
                    nm = psutil.Process(pid.value).name().lower()
                except psutil.Error:
                    return 1
                if nm in listed:
                    hits.append(nm)
                    return 0
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return hits[0] if hits else None
    except Exception:
        return None


def find_active_game():
    # The games.txt list is ALWAYS honored - this catches windowed games like
    # Hearthstone that window detection would miss.
    listed = load_game_list()
    running = None
    if listed:
        running = running_process_names()
        hit = listed & running
        if hit:
            return sorted(hit)[0]
        # the walk can lie (short/incomplete snapshots, measured twice
        # on this machine) - a listed game with a real window on screen
        # is playing, whatever the walk says
        byw = _listed_game_by_window(listed)
        if byw:
            return byw
    if SETTINGS["detection_mode"] == "list":
        return None
    # Auto mode: the built-in known-games list catches windowed games the
    # moment they launch (user's ignore list wins over it)...
    builtin = load_builtin_games()
    if builtin:
        if running is None:
            running = running_process_names()
        hit = (builtin & running) - load_ignore_list()
        if hit:
            return sorted(hit)[0]
    # ...and real game RECOGNITION catches everything else: Windows' own
    # game database + games the GPU heuristic learned + sustained 3D GPU
    # load for the rest. Learned games are checked THERE (with a real
    # window required), never by bare process presence - a lingering
    # background process must not claim recordings. Fullscreen alone no
    # longer starts a recording (it used to record any fullscreened app).
    return detect_game_smart()


# ---------------------------------------------------------------------------
#  WASAPI audio capture (the part ffmpeg can't do)
# ---------------------------------------------------------------------------
# ONE process-wide gate for PortAudio. Its initialise/terminate touch global
# state; two threads inside them at once corrupts the heap, which is what the
# ntdll access violation on a quick stop-then-start actually was.
_PA_GATE = threading.RLock()
# how long to let in-flight callbacks finish after the streams are closed.
# Measured against the crash: without it, terminate() could free structures a
# callback was still writing into.
_PA_SETTLE = 0.25


def _pa_open(pyaudio):
    """Enter PortAudio under the gate."""
    with _PA_GATE:
        return pyaudio.PyAudio()


def _pa_close(pa):
    """Leave PortAudio under the same gate, never twice."""
    if pa is None:
        return
    with _PA_GATE:
        try:
            pa.terminate()
        except Exception:
            pass


class AudioRecorder:
    """Captures system loopback (default playback device) and/or the mic to
    separate WAV files using WASAPI. No rerouting, no added latency."""

    def __init__(self, tmp_dir, tag="", game_pid=None):
        self.tmp_dir = tmp_dir
        self.tag = tag                       # per-run suffix so pause/resume parts don't clash
        self.game_pid = game_pid             # for the EXPERIMENTAL game-audio-only tap
        self._sys_done = False
        self._pa = None
        self._streams = []
        self._threads = []
        self._stop = threading.Event()
        self.system_wav = None
        self.mic_wav = None
        # In-memory rolling buffer of the most recent audio, per stream, so the
        # "save last minute" replay can be muxed without reading the live WAVs.
        self.rings = []          # list of dicts: kind, rate, channels, chunks, bytes, max
        self._ring_lock = threading.Lock()
        # Hold enough audio for the LONGEST clip any feature can ask for - the
        # replay length, the clip-hotkey length (up to 120s) and the Discord clip
        # length - not just the default, or a long clip would get full video but
        # truncated/silent audio.
        self._replay_seconds = max(
            60,
            int(SETTINGS.get("replay_seconds", 60)),
            int(SETTINGS.get("clip_hotkey_seconds", 60)),
            int(SETTINGS.get("discord_clip_seconds", 15)),
        ) + 5

    def _open_capture(self, dev, path, label, kind):
        import pyaudiowpatch as pyaudio
        import queue
        from collections import deque
        channels = max(1, int(dev["maxInputChannels"]))
        rate = int(dev["defaultSampleRate"])
        wf = wave.open(path, "wb")
        wf.setnchannels(channels)
        wf.setsampwidth(2)  # paInt16
        wf.setframerate(rate)

        ring = {"kind": kind, "rate": rate, "channels": channels,
                "chunks": deque(), "bytes": 0,
                "max": rate * channels * 2 * self._replay_seconds,
                "t_first": None, "frames": 0, "push": None, "frame_bytes": channels * 2}
        with self._ring_lock:
            self.rings.append(ring)

        # Bound the writer queue to ~60s of audio so a sustained disk stall can't grow
        # memory without limit (the ring is already bounded; the live-WAV queue was
        # not). Overflow happens only on a slow/full drive and is counted SEPARATELY
        # from WASAPI capture xruns, so the log stays diagnostic.
        qmax = max(256, int(rate * 60 / 4096) + 16)
        q = queue.Queue(maxsize=qmax)
        drops = {"n": 0}
        qdrops = {"n": 0}
        frame_bytes = channels * 2

        def _push(data):
            try:
                q.put_nowait(data)
            except queue.Full:
                qdrops["n"] += 1          # disk can't keep up; cap RAM (rare, catastrophic)
            with self._ring_lock:
                ring["chunks"].append(data)
                ring["bytes"] += len(data)
                while ring["bytes"] > ring["max"] and len(ring["chunks"]) > 1:
                    ring["bytes"] -= len(ring["chunks"].popleft())
        ring["push"] = _push              # signal_stop() uses it to fill the tail

        # Callback mode: WASAPI hands us audio the instant it's ready. The
        # callback only drops the bytes into a queue (fast, non-blocking); a
        # writer thread does the actual disk writing so the audio system is
        # never stalled. `status` is non-zero when WASAPI had data ready but we
        # weren't quick enough to take it - i.e. samples were LOST.
        #
        # SILENCE-GAP FILL: WASAPI *loopback* starves while the render engine is
        # idle (loading screens, menus, quiet moments) - callbacks pause or turn
        # up empty. Left as-is those wall-clock seconds are simply missing from
        # the WAV, so everything after a gap plays EARLY (and the old duration-
        # based sync then over-delayed the whole track: the '4-6 seconds late'
        # bug). Fix: count frames delivered and, on every callback, top the
        # stream up with real silence until it matches the wall clock since the
        # first sample - the WAV timeline then always equals wall time no matter
        # HOW the device starves.
        def callback(in_data, frame_count, time_info, status):
            now = time.time()
            if ring.get("closed"):
                return (None, pyaudio.paComplete)       # tail already sealed by stop
            if status:
                drops["n"] += 1
            nfr = len(in_data) // frame_bytes
            if ring["t_first"] is None:
                if not nfr:
                    return (None, pyaudio.paContinue)   # idle ticks before any audio
                ring["t_first"] = now - nfr / rate      # sync anchor: first REAL sample
                ring["frames"] = 0
            target = int((now - ring["t_first"]) * rate)
            miss = target - ring["frames"] - nfr
            if miss > rate * 0.25:                      # engine starved: true silence
                # fill the WHOLE gap (bounded pieces) - filling only 30s per
                # callback scattered post-gap audio as blips every 30s when
                # a source stayed silent for minutes
                miss = int(min(miss, rate * 14400))
                while miss > 0:
                    n = int(min(miss, rate * 30))
                    _push(b"\x00" * (n * frame_bytes))
                    ring["frames"] += n
                    miss -= n
            if nfr:
                _push(in_data)
                ring["frames"] += nfr
            return (None, pyaudio.paContinue)

        # A bigger buffer means the callback fires less often, which leaves far
        # more headroom against scheduling jitter while the GPU is busy encoding.
        # That headroom is what keeps the high-rate Sonar stream (8ch @ 96kHz)
        # from dropping samples and sounding robotic.
        stream = self._pa.open(
            format=pyaudio.paInt16, channels=channels, rate=rate,
            input=True, input_device_index=dev["index"],
            frames_per_buffer=4096, stream_callback=callback,
        )
        self._streams.append(stream)

        def writer():
            try:
                while not self._stop.is_set() or not q.empty():
                    try:
                        wf.writeframes(q.get(timeout=0.3))
                    except queue.Empty:
                        continue
            except Exception as e:
                # one write error used to kill this thread in silence while
                # the video kept encoding - a 3-hour session with audio
                # ending at minute 40 and nothing anywhere saying why
                log(f"Audio writer DIED mid-recording: {e} - this "
                    f"recording's sound ends early.")
            finally:
                try:
                    wf.close()
                except Exception:
                    pass
                if drops["n"]:
                    log(f"Audio WARNING: '{label}' had {drops['n']} capture xrun(s) "
                        f"- if it sounds choppy, this is why.")
                if qdrops["n"]:
                    log(f"Audio WARNING: '{label}' dropped {qdrops['n']} buffer(s) to a "
                        f"disk backlog (slow/full drive); memory was capped to protect the app.")

        t = threading.Thread(target=writer, daemon=True)
        t.start()
        self._threads.append(t)
        log(f"Audio: capturing {label} -> {channels}ch @ {rate}Hz")

    def _open_process_tap(self, pid, path):
        """EXPERIMENTAL game-audio-only: capture ONLY the given process tree's
        sound via WASAPI process loopback (proc-tap) instead of everything the
        speakers play - Discord/Spotify stay out of the video. Mirrors
        _open_capture's contract exactly: int16 WAV, replay ring, wall-clock
        silence-fill (process loopback delivers NOTHING while the game is
        silent - unfilled, the track would drift early, the same starvation
        bug the loopback path already solves). Returns True when the tap is
        live; the caller falls back to normal loopback on False."""
        try:
            from proctap import ProcessAudioCapture
            import numpy as np
            from collections import deque
            import queue
        except Exception as e:
            log(f"Game-audio tap unavailable ({e}); using system audio.")
            return False
        rate, channels = 48000, 2
        frame_bytes = channels * 2
        wf = wave.open(path, "wb")
        wf.setnchannels(channels)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        ring = {"kind": "system", "rate": rate, "channels": channels,
                "chunks": deque(), "bytes": 0,
                "max": rate * channels * 2 * self._replay_seconds,
                "t_first": None, "frames": 0, "push": None,
                "frame_bytes": frame_bytes}
        with self._ring_lock:
            self.rings.append(ring)
        q = queue.Queue(maxsize=4096)

        def _push(data):
            try:
                q.put_nowait(data)
            except queue.Full:
                pass
            with self._ring_lock:
                ring["chunks"].append(data)
                ring["bytes"] += len(data)
                while ring["bytes"] > ring["max"] and len(ring["chunks"]) > 1:
                    ring["bytes"] -= len(ring["chunks"].popleft())
        ring["push"] = _push

        def on_pcm(pcm, *_a):
            # float32 [-1,1] -> int16, then the same clock-fill discipline
            # as the WASAPI callback: the WAV timeline always equals wall
            # time, however the tap starves.
            now = time.time()
            if ring.get("closed"):
                return
            fl = np.frombuffer(pcm, dtype=np.float32)
            data = (np.clip(fl, -1.0, 1.0) * 32767.0).astype(np.int16).tobytes()
            nfr = len(data) // frame_bytes
            if ring["t_first"] is None:
                if not nfr:
                    return
                ring["t_first"] = now - nfr / rate
                ring["frames"] = 0
            target = int((now - ring["t_first"]) * rate)
            miss = target - ring["frames"] - nfr
            if miss > rate * 0.25:
                # whole-gap fill: a game can be silent for MINUTES (menus,
                # cutscenes) and the resumed audio must land exactly at its
                # wall-clock spot, not 30s at a time
                miss = int(min(miss, rate * 14400))
                while miss > 0:
                    n = int(min(miss, rate * 30))
                    _push(b"\x00" * (n * frame_bytes))
                    ring["frames"] += n
                    miss -= n
            if nfr:
                _push(data)
                ring["frames"] += nfr

        state = {"live": False, "err": None}

        def tap_thread():
            # dedicated clean thread: the tap initialises COM itself and must
            # not inherit pywebview's apartment
            tap = None
            try:
                tap = ProcessAudioCapture(int(pid), on_data=on_pcm)
                tap.start()
                # THE HONESTY CHECK: proctap's native layer silently falls
                # back to SYSTEM-WIDE loopback when process activation fails
                # (dead pid, protected process) - construction still
                # succeeds. Recording everything while labelled "game only"
                # is the exact opposite of the feature, so a non-specific
                # tap is treated as a failure and LORE's own loopback path
                # (which honours the user's device pick) takes over.
                try:
                    native = getattr(getattr(tap, "_backend", None),
                                     "_native", None)
                    if native is not None and hasattr(native,
                                                      "is_process_specific"):
                        if not native.is_process_specific():
                            raise RuntimeError(
                                "tap fell back to system-wide capture")
                except RuntimeError:
                    raise
                except Exception:
                    pass          # introspection unavailable: trust the tap
                state["live"] = True
            except Exception as e:
                state["err"] = e
                try:
                    if tap is not None:
                        tap.stop()
                        tap.close()
                except Exception:
                    pass
                return
            self._stop.wait()
            try:
                tap.stop()
                tap.close()
            except Exception:
                pass
        tt = threading.Thread(target=tap_thread, daemon=True)
        tt.start()
        self._threads.append(tt)
        # commit only once start() ran and the tap proved process-specific
        for _ in range(25):
            if state["err"] is not None or state["live"]:
                break
            time.sleep(0.1)
        if state["err"] is not None or not state["live"]:
            log(f"Game-audio tap failed to start ({state['err']}); "
                "using system audio.")
            ring["closed"] = True      # a late-finishing tap must push nothing
            with self._ring_lock:
                try:
                    self.rings.remove(ring)
                except ValueError:
                    pass
            try:
                wf.close()
                os.remove(path)
            except Exception:
                pass
            return False

        def writer():
            try:
                while not self._stop.is_set() or not q.empty():
                    try:
                        wf.writeframes(q.get(timeout=0.3))
                    except queue.Empty:
                        continue
            except Exception as e:
                # one write error used to kill this thread in silence while
                # the video kept encoding - a 3-hour session with audio
                # ending at minute 40 and nothing anywhere saying why
                log(f"Audio writer DIED mid-recording: {e} - this "
                    f"recording's sound ends early.")
            finally:
                try:
                    wf.close()
                except Exception:
                    pass
        t = threading.Thread(target=writer, daemon=True)
        t.start()
        self._threads.append(t)
        log(f"Audio: capturing the GAME's own sound only (pid {pid}).")
        return True

    def start(self):
        import pyaudiowpatch as pyaudio
        self._pa = _pa_open(pyaudio)
        wasapi = self._pa.get_host_api_info_by_type(pyaudio.paWASAPI)

        if SETTINGS["capture_system"] and SETTINGS.get("game_audio_only") \
                and getattr(self, "game_pid", None):
            self.system_wav = os.path.join(
                self.tmp_dir, f"system{('_' + self.tag) if self.tag else ''}.wav")
            if self._open_process_tap(self.game_pid, self.system_wav):
                self._sys_done = True
            else:
                self.system_wav = None      # fall through to normal loopback

        if SETTINGS["capture_system"] and not getattr(self, "_sys_done", False):
            # Which playback device to listen to: the user's explicit pick from
            # Settings > Audio, or the Windows default. (It was always the default
            # before, which looked random to anyone who switches outputs.)
            out = self._pa.get_device_info_by_index(wasapi["defaultOutputDevice"])
            want = str(SETTINGS.get("audio_output_device", "") or "").strip().lower()
            if want:
                for i in range(self._pa.get_device_count()):
                    d0 = self._pa.get_device_info_by_index(i)
                    if (d0.get("maxOutputChannels", 0) > 0
                            and not d0.get("isLoopbackDevice")
                            and want in str(d0.get("name", "")).lower()):
                        out = d0
                        break
                else:
                    log(f"Audio: chosen output '{want}' not found; using the default.")
            loop = None
            for d in self._pa.get_loopback_device_info_generator():
                if out["name"] in d["name"]:
                    loop = d
                    break
            if loop is None:  # fall back to first loopback device
                gen = self._pa.get_loopback_device_info_generator()
                loop = next(gen, None)
            if loop is not None:
                self.system_wav = os.path.join(
                    self.tmp_dir, f"system{('_' + self.tag) if self.tag else ''}.wav")
                self._open_capture(loop, self.system_wav, f"system ({out['name']})", "system")
            else:
                log("Audio: no WASAPI loopback device found; system sound skipped.")

        if SETTINGS["capture_mic"]:
            mic = self._resolve_mic(wasapi)
            if mic is not None:
                self.mic_wav = os.path.join(
                    self.tmp_dir, f"mic{('_' + self.tag) if self.tag else ''}.wav")
                self._open_capture(mic, self.mic_wav, f"mic ({mic['name']})", "mic")
            else:
                log("Audio: no microphone found; mic skipped.")

    def _resolve_mic(self, wasapi):
        want = SETTINGS["mic_name_contains"].strip().lower()
        if want:
            for i in range(self._pa.get_device_count()):
                d = self._pa.get_device_info_by_index(i)
                if d["maxInputChannels"] > 0 and not d.get("isLoopbackDevice") \
                        and want in d["name"].lower():
                    return d
        try:
            return self._pa.get_device_info_by_index(wasapi["defaultInputDevice"])
        except Exception:
            return None

    def first_sample_wallclock(self, kind):
        """Wall-clock time of this stream's first captured sample ('system'/'mic'),
        or None. The A/V sync anchors on this instead of guessing from durations."""
        with self._ring_lock:
            for r in self.rings:
                if r["kind"] == kind:
                    return r["t_first"]
        return None

    def signal_stop(self):
        """Tell capture threads to stop now (non-blocking), so audio and video
        stop at the same instant. First seals each ring (so a racing callback
        can't double-fill), then tops every stream up with silence to the current
        wall clock in small chunks - a recording that ENDS during a quiet stretch
        would otherwise have its last starved seconds missing from the WAV. The
        tail fill is capped at 2 minutes: beyond that the missing part is
        trailing silence anyway, and a multi-hour zero-buffer would spike RAM."""
        now = time.time()
        for r in list(self.rings):
            try:
                r["closed"] = True
                if r["t_first"] is not None and r["push"]:
                    miss = int((now - r["t_first"]) * r["rate"]) - r["frames"]
                    miss = min(miss, r["rate"] * 120)
                    while miss > 0:                              # 5s pieces
                        n = min(miss, r["rate"] * 5)
                        r["push"](b"\x00" * (n * r["frame_bytes"]))
                        r["frames"] += n
                        miss -= n
            except Exception:
                pass
        self._stop.set()

    def finalize(self):
        """Stop capture, then let writer threads flush the rest to disk."""
        if getattr(self, "_finalized", False):
            return                       # twice through here is a double-free
        self._finalized = True
        # Stop the callback streams first so they stop filling the queues...
        for s in self._streams:
            try:
                s.stop_stream()
            except Exception:
                pass
        # ...let any callback ALREADY RUNNING finish before the close. Closing
        # underneath a live callback is half of the crash.
        try:
            time.sleep(_PA_SETTLE)
        except Exception:
            pass
        for s in self._streams:
            try:
                s.close()
            except Exception:
                pass
        self._streams = []
        # ...then let the writer threads drain whatever's left and close files.
        for t in self._threads:
            t.join(timeout=10)
            if t.is_alive():
                log("Audio: a writer thread is still flushing after 10s (slow/full "
                    "disk); its track may be slightly truncated.")
        # and terminate under the gate, so a recording starting right now
        # cannot be inside PyAudio() while this one is inside terminate()
        _pa_close(self._pa)
        self._pa = None

    def stop(self):
        self.signal_stop()
        self.finalize()

    def dump_ring(self, out_dir, seconds, trim_tail=0.0):
        """Write the last `seconds` of buffered audio to WAV file(s). Returns
        (system_wav_or_None, mic_wav_or_None, ends) where ends maps
        'system'/'mic' to the WALL-CLOCK time of the written wav's LAST sample.
        That anchor is what lets the clip mux line audio up against the video's
        own wall-clock end instead of guessing - the guess ('trim half a
        segment') left clip audio 1-2s EARLY whenever the open segment was
        young. trim_tail still drops the most-recent N seconds first (the clip's
        video ends in the past; audio buffered beyond it is useless)."""
        sys_path = mic_path = None
        ends = {}
        # Snapshot under the lock with only a shallow ref-copy of each deque (fast),
        # then do the expensive b"".join OUTSIDE the lock so the audio callback isn't
        # blocked appending to the ring while a long clip is assembled (that block was
        # causing capture drops exactly when the user saved a clip). Bytes chunks are
        # immutable, so the joined result is identical to joining under the lock.
        # Top every ring up to NOW first: process-loopback (and starved
        # WASAPI) delivers nothing while the source is silent, so the ring's
        # newest bytes can be minutes old - a clip cut from that would lay
        # stale audio over silent footage. Bounded to the clip length.
        now = time.time()
        cap = int(max(1, seconds) + 5)
        with self._ring_lock:
            for r in self.rings:
                try:
                    if r.get("closed") or r["t_first"] is None or not r["push"]:
                        continue
                    miss = int((now - r["t_first"]) * r["rate"]) - r["frames"]
                    miss = min(miss, r["rate"] * cap)
                    while miss > 0:
                        n = min(miss, r["rate"] * 5)
                        r["push"](b"\x00" * (n * r["frame_bytes"]))
                        r["frames"] += n
                        miss -= n
                except Exception:
                    pass
            snap_refs = [(r["kind"], r["rate"], r["channels"], list(r["chunks"]),
                          r.get("t_first"), r.get("frames", 0))
                         for r in self.rings]
        snapshot = [(kind, rate, channels, b"".join(chunks), t0, frames)
                    for (kind, rate, channels, chunks, t0, frames) in snap_refs]
        for kind, rate, channels, data, t0, frames in snapshot:
            frame = channels * 2                     # bytes per sample frame
            drop = int(rate * channels * 2 * max(0.0, trim_tail))
            drop -= drop % frame
            dropped_sec = 0.0
            if 0 < drop < len(data):
                data = data[:-drop]                  # discard the newest audio
                dropped_sec = drop / float(rate * channels * 2)
            want = int(rate * channels * 2 * seconds)
            tail = data[-want:] if want < len(data) else data
            tail = tail[len(tail) % frame:]          # keep cut on a sample boundary
            path = os.path.join(out_dir, f"{kind}_clip.wav")
            try:
                wf = wave.open(path, "wb")
                wf.setnchannels(channels); wf.setsampwidth(2); wf.setframerate(rate)
                wf.writeframes(tail); wf.close()
            except Exception as e:
                log(f"Replay: could not write {kind} audio ({e})")
                continue
            # Wall-clock of the wav's last sample: ring start + frames delivered
            # (the silence top-up keeps 'frames' tracking wall time), minus what
            # trim_tail actually removed.
            if t0 is not None and frames:
                ends[kind] = t0 + frames / float(rate) - dropped_sec
            if kind == "system":
                sys_path = path
            else:
                mic_path = path
        return sys_path, mic_path, ends


def list_audio_devices():
    """(playback_outputs, microphones) - device-name lists for the Settings
    pickers. WASAPI devices only, loopback mirrors excluded. Safe on failure."""
    outs, mics = [], []
    try:
        import pyaudiowpatch as pyaudio
        pa = _pa_open(pyaudio)
        try:
            was = pa.get_host_api_info_by_type(pyaudio.paWASAPI)["index"]
            for i in range(pa.get_device_count()):
                d = pa.get_device_info_by_index(i)
                if d.get("hostApi") != was or d.get("isLoopbackDevice"):
                    continue
                name = str(d.get("name", "")).strip()
                if not name:
                    continue
                if d.get("maxOutputChannels", 0) > 0 and name not in outs:
                    outs.append(name)
                if d.get("maxInputChannels", 0) > 0 and name not in mics:
                    mics.append(name)
        finally:
            _pa_close(pa)
    except Exception as e:
        log(f"Audio device scan failed: {e}")
    return outs, mics


def diag_audio():
    load_settings()
    try:
        import pyaudiowpatch as pyaudio
    except ImportError:
        print("PyAudioWPatch not installed. Run:  pip install PyAudioWPatch")
        return
    p = _pa_open(pyaudio)
    wasapi = p.get_host_api_info_by_type(pyaudio.paWASAPI)
    out = p.get_device_info_by_index(wasapi["defaultOutputDevice"])
    inp = p.get_device_info_by_index(wasapi["defaultInputDevice"])
    print(f"\nDefault PLAYBACK (system sound will follow this): {out['name']}")
    print(f"Default MICROPHONE: {inp['name']}\n")
    print("Loopback devices (system capture uses one of these automatically):")
    for d in p.get_loopback_device_info_generator():
        print(f"  - {d['name']}")
    print("\nMicrophones / inputs you can target via 'mic_name_contains':")
    for i in range(p.get_device_count()):
        d = p.get_device_info_by_index(i)
        if d["maxInputChannels"] > 0 and not d.get("isLoopbackDevice"):
            print(f"  - {d['name']}")
    _pa_close(p)
    print("\nTip: to use your clean HyperX mic, set mic_name_contains to 'HyperX'.")


# ---------------------------------------------------------------------------
#  GPU / encoder auto-detection  (so it runs on AMD, NVIDIA, or Intel)
# ---------------------------------------------------------------------------
def get_screen_size():
    """Primary monitor pixel size (used only to probe the encoder at the real
    resolution - catches e.g. H.264's 4096px-wide hardware limit)."""
    if os.name == "nt":
        try:
            import ctypes
            try:
                ctypes.windll.user32.SetProcessDPIAware()
            except Exception:
                pass
            u = ctypes.windll.user32
            w, h = u.GetSystemMetrics(0), u.GetSystemMetrics(1)
            if w and h:
                return int(w), int(h)
        except Exception:
            pass
    return 1920, 1080


def _enumerate_active_monitors():
    r"""All currently-active display monitors, each as a dict:
        device  - the '\\.\DISPLAYn' GDI name
        num     - the trailing integer of that name (Windows' display number)
        rect    - (left, top, right, bottom) in virtual-desktop pixels
        primary - True for the primary monitor
    Returned in no particular order. Windows-only; [] elsewhere or on error."""
    mons = []
    if os.name != "nt":
        return mons
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        class MONITORINFOEXW(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD),
                        ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT),
                        ("dwFlags", wintypes.DWORD),
                        ("szDevice", ctypes.c_wchar * 32)]

        MONITORENUMPROC = ctypes.WINFUNCTYPE(
            ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.POINTER(wintypes.RECT), ctypes.c_void_p)
        handles = []

        def _cb(hmon, hdc, lprc, lparam):
            handles.append(hmon)
            return 1
        user32.EnumDisplayMonitors(None, None, MONITORENUMPROC(_cb), 0)
        for hmon in handles:
            mi = MONITORINFOEXW()
            mi.cbSize = ctypes.sizeof(MONITORINFOEXW)
            if user32.GetMonitorInfoW(ctypes.c_void_p(hmon), ctypes.byref(mi)):
                dev = mi.szDevice or ""
                digits = "".join(c for c in dev if c.isdigit())
                mons.append({
                    "device": dev,
                    "num": int(digits) if digits else 0,
                    "rect": (mi.rcMonitor.left, mi.rcMonitor.top,
                             mi.rcMonitor.right, mi.rcMonitor.bottom),
                    "work": (mi.rcWork.left, mi.rcWork.top,
                             mi.rcWork.right, mi.rcWork.bottom),
                    "primary": bool(mi.dwFlags & 1),
                })
    except Exception:
        return []
    return mons


def _active_monitor_count():
    """How many monitors the screen-grabber can address (>=1)."""
    return max(1, len(_enumerate_active_monitors()))


_DXGI_MAP = {"at": 0.0, "map": None}


def _dxgi_output_map():
    """{device name: ddagrab output_idx}, asked of DXGI itself.

    ddagrab counts outputs the way DXGI enumerates them, which has nothing
    to do with the number in a device name. The tome used to assume they
    matched; on a desk whose primary screen is DISPLAY2 they are inverted,
    and every capture went to the wrong monitor. Cached for a minute -
    enumerating COM objects on the watcher beat is rude. An empty dict on
    any failure, and the caller falls back to the old guess rather than
    refusing to record."""
    now = time.time()
    if _DXGI_MAP["map"] is not None and now - _DXGI_MAP["at"] < 60:
        return _DXGI_MAP["map"]
    out = {}
    if os.name != "nt":
        return out
    try:
        import ctypes
        from ctypes import POINTER, byref, c_void_p, c_uint
        import uuid as _uuid

        class _GUID(ctypes.Structure):
            _fields_ = [("d1", ctypes.c_ulong), ("d2", ctypes.c_ushort),
                        ("d3", ctypes.c_ushort), ("d4", ctypes.c_ubyte * 8)]

        class _RECT(ctypes.Structure):
            _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

        class _ODESC(ctypes.Structure):
            _fields_ = [("DeviceName", ctypes.c_wchar * 32),
                        ("DesktopCoordinates", _RECT),
                        ("AttachedToDesktop", ctypes.c_int),
                        ("Rotation", ctypes.c_uint),
                        ("Monitor", c_void_p)]

        g = _GUID()
        b = _uuid.UUID("770aae78-f26f-4dba-a829-253c83d1b387").bytes
        g.d1 = int.from_bytes(b[0:4], "big")
        g.d2 = int.from_bytes(b[4:6], "big")
        g.d3 = int.from_bytes(b[6:8], "big")
        for i in range(8):
            g.d4[i] = b[8 + i]

        fac = c_void_p()
        if ctypes.windll.dxgi.CreateDXGIFactory1(byref(g), byref(fac)) != 0:
            return out

        def _call(p, slot, restype, *args):
            vt = ctypes.cast(p, POINTER(POINTER(c_void_p)))[0]
            return ctypes.WINFUNCTYPE(restype, c_void_p, *args)(vt[slot])

        try:
            a = 0
            while True:
                ad = c_void_p()
                # EnumAdapters1 is slot 12, read as a plain long: the LAST
                # call always returns a failure code and an HRESULT
                # restype would raise on it
                if _call(fac, 12, ctypes.c_long, c_uint,
                         POINTER(c_void_p))(fac, a, byref(ad)) != 0:
                    break
                try:
                    o = 0
                    while True:
                        op = c_void_p()
                        if _call(ad, 7, ctypes.c_long, c_uint,
                                 POINTER(c_void_p))(ad, o, byref(op)) != 0:
                            break
                        try:
                            d = _ODESC()
                            _call(op, 7, ctypes.c_long,
                                  POINTER(_ODESC))(op, byref(d))
                            if d.DeviceName:
                                out[d.DeviceName] = o
                        finally:
                            _call(op, 2, ctypes.c_ulong)(op)
                        o += 1
                finally:
                    _call(ad, 2, ctypes.c_ulong)(ad)
                a += 1
        finally:
            _call(fac, 2, ctypes.c_ulong)(fac)
    except Exception:
        return {}
    _DXGI_MAP["map"] = out
    _DXGI_MAP["at"] = now
    return out


def _mon_output_idx(mon, fallback=0):
    """One monitor's ddagrab output index, or the old guess if DXGI is
    unreadable."""
    try:
        got = _dxgi_output_map().get(mon.get("device") or "")
        if got is not None:
            return int(got)
    except Exception:
        pass
    return int(fallback)


def _monitors_ranked():
    """Every active monitor, PRIMARY FIRST, then by display number.

    The setting has always said "0 = the primary screen". It ranked by the
    number in the device name instead, so on a desk whose primary is
    DISPLAY2 the default pointed at the other screen. Primary first makes
    that sentence true, and every rect check now reads the same list."""
    mons = _enumerate_active_monitors()
    if not mons:
        return []
    return sorted(mons, key=lambda m: (0 if m.get("primary") else 1,
                                       m.get("num", 0)))


def _capture_output_idx(idx=None):
    """The ddagrab output_idx for the screen the tome is set to record.

    The single place that turns "which monitor" into "which output"."""
    mons = _monitors_ranked()
    if not mons:
        return 0
    try:
        i = int(idx if idx is not None else SETTINGS.get("monitor_index", 0))
    except (TypeError, ValueError):
        i = 0
    i = min(max(0, i), len(mons) - 1)
    return _mon_output_idx(mons[i], i)


def _resolve_capture_monitor():
    """Which screen to capture. Simple and predictable: the monitor_index setting,
    where 0 = primary screen (the default). "Auto"/-1 also means the primary screen.
    No foreground-window guessing - that proved unreliable across mixed multi-monitor
    setups and could silently record the wrong screen."""
    try:
        idx = int(SETTINGS.get("monitor_index", 0))
    except Exception:
        idx = 0
    return idx if idx >= 0 else 0



def _hdr_active():
    """True if ANY active display currently has HDR (advanced colour) switched ON.
    Windows-only, and deliberately CONSERVATIVE: any uncertainty returns False, so
    it can never wrongly tone-map an ordinary SDR desktop. This is what lets Lore
    record correctly when Windows HDR is on even if the app's HDR toggle is off."""
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        QDC_ONLY_ACTIVE_PATHS = 2

        class LUID(ctypes.Structure):
            _fields_ = [("LowPart", wintypes.DWORD), ("HighPart", wintypes.LONG)]

        class SRC(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("statusFlags", wintypes.UINT)]

        class TGT(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("outputTechnology", wintypes.UINT),
                        ("rotation", wintypes.UINT), ("scaling", wintypes.UINT),
                        ("refreshNum", wintypes.UINT), ("refreshDen", wintypes.UINT),
                        ("scanline", wintypes.UINT), ("targetAvailable", wintypes.BOOL),
                        ("statusFlags", wintypes.UINT)]

        class PATH(ctypes.Structure):
            _fields_ = [("sourceInfo", SRC), ("targetInfo", TGT), ("flags", wintypes.UINT)]

        class MODE(ctypes.Structure):       # we only need the right size for the buffer
            _fields_ = [("infoType", wintypes.UINT), ("id", wintypes.UINT),
                        ("adapterId", LUID), ("blob", ctypes.c_byte * 64)]

        class HDR(ctypes.Structure):
            _fields_ = [("type", wintypes.UINT), ("size", wintypes.UINT),
                        ("adapterId", LUID), ("id", wintypes.UINT),
                        ("value", wintypes.UINT), ("colorEncoding", wintypes.UINT),
                        ("bitsPerColor", wintypes.UINT)]

        npaths, nmodes = wintypes.UINT(), wintypes.UINT()
        if user32.GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS,
                                              ctypes.byref(npaths), ctypes.byref(nmodes)) != 0:
            return False
        paths = (PATH * npaths.value)()
        modes = (MODE * nmodes.value)()
        if user32.QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS, ctypes.byref(npaths), paths,
                                     ctypes.byref(nmodes), modes, None) != 0:
            return False
        GET_ADVANCED_COLOR_INFO = 9
        for i in range(npaths.value):
            req = HDR()
            req.type = GET_ADVANCED_COLOR_INFO
            req.size = ctypes.sizeof(HDR)
            req.adapterId = paths[i].targetInfo.adapterId
            req.id = paths[i].targetInfo.id
            if user32.DisplayConfigGetDeviceInfo(ctypes.byref(req)) == 0:
                # bit0 = advancedColorSupported, bit1 = advancedColorEnabled (HDR on)
                if req.value & 0x2:
                    return True
        return False
    except Exception:
        return False


def _sdr_white_nits():
    """The Windows 'SDR content brightness' level in nits - the brightness an HDR
    desktop draws WHITE (255,255,255) at. This is THE anchor for converting an
    HDR recording back to a normal-looking SDR file: convert against a textbook
    reference (100 or 203 nits) instead and everything comes out 1.2-2.4x too
    bright ('mega blown out' - the 1.21-1.23 bug). Returns the LARGEST level
    across active displays (SDR-only displays report the 80-nit floor, the HDR
    display carries the real slider value), or None if the query fails.
    Verified against the dev G95SC: slider 40% -> SDRWhiteLevel 3000 -> 240.0."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        QDC_ONLY_ACTIVE_PATHS = 2

        class LUID(ctypes.Structure):
            _fields_ = [("LowPart", wintypes.DWORD), ("HighPart", wintypes.LONG)]

        class SRC(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("statusFlags", wintypes.UINT)]

        class TGT(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("outputTechnology", wintypes.UINT),
                        ("rotation", wintypes.UINT), ("scaling", wintypes.UINT),
                        ("refreshNum", wintypes.UINT), ("refreshDen", wintypes.UINT),
                        ("scanline", wintypes.UINT), ("targetAvailable", wintypes.BOOL),
                        ("statusFlags", wintypes.UINT)]

        class PATH(ctypes.Structure):
            _fields_ = [("sourceInfo", SRC), ("targetInfo", TGT), ("flags", wintypes.UINT)]

        class MODE(ctypes.Structure):
            _fields_ = [("infoType", wintypes.UINT), ("id", wintypes.UINT),
                        ("adapterId", LUID), ("blob", ctypes.c_byte * 64)]

        class SDRW(ctypes.Structure):   # DISPLAYCONFIG_SDR_WHITE_LEVEL
            _fields_ = [("type", wintypes.UINT), ("size", wintypes.UINT),
                        ("adapterId", LUID), ("id", wintypes.UINT),
                        ("SDRWhiteLevel", wintypes.ULONG)]

        npaths, nmodes = wintypes.UINT(), wintypes.UINT()
        if user32.GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS,
                                              ctypes.byref(npaths), ctypes.byref(nmodes)) != 0:
            return None
        paths = (PATH * npaths.value)()
        modes = (MODE * nmodes.value)()
        if user32.QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS, ctypes.byref(npaths), paths,
                                     ctypes.byref(nmodes), modes, None) != 0:
            return None
        GET_SDR_WHITE_LEVEL = 11
        best = None
        for i in range(npaths.value):
            req = SDRW()
            req.type = GET_SDR_WHITE_LEVEL
            req.size = ctypes.sizeof(SDRW)
            req.adapterId = paths[i].targetInfo.adapterId
            req.id = paths[i].targetInfo.id
            if user32.DisplayConfigGetDeviceInfo(ctypes.byref(req)) == 0:
                nits = req.SDRWhiteLevel * 80.0 / 1000.0   # units of 1/1000 of 80 nits
                if nits > 0 and (best is None or nits > best):
                    best = nits
        return best
    except Exception:
        return None


_FILTER_CACHE = {}


def _has_filter(name):
    """Does the bundled ffmpeg have this filter? Probed once per session."""
    v = _FILTER_CACHE.get(name)
    if v is not None:
        return v
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([SETTINGS["ffmpeg_path"], "-hide_banner", "-h", f"filter={name}"],
                           capture_output=True, text=True, timeout=10, creationflags=flags)
        v = (r.returncode == 0 and "Unknown filter" not in (r.stderr or "")
             and "Unknown filter" not in (r.stdout or ""))
    except Exception:
        v = False
    _FILTER_CACHE[name] = v
    return v


def _hdr_strategy():
    """How this capture should handle an HDR desktop:
      None      - no HDR handling (SDR desktop, or the user turned it off)
      'native'  - capture the float16 (scRGB) desktop surface zero-copy into an
                  AMF encoder, producing a TRUE 10-bit HDR10 (PQ/BT.2020) file.
    Why float16 is not optional: the colour-patch lab proved every other ddagrab
    readback of an HDR desktop (8-bit AND 10-bit) is LINEAR light hard-clipped at
    80 nits by Windows - most of the image is destroyed before any filter can
    touch it. That clipped source is what made 1.16-1.23 HDR washed/neon under
    every tone-map curve tried. Only AMF encoders accept the float16 surface on
    the GPU, so 'native' applies only to them; everything else records plain
    (build_video_cmd handles that), which is flat-ish but never neon.
    Accepts legacy values (bool / 'on' / 'tonemap')."""
    mode = str(SETTINGS.get("hdr_mode", "auto")).strip().lower()
    if mode in ("off", "false", "0", "no"):
        return None
    return "native" if _hdr_active() else None


def _enc_supports_10bit(enc):
    """Can this encoder produce a real 10-bit stream? Native HDR must never be
    attempted on 8-bit-only encoders (h264_nvenc, h264_amf, libx264) - the run
    would just die and burn a retry cycle on every recording."""
    e = (enc or "").lower()
    return ("av1" in e) or ("hevc" in e) or ("265" in e)


def _hdr_native_args(grab, enc_name=""):
    """(filtergraph, extra encoder args, global pre-args) for native HDR capture
    on an AMF encoder - the ONLY encoder family here that accepts the float16
    scRGB desktop surface directly (zero-copy d3d11; measured the same speed
    class as plain capture on the dev RX 9070 XT, and bit-exact PQ against the
    drawn-patch lab: white 255 -> 255, grey 128 -> 129 after finishing).

    The pieces, each load-bearing:
      * output_fmt=16bit    - the float16 surface; the only UNCLIPPED source.
      * -init_hw_device...  - a shared d3d11 device; without it AMF refuses the
                              float16 frames outright ('Invalid argument').
      * -bitdepth 10 / main10 - with 10-bit output AMF PQ-encodes the linear
                              floats at the true scRGB scale (1.0 = 80 nits,
                              verified against PQ maths to within quantisation).
      * the metadata BSF    - AMF stamps the container 'linear/gbr', which is
                              wrong; the BSF writes PQ/BT.2020 into the actual
                              bitstream header, which is what decoders trust."""
    if enc_name.startswith("av1"):
        depth = ["-bitdepth", "10"]
        bsf = ["-bsf:v", "av1_metadata=color_primaries=9:"
               "transfer_characteristics=16:matrix_coefficients=9:color_range=tv"]
    else:                                   # hevc_amf
        depth = ["-profile:v", "main10"]
        bsf = ["-bsf:v", "hevc_metadata=colour_primaries=9:"
               "transfer_characteristics=16:matrix_coefficients=9"]
    pre = ["-init_hw_device", "d3d11va=dd", "-filter_hw_device", "dd"]
    vf = f"{grab}:output_fmt=16bit[v]"
    return vf, depth + bsf, pre


def _hdr_to_sdr_vf(trc, nits=None):
    """The ONE offline HDR->SDR conversion used everywhere (finishing queue,
    Discord copies, thumbnails), so every consumer produces the same colours.
    Validated absolutely against drawn patches on the dev machine: white 255 ->
    255, grey 180 -> 180, grey 128 -> 129, red (255,0,0) -> (252,6,4).

    The recipe (each part fixes a measured failure - don't 'improve' casually):
      * setparams when the container says 'linear' - our own recordings: AMF
        writes real PQ/BT.2020 pixels but mislabels the container; concat-copied
        segments keep that label. Forcing the true interpretation makes the
        chain deterministic even if a decoder ignores the (correct) bitstream
        header that the recording BSF wrote.
      * npl = the Windows SDR white level AT RECORD TIME (the nits argument;
        falls back to querying now, then 240). PQ is absolute: dividing by the
        wrong white is exactly the old 'mega blown out' bug - npl=100 lifted a
        240-nit desktop 2.4x.
      * tonemap=clip:desat=0 - highlights above SDR white clip, exactly like an
        SDR monitor would show them. desat=0 matters: the filter's DEFAULT
        desat=2 bleeds blue into bright yellows/reds (measured +65/255 blue).
      * output transfer iec61966-2-1 (sRGB) - matches how the desktop actually
        displayed the content; the classic bt709 camera curve measured ~+7 too
        bright on every mid grey."""
    n = 240
    try:
        n = int(round(float(nits))) if nits else int(round(_sdr_white_nits() or 240))
    except Exception:
        pass
    n = max(80, min(1000, n))
    pre = ""
    if (trc or "").strip().lower() == "linear":
        pre = ("setparams=color_primaries=bt2020:color_trc=smpte2084:"
               "colorspace=bt2020nc,")
    return (pre + f"zscale=t=linear:npl={n},"
            "tonemap=tonemap=clip:param=1.0:desat=0,"
            "zscale=p=bt709:t=iec61966-2-1:m=bt709:r=tv")


def _is_hdr_trc(trc):
    """Is this transfer tag one of our HDR recordings? 'smpte2084'/'arib-std-b67'
    are real HDR labels; 'linear' is what AMF stamps on the CONTAINER of our
    float16-native recordings (the bitstream itself is PQ - see _hdr_native_args)."""
    return (trc or "").strip().lower() in ("smpte2084", "arib-std-b67", "linear")


def detect_gpu_vendor():
    """Return 'amd' / 'nvidia' / 'intel' / None by asking Windows what display
    adapter is installed. Prefers a discrete GPU when more than one is listed."""
    if os.name != "nt":
        return None
    try:
        flags = subprocess.CREATE_NO_WINDOW
        out = subprocess.run(
            ["powershell", "-NoProfile", "-Command",
             "Get-CimInstance Win32_VideoController | "
             "Select-Object -ExpandProperty Name"],
            capture_output=True, text=True, timeout=6, creationflags=flags
        ).stdout.lower()
    except Exception:
        out = ""
    if any(k in out for k in ("nvidia", "geforce", "rtx", "gtx")):
        return "nvidia"
    if any(k in out for k in ("radeon", "amd", "rx ")):
        return "amd"
    if any(k in out for k in ("intel", "arc", "iris", "uhd graphics")):
        return "intel"
    return None


def _encoder_works(enc, w, h, fps):
    """True if this encoder actually initialises on this machine. Feeds it a few
    synthetic nv12 frames at the real resolution - the same pixel format the real
    capture delivers - so a pass is representative."""
    if enc in _BAD_ENCODERS:
        return False
    cmd = [SETTINGS["ffmpeg_path"], "-hide_banner", "-loglevel", "error",
           "-f", "lavfi", "-i", f"color=c=black:s={w}x{h}:r={fps}",
           "-vf", "format=nv12", "-frames:v", "3", "-c:v", enc, "-f", "null", "-"]
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        return subprocess.run(cmd, capture_output=True, timeout=40,
                              creationflags=flags).returncode == 0
    except Exception:
        return False


def choose_encoder(vendor, w, h, fps, prefer_av1=True):
    """Pick the best WORKING encoder for this GPU. Tries the vendor's AV1 then
    HEVC hardware encoder, then any other vendor's HEVC (in case detection was
    off), then guarantees a result with software encoding. Encoders that died at
    runtime earlier this session (_BAD_ENCODERS) are skipped."""
    fam = {
        "amd":    ["av1_amf", "hevc_amf"],
        "nvidia": ["av1_nvenc", "hevc_nvenc"],
        "intel":  ["av1_qsv", "hevc_qsv"],
    }.get(vendor, [])
    if not prefer_av1:
        fam = [e for e in fam if not e.startswith("av1")]
    # Cross-vendor fallback. Include the hardware AV1 encoders here too (when AV1 is
    # wanted) so a machine whose GPU vendor couldn't be detected (e.g. PowerShell/WMI
    # locked down) still tries hardware AV1 before dropping to CPU software. The
    # h264 HARDWARE encoders come before software: an older GPU (GTX 6xx-9xx,
    # pre-Skylake Intel) still beats libx264 trying to chase 60fps on the CPU.
    tail = (["av1_amf", "av1_nvenc", "av1_qsv"] if prefer_av1 else []) \
        + ["hevc_amf", "hevc_nvenc", "hevc_qsv",
           "h264_nvenc", "h264_qsv", "h264_amf", "libx265", "libx264"]
    seen, order = set(), []
    for e in fam + tail:
        if e not in seen and e not in _BAD_ENCODERS:
            seen.add(e); order.append(e)
    for enc in order:
        if _encoder_works(enc, w, h, fps):
            return enc
    return "libx264"  # last resort; always present in a full ffmpeg build


def _capture_screen_size():
    """A representative resolution for the encoder probe. The capture target may be a
    secondary monitor LARGER than the primary, so probe at the biggest active monitor
    (and never below the primary) - that keeps the H.264 4096px-wide guard meaningful
    when capturing a 4K/ultrawide secondary. Falls back to the primary on any error."""
    pw, ph = get_screen_size()
    try:
        mons = _enumerate_active_monitors()
        if mons:
            w = max((m["rect"][2] - m["rect"][0]) for m in mons)
            h = max((m["rect"][3] - m["rect"][1]) for m in mons)
            return max(w, pw), max(h, ph)
    except Exception:
        pass
    return pw, ph


def resolve_encoder():
    """Turn the 'encoder' setting (auto / av1 / hevc / explicit) into a concrete
    encoder that works on THIS machine, and cache it for the session."""
    pref = str(SETTINGS.get("encoder", "auto")).lower()
    w, h = _capture_screen_size()
    fps = int(SETTINGS["framerate"])
    if pref in ("auto", "av1", "hevc"):
        vendor = detect_gpu_vendor()
        enc = choose_encoder(vendor, w, h, fps, prefer_av1=(pref != "hevc"))
        log(f"GPU detected: {vendor or 'unknown'} -> encoder '{enc}' @ {w}x{h}/{fps}")
    elif _encoder_works(pref, w, h, fps):
        enc = pref
    else:
        vendor = detect_gpu_vendor()
        enc = choose_encoder(vendor, w, h, fps, True)
        log(f"Encoder '{pref}' didn't work here; falling back to '{enc}'")
    SETTINGS["_encoder_resolved"] = enc
    return enc


def _current_encoder():
    return SETTINGS.get("_encoder_resolved") or resolve_encoder()


def _ffmpeg_ok():
    """Quick one-shot check that the ffmpeg binary actually runs. Lets a missing or
    antivirus-quarantined ffmpeg surface as a plain-language message at startup
    instead of degrading into a permanent, silent 'never records'."""
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([SETTINGS["ffmpeg_path"], "-version"],
                           capture_output=True, timeout=10, creationflags=flags)
        return r.returncode == 0
    except Exception:
        return False


def encoder_quality_flags(enc, br):
    """Rate-control + quality flags, tuned for QUALITY PER GIGABYTE: peak-constrained
    VBR instead of CBR, so quiet scenes stop burning bits and busy scenes may borrow
    up to 2x the target. Real files come out well under the old CBR sizes at equal
    or better quality. The option NAMES differ per encoder family, so this can't be
    shared - AMF uses -quality, NVENC uses -preset pN, etc."""
    q = SETTINGS["amf_quality"]
    vbr = ["-b:v", f"{br}M", "-maxrate", f"{br * 2}M", "-bufsize", f"{br * 4}M"]
    if enc.endswith("_amf"):
        return ["-rc", "vbr_peak", *vbr, "-quality", q]
    if enc.endswith("_nvenc"):
        preset = {"speed": "p1", "balanced": "p4", "quality": "p7"}.get(q, "p4")
        return ["-rc", "vbr", *vbr, "-preset", preset]
    if enc.endswith("_qsv"):
        preset = {"speed": "veryfast", "balanced": "medium", "quality": "slower"}.get(q, "medium")
        return [*vbr, "-preset", preset]
    # software libx264 / libx265: constant-quality capped at the same peak
    preset = {"speed": "veryfast", "balanced": "medium", "quality": "slow"}.get(q, "medium")
    return ["-crf", "23", "-maxrate", f"{br * 2}M", "-bufsize", f"{br * 4}M",
            "-preset", preset]


# ---------------------------------------------------------------------------
#  ffmpeg: video capture + final mux
# ---------------------------------------------------------------------------
def _game_window_title(pname):
    """Title of the given process's biggest visible top-level window, or None.
    Used by the EXPERIMENTAL window-only capture scope to aim gdigrab."""
    if os.name != "nt" or not pname:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        pids = set()
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    pids.add(pr.info["pid"])
            except Exception:
                pass
        if not pids:
            return None
        best = {"area": 0, "title": None}

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if not user32.IsWindowVisible(h) or user32.IsIconic(h):
                    return 1
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if pid.value not in pids:
                    return 1
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                area = max(0, r.right - r.left) * max(0, r.bottom - r.top)
                if area <= best["area"]:
                    return 1
                n = user32.GetWindowTextLengthW(h)
                if n <= 0:
                    return 1
                buf = ctypes.create_unicode_buffer(n + 1)
                user32.GetWindowTextW(h, buf, n + 1)
                if buf.value:
                    best["area"] = area
                    best["title"] = buf.value
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return best["title"]
    except Exception:
        return None


def _pid_for_exe(pname):
    """First live pid with this exe name, or None. Used to aim the
    game-audio-only tap (process loopback captures the pid + its children,
    so the main process is the right target even for launcher-spawned
    games)."""
    if not pname:
        return None
    try:
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    return pr.info["pid"]
            except Exception:
                pass
    except Exception:
        pass
    return None


def _screen_capture_wh(mon_idx):
    """Pixel size of the screen a screen-scope session records. A capture
    restart may only continue the SAME file while this is unchanged: the
    runs are joined with -c copy, and two frame sizes in one stream make an
    unplayable video. Ranked by display number, the ddagrab output_idx
    contract. None when it can't be determined (caller then plays safe)."""
    # Retried: this is asked precisely WHILE the display mode is changing,
    # and a single failed enumeration then would read as "the screen changed
    # shape" and split the recording - the exact symptom being fixed.
    for attempt in range(3):
        try:
            mons = _monitors_ranked()
            if mons:
                m = mons[min(max(0, int(mon_idx or 0)), len(mons) - 1)]
                r = m["rect"]
                return (r[2] - r[0], r[3] - r[1])
        except Exception:
            pass
        if attempt < 2:
            time.sleep(0.2)
    return None


def _hdr_run_flag():
    """Will the NEXT capture run record true HDR? Mirrors build_video_cmd's
    gate exactly (float16 only rides a 10-bit-capable AMF encoder). A
    restart may only continue the same file while this is unchanged - an
    HDR run and an SDR run cannot be concatenated by stream copy."""
    try:
        strat = _hdr_strategy()
        enc_now = _current_encoder()
        if strat == "native" and not (enc_now.endswith("_amf")
                                      and _enc_supports_10bit(enc_now)):
            strat = None
        return bool(strat and _HDR_LEVEL[0] < 1)
    except Exception:
        return False


def _game_window_rect(pname, hwnd=None):
    """Where the given game's window is RIGHT NOW, as a capture rect:
        {"hwnd", "mon" (ddagrab output index), "x", "y", "w", "h"}
      or {"hwnd", "iconic": True}   while the window is minimised
      or None                       when the process has no usable window.
    x/y/w/h are the window's CLIENT area (the game's picture, no title bar)
    in monitor-relative physical pixels, clamped to the screen and aligned
    for the encoder (offsets even, size mod-8 - AMF pads odd sizes up, which
    would smuggle dead pixel columns in and shift dims between runs).
    Used by the EXPERIMENTAL window-only capture scope: the rect crops the
    same GPU desktop-duplication capture the whole screen uses, so HDR and
    zero-copy encoding keep working. Pass the previous poll's hwnd - it is
    revalidated cheaply and the full window hunt runs only when it died
    (games recreate their window on display-mode switches)."""
    if os.name != "nt" or not pname:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        # ddagrab captures PHYSICAL pixels, but a system-DPI-aware process
        # reads VIRTUALISED rects for windows on monitors whose scale differs
        # from the system DPI (a game on a 150% 4K next to a 100% primary
        # would get a rect ~2/3 its real size - the file would hold only part
        # of the game). Flip just this thread to per-monitor awareness while
        # measuring; restored below. Pre-1703 Windows: quietly skipped -
        # single-scale setups were already correct there.
        oldctx = None
        try:
            user32.SetThreadDpiAwarenessContext.restype = ctypes.c_void_p
            user32.SetThreadDpiAwarenessContext.argtypes = [ctypes.c_void_p]
            oldctx = user32.SetThreadDpiAwarenessContext(ctypes.c_void_p(-4))
        except Exception:
            oldctx = None
        try:
            h = None
            icon_h = None
            if hwnd:
                try:
                    if user32.IsWindow(hwnd) and user32.IsWindowVisible(hwnd):
                        pid = wintypes.DWORD()
                        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                        if (pid.value
                                and psutil.Process(pid.value).name().lower()
                                == pname.lower()):
                            h = hwnd
                except Exception:
                    h = None
            if h is None:
                pids = set()
                for pr in psutil.process_iter(["pid", "name"]):
                    try:
                        if (pr.info.get("name") or "").lower() == pname.lower():
                            pids.add(pr.info["pid"])
                    except Exception:
                        pass
                if not pids:
                    return None
                best = {"area": 0, "hwnd": None, "icon": None}

                @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
                def _enum(hw, _l):
                    try:
                        if not user32.IsWindowVisible(hw):
                            return 1
                        pid = wintypes.DWORD()
                        user32.GetWindowThreadProcessId(hw, ctypes.byref(pid))
                        if pid.value not in pids:
                            return 1
                        if user32.IsIconic(hw):
                            # minimised counts (it pauses capture) - tracked
                            # apart so a tiny visible stub window (a crash
                            # handler, a notifier) can't make the real,
                            # minimised game look 'gone'
                            if best["icon"] is None:
                                best["icon"] = hw
                            return 1
                        r = wintypes.RECT()
                        user32.GetWindowRect(hw, ctypes.byref(r))
                        area = (max(0, r.right - r.left)
                                * max(0, r.bottom - r.top))
                        if area > best["area"]:
                            best["area"] = area
                            best["hwnd"] = hw
                    except Exception:
                        pass
                    return 1
                user32.EnumWindows(_enum, 0)
                h = best["hwnd"] or best["icon"]
                icon_h = best["icon"]
            if h is None:
                return None
            if user32.IsIconic(h):
                return {"hwnd": h, "iconic": True}
            cr = wintypes.RECT()
            if not user32.GetClientRect(h, ctypes.byref(cr)):
                return None
            pt = wintypes.POINT(0, 0)
            if not user32.ClientToScreen(h, ctypes.byref(pt)):
                return None
            x, y = pt.x, pt.y
            w, hh = cr.right - cr.left, cr.bottom - cr.top
            if w < 64 or hh < 64:
                # the visible winner is a stub; honour a minimised sibling so
                # capture pauses instead of falling back to the whole screen
                if icon_h:
                    return {"hwnd": icon_h, "iconic": True}
                return None

            # which screen the window lives on -> the matching ddagrab
            # output. Ranked by display number: the same contract every other
            # output_idx consumer uses (_watched_monitor_rect and friends) -
            # raw EnumDisplayMonitors order is NOT guaranteed to match it.
            class MI(ctypes.Structure):
                _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                            ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]
            hm = user32.MonitorFromWindow(h, 2)      # MONITOR_DEFAULTTONEAREST
            mi = MI()
            mi.cbSize = ctypes.sizeof(MI)
            if not user32.GetMonitorInfoW(hm, ctypes.byref(mi)):
                return None
            mrect = (mi.rcMonitor.left, mi.rcMonitor.top,
                     mi.rcMonitor.right, mi.rcMonitor.bottom)
            # WHICH OUTPUT, NOT WHICH RANK. This matched the window's
            # monitor against a list sorted by device number and gave
            # ddagrab that position. DXGI numbers its outputs its own way,
            # so on his desk a game on the main screen was captured from
            # the second one - the screen his own window was filling,
            # which is how the tome ended up inside his recordings.
            mons = _monitors_ranked()
            mon = 0
            for i, m in enumerate(mons):
                if tuple(m["rect"]) == mrect:
                    mon = _mon_output_idx(m, i)
                    break
            cx, cy = max(x, mrect[0]), max(y, mrect[1])
            cw = min(x + w, mrect[2]) - cx
            ch = min(y + hh, mrect[3]) - cy
            ox, oy = cx - mrect[0], cy - mrect[1]
            ox -= ox % 2
            oy -= oy % 2
            cw -= cw % 8
            ch -= ch % 8
            if cw < 160 or ch < 120:
                return None  # off-screen sliver / splash remnant - not the game
            return {"hwnd": h, "mon": mon, "x": ox, "y": oy, "w": cw, "h": ch}
        finally:
            if oldctx:
                try:
                    user32.SetThreadDpiAwarenessContext(oldctx)
                except Exception:
                    pass
    except Exception:
        return None


def build_video_cmd(out_pattern, start_number=0, monitor_index=None,
                    window_rect=None):
    """Capture the screen and encode it, writing the stream as a sequence of
    short MP4 segments (out_pattern like '.../seg_%06d.mp4'). Segments let us
    (a) concat them into the full session file at the end, (b) grab just the
    last minute on demand for the replay hotkey, and (c) continue numbering
    after a pause - all without re-encoding. start_number is where this run's
    segment numbering begins (so a resumed run doesn't overwrite earlier ones).
    monitor_index overrides which screen to grab; None falls back to settings.
    window_rect=(x, y, w, h) crops the capture AT THE SOURCE to the game's
    window (monitor-relative, from _game_window_rect): the same GPU
    duplication capture, so zero-copy encoding and HDR keep working - unlike
    the old gdigrab path, which returned black frames for modern games."""
    s = SETTINGS
    enc = _current_encoder()
    br = s["bitrate_mbps"]
    safe = _ENC_SAFE[0]
    mon = monitor_index if monitor_index is not None else s.get("monitor_index", 0)
    try:
        mon = int(mon)
    except Exception:
        mon = 0
    if mon < 0:
        mon = 0   # "Auto" records the primary screen (output 0) - simple and reliable
    # Never ask ddagrab for a screen that doesn't exist (a stale saved index, or a
    # monitor that was unplugged) - clamp to the real screen count so capture still
    # starts on a valid output instead of failing outright.
    mon = min(mon, _active_monitor_count() - 1)
    grab = f"ddagrab=output_idx={mon}:framerate={s['framerate']}"
    if window_rect:
        x, y, w, h = window_rect
        grab += f":offset_x={x}:offset_y={y}:video_size={w}x{h}"

    hdr_enc_args = []
    hdr_pre_args = []
    strategy = None if _HDR_LEVEL[0] >= 1 else _hdr_strategy()
    if strategy == "native" and not (enc.endswith("_amf") and _enc_supports_10bit(enc)):
        # Only AMF encoders accept the float16 surface (the sole unclipped HDR
        # source - see _hdr_strategy). Everyone else records plain SDR capture:
        # slightly flat on an HDR desktop, but stable and never neon.
        strategy = None
    if strategy == "native":
        # True HDR file: the float16 scRGB surface goes zero-copy into the AMF
        # encoder, which PQ-encodes it (verified bit-exact against PQ maths).
        # The finishing queue converts it to normal SDR right after the session.
        # If the chain yields zero frames, the watcher steps _HDR_LEVEL to plain.
        vf, hdr_enc_args, hdr_pre_args = _hdr_native_args(grab, enc)
        # Give the HDR master a bitrate FLOOR: it lives through one more encode
        # generation (the SDR finishing pass) than a normal recording, so the
        # master must not be the quality bottleneck - the finished file should
        # be bounded by the user's own bitrate. Costs disk only TEMPORARILY:
        # finishing re-encodes at the user's bitrate and replaces this file.
        br = max(int(br), 30)
    elif enc.endswith(("_amf", "_nvenc")) and not safe:
        # AMF and NVENC consume ddagrab's d3d11 frames directly (zero-copy, most
        # efficient). On fragile setups (some 4K AMD combos, hybrid laptops where
        # capture runs on the iGPU and NVENC on the dGPU) this fast path can fail
        # to start - the encoder-died recovery then retries in 'safe' mode below
        # and remembers it, so it self-heals after one lost start, once ever.
        vf = f"{grab}[v]"
    else:
        # NVENC / QSV / software (and AMF in safe mode) take frames in system
        # memory as nv12 - the most compatible path.
        vf = f"{grab},hwdownload,format=bgra,format=nv12[v]"

    seg = max(2, int(s.get("segment_seconds", 4)))
    fps = int(s["framerate"])
    gop = max(1, fps * seg)
    # Force a keyframe on each segment boundary so cuts land on time. Some
    # encoders choke on the expression form, so safe mode relies on -g alone.
    keyframes = [] if safe else ["-force_key_frames", f"expr:gte(t,n_forced*{seg})"]
    # Safe mode also drops encoder-specific tuning (-quality/-preset/-rc), which
    # can be rejected by some driver/ffmpeg combos, for plain CBR.
    rc = (["-b:v", f"{br}M", "-maxrate", f"{br}M", "-bufsize", f"{br * 2}M"]
          if safe else encoder_quality_flags(enc, br))
    tail = [
        "-c:v", enc,
        *rc,
        *hdr_enc_args,                 # 10-bit depth + PQ/BT.2020 bitstream tags
        "-g", str(gop), *keyframes,
        # MP4 segments work for AV1 / HEVC / H.264 alike (MPEG-TS can't carry
        # AV1, which is what AMD GPUs pick by default - that broke saving).
        # hybrid_fragmented (2.0): each segment is written as a fragmented
        # file and converted to plain MP4 when it closes - a hard crash or
        # power cut mid-segment now loses NOTHING (the tail segment stays a
        # valid fMP4 the salvage weld reads normally). Finished segments are
        # byte-identical plain MP4s, so nothing downstream changes.
        "-f", "segment", "-segment_time", str(seg),
        "-segment_format", "mp4", "-reset_timestamps", "1",
        "-segment_format_options", "movflags=+hybrid_fragmented",
        "-segment_start_number", str(int(start_number)),
        out_pattern,
    ]
    return [
        s["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error", "-stats",
        *hdr_pre_args,                 # shared d3d11 device (float16 HDR capture only)
        "-filter_complex", vf,
        "-map", "[v]",
        *tail,
    ]


def build_wgc_cmd(w, h, fps, out_pattern, start_number=0):
    """ffmpeg tail for the WGC (Windows Graphics Capture) transport: raw
    BGRA frames arrive on stdin from _WGCFeed and everything downstream -
    encoder flags, GOP, keyframes, 4s MP4 segments - matches
    build_video_cmd exactly, so replay clips, pause/resume and the save
    pipeline never know which transport recorded the footage. bgr0 goes
    STRAIGHT into the AMF encoder (it accepts RGB natively) - the
    BGRA->NV12 conversion happens on the GPU, not in Python or swscale."""
    s = SETTINGS
    enc = _current_encoder()
    br = s["bitrate_mbps"]
    safe = _ENC_SAFE[0]
    seg = max(2, int(s.get("segment_seconds", 4)))
    gop = max(1, fps * seg)
    keyframes = [] if safe else ["-force_key_frames", f"expr:gte(t,n_forced*{seg})"]
    rc = (["-b:v", f"{br}M", "-maxrate", f"{br}M", "-bufsize", f"{br * 2}M"]
          if safe else encoder_quality_flags(enc, br))
    return [
        s["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error", "-stats",
        "-f", "rawvideo", "-pixel_format", "bgr0",
        "-video_size", f"{w}x{h}", "-framerate", str(fps),
        # WHY THE AUDIO USED TO DRIFT. rawvideo carries no timestamps, so
        # ffmpeg stamped frame N at exactly N/fps - the rate we ASKED for.
        # The audio is captured separately against the wall clock. So any
        # stretch where the window did not actually deliver 60 fps made the
        # picture's clock run slow while the sound's kept real time, and the
        # two slid apart for the rest of the recording. Measured on a real
        # session: 58.9 fps delivered, 5.4 seconds adrift by the end.
        # Wall-clock stamps in, constant rate out: frames are timed by when
        # they ARRIVED, then resampled to an exactly-60fps output so the
        # segment weld still has one unchanging frame rate to copy.
        "-use_wallclock_as_timestamps", "1",
        "-i", "pipe:0",
        "-fps_mode", "cfr", "-r", str(fps),
        "-c:v", enc, *rc,
        "-g", str(gop), *keyframes,
        "-f", "segment", "-segment_time", str(seg),
        "-segment_format", "mp4", "-reset_timestamps", "1",
        "-segment_format_options", "movflags=+hybrid_fragmented",
        "-segment_start_number", str(int(start_number)),
        out_pattern,
    ]


def _client_crop(hwnd, frame_w, frame_h):
    """Where the window's CLIENT area sits inside a WGC frame, in frame
    pixels: (x, y, w, h) - or None if anything looks off.

    The frame is the window's physical surface; GetWindowRect/ClientToScreen
    speak the process's coordinate space, which may be scaled by DPI. Taking
    the ratio between the two removes that difference without needing to know
    the scale factor, and it stays right on a mixed-DPI desktop."""
    try:
        import ctypes
        u = ctypes.windll.user32

        class _R(ctypes.Structure):
            _fields_ = [("l", ctypes.c_long), ("t", ctypes.c_long),
                        ("r", ctypes.c_long), ("b", ctypes.c_long)]

        class _P(ctypes.Structure):
            _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

        wr, cr, org = _R(), _R(), _P(0, 0)
        if not u.GetWindowRect(hwnd, ctypes.byref(wr)):
            return None
        if not u.GetClientRect(hwnd, ctypes.byref(cr)):
            return None
        if not u.ClientToScreen(hwnd, ctypes.byref(org)):
            return None
        win_w, win_h = wr.r - wr.l, wr.b - wr.t
        cli_w, cli_h = cr.r - cr.l, cr.b - cr.t
        if win_w <= 0 or win_h <= 0 or cli_w <= 0 or cli_h <= 0:
            return None
        sx, sy = frame_w / float(win_w), frame_h / float(win_h)
        x = int(round((org.x - wr.l) * sx))
        y = int(round((org.y - wr.t) * sy))
        w = int(round(cli_w * sx))
        h = int(round(cli_h * sy))
        # a borderless / fullscreen window is all client - nothing to trim
        if x < 0 or y < 0 or w < 16 or h < 16:
            return None
        if x + w > frame_w or y + h > frame_h:
            return None
        return x, y, w, h
    except Exception:
        return None


class _WGCFeed:
    """Windows Graphics Capture -> ffmpeg stdin. The WINDOW ITSELF is the
    source (not a screen region), which is the 2.0 upgrade: overlays,
    popups and Discord toasts physically cannot appear in the recording,
    the feed follows the window wherever it moves, and alt-tab doesn't
    kill anything - WGC keeps compositing an occluded window.

    WGC only delivers frames when the window CHANGES, so a paused game
    would starve the encoder; a 60Hz ticker therefore re-sends the last
    frame whenever no fresh one arrived (constant frame rate, segment
    maths stay exact). One write per frame on a raw (bufsize=0) pipe -
    the single-syscall pattern the pipe can sustain at 2560x1440@60
    (measured 90fps headroom on this machine).

    A frame arriving at a DIFFERENT size means the window was resized:
    feeding it would corrupt the raw stream, so the feed stops cleanly
    and the watcher's existing resize law (split the chapter) takes over."""

    def __init__(self, hwnd, fps):
        self.w = self.h = 0               # aligned encode size (first frame,
        self.fps = fps                    # width mod-8 / height even)
        self._raw_w = self._raw_h = 0     # the window's true physical size
        self._ox = self._oy = 0           # client-area origin inside the frame
        self.stdin = None
        self.size_changed = False
        self.dead = False
        self.frames_in = 0
        self.frames_out = 0
        self._last = None                 # latest BGRA bytes (owned copy)
        self._lock = threading.Lock()
        self._stopev = threading.Event()
        self._first = threading.Event()
        self._ctl = None
        self._ticker_t = None
        self.hwnd = int(hwnd)
        self._crop = None                 # (x, y, w, h) of the CLIENT area
        from windows_capture import WindowsCapture
        # draw_border=False removes the yellow highlight Windows paints around
        # a captured window - it is part of the composed surface, so it lands
        # IN the recording. Older Windows builds don't accept the argument.
        try:
            cap = WindowsCapture(cursor_capture=False, draw_border=False,
                                 window_hwnd=self.hwnd)
        except Exception:
            cap = WindowsCapture(cursor_capture=False, window_hwnd=self.hwnd)
        feed = self

        @cap.event
        def on_frame_arrived(frame, capture_control):
            if feed._stopev.is_set():
                try:
                    capture_control.stop()
                except Exception:
                    pass
                return
            if not feed._first.is_set():
                feed._raw_w, feed._raw_h = frame.width, frame.height
                # WGC hands back the WHOLE window - title bar, buttons and
                # frame included (measured: 39px of chrome above the client
                # area). A game recording wants the game, so crop to the
                # client area; that also takes the window's outer edge with
                # it. Falls back to the full frame if the maths look wrong.
                feed._crop = _client_crop(feed.hwnd, frame.width, frame.height)
                cx, cy, cw, ch = (feed._crop if feed._crop
                                  else (0, 0, frame.width, frame.height))
                # the SAME alignment law as every other capture path: width
                # mod-8, height even - AMF pads odd sizes up and the padding
                # columns would appear as a garbage stripe in the video
                feed.w = cw - (cw % 8)
                feed.h = ch - (ch % 2)
                feed._ox, feed._oy = cx, cy
                buf = frame.frame_buffer[cy:cy + feed.h,
                                         cx:cx + feed.w].tobytes()
                with feed._lock:
                    feed._last = buf
                feed.frames_in += 1
                feed._first.set()
                return
            if frame.width != feed._raw_w or frame.height != feed._raw_h:
                feed.size_changed = True      # resize: the raw stream is over
                feed._stopev.set()
                return
            buf = frame.frame_buffer[feed._oy:feed._oy + feed.h,
                                     feed._ox:feed._ox + feed.w].tobytes()
            with feed._lock:
                feed._last = buf
            feed.frames_in += 1

        @cap.event
        def on_closed():
            feed.dead = True                     # window destroyed (game exit)
            feed._stopev.set()
        self._cap = cap

    def begin(self, timeout=2.5):
        """Start capturing; block until the first frame reveals the true
        frame size. None on timeout (exclusive-fullscreen windows can be
        invisible to WGC) - the caller then falls back to ddagrab."""
        self._ctl = self._cap.start_free_threaded()
        if not self._first.wait(timeout=timeout):
            self.stop()
            return None
        return (self.w, self.h)

    def attach(self, stdin):
        self.stdin = stdin
        t = threading.Thread(target=self._ticker, daemon=True)
        t.start()
        self._ticker_t = t

    def _ticker(self):
        period = 1.0 / self.fps
        nxt = time.perf_counter()
        while not self._stopev.is_set():
            nxt += period
            delay = nxt - time.perf_counter()
            if delay > 0:
                time.sleep(delay)
            else:
                nxt = time.perf_counter()        # fell behind: re-anchor
            with self._lock:
                buf = self._last
            if buf is None:
                continue                          # nothing captured yet
            try:
                self.stdin.write(buf)             # ONE WriteFile, GIL released
                self.frames_out += 1
            except Exception:
                self.dead = True                  # encoder went away
                break
        try:
            self.stdin.close()                    # EOF -> ffmpeg finalises
        except Exception:
            pass

    def stop(self):
        self._stopev.set()
        try:
            if self._ctl is not None:
                self._ctl.stop()
        except Exception:
            pass
        try:
            if self._ticker_t is not None:
                self._ticker_t.join(timeout=3)
        except Exception:
            pass


def _wgc_available():
    try:
        import windows_capture  # noqa: F401
        return True
    except Exception:
        return False


_SPIN_CACHE = {}


def _drive_has_seek_penalty(path):
    """True if `path` lives on a SPINNING disk, False for solid state, None
    when it cannot be told. Asks the volume itself via the storage device's
    seek-penalty property - no WMI, no admin rights."""
    try:
        root = os.path.splitdrive(os.path.abspath(path))[0].upper()
        if not root:
            return None
        if root in _SPIN_CACHE:
            return _SPIN_CACHE[root]
        import ctypes
        from ctypes import wintypes
        GENERIC_READ = 0            # query-only: no rights needed, so this
        OPEN_EXISTING = 3           # works without running as administrator
        IOCTL = 0x2D1400            # IOCTL_STORAGE_QUERY_PROPERTY

        class STORAGE_PROPERTY_QUERY(ctypes.Structure):
            _fields_ = [("PropertyId", wintypes.DWORD),
                        ("QueryType", wintypes.DWORD),
                        ("AdditionalParameters", ctypes.c_byte * 1)]

        class DEVICE_SEEK_PENALTY_DESCRIPTOR(ctypes.Structure):
            _fields_ = [("Version", wintypes.DWORD),
                        ("Size", wintypes.DWORD),
                        ("IncursSeekPenalty", ctypes.c_byte)]

        h = ctypes.windll.kernel32.CreateFileW(
            rf"\\.\{root}", GENERIC_READ, 3, None, OPEN_EXISTING, 0, None)
        if h == -1 or h == ctypes.c_void_p(-1).value:
            return None
        try:
            q = STORAGE_PROPERTY_QUERY(7, 0, (ctypes.c_byte * 1)())  # SeekPenalty
            d = DEVICE_SEEK_PENALTY_DESCRIPTOR()
            got = wintypes.DWORD()
            ok = ctypes.windll.kernel32.DeviceIoControl(
                h, IOCTL, ctypes.byref(q), ctypes.sizeof(q),
                ctypes.byref(d), ctypes.sizeof(d), ctypes.byref(got), None)
            res = bool(d.IncursSeekPenalty) if ok else None
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
        _SPIN_CACHE[root] = res
        return res
    except Exception:
        return None


def _free_bytes(path):
    try:
        return shutil.disk_usage(path).free
    except Exception:
        return 0


def _work_dir():
    """A SINGLE hidden parent folder for in-progress capture scratch (segments
    + wavs).

    It used to live beside the recordings "so the final assemble is a fast
    local read". On a spinning library drive that reasoning is backwards: the
    save then READS the segments and WRITES the finished file through the same
    head, and a paused session is welded twice (segments -> one file per run ->
    one final file), so a 48 GB recording moves about 240 GB through one disk.
    Measured on this machine: 16-27 MB/s.

    So when the library is on a spinning disk and a solid-state drive has room,
    the scratch goes THERE: the save becomes a fast read plus one clean
    sequential write, with no head fighting itself. 'scratch_dir' overrides."""
    out = SETTINGS.get("output_dir", "") or _data_dir()
    want = str(SETTINGS.get("scratch_dir", "auto") or "auto").strip()
    if want and want.lower() != "auto":
        d = os.path.join(want, ".lore_cache")
        try:
            os.makedirs(d, exist_ok=True)
            return d
        except Exception:
            pass                      # unreachable drive: fall through to auto
    elif _drive_has_seek_penalty(out) is True:
        best, best_free = None, 0
        for cand in _scratch_candidates():
            if _drive_has_seek_penalty(cand) is not False:
                continue              # only trust a KNOWN solid-state drive
            free = _free_bytes(cand)
            # a long session needs the segments AND the per-run welds at once
            if free > best_free and free >= 120 * (1 << 30):
                best, best_free = cand, free
        if best:
            d = os.path.join(best, ".lore_cache")
            try:
                os.makedirs(d, exist_ok=True)
                return d
            except Exception:
                pass
    d = os.path.join(out, ".lore_cache")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        d = os.path.join(_data_dir(), ".lore_cache")
        os.makedirs(d, exist_ok=True)
    return d


def _work_dirs_all():
    """Every folder that could be holding in-progress footage: the scratch in
    use now PLUS the legacy one beside the library. Moving the scratch to a
    solid state drive must never strand a crashed session's segments on the
    old drive - salvage and sweeping both walk this list."""
    seen, out = set(), []
    for d in (_work_dir(),
              os.path.join(SETTINGS.get("output_dir", "") or _data_dir(),
                           ".lore_cache"),
              os.path.join(_data_dir(), ".lore_cache")):
        k = os.path.normcase(os.path.abspath(d))
        if k in seen or not os.path.isdir(d):
            continue
        seen.add(k)
        out.append(d)
    return out


def _scratch_candidates():
    """Fixed local drive roots that could host the scratch folder, best first."""
    out = []
    if os.name != "nt":
        return out
    try:
        import ctypes
        bits = ctypes.windll.kernel32.GetLogicalDrives()
        for i in range(26):
            if not (bits >> i) & 1:
                continue
            root = f"{chr(65 + i)}:\\"
            # 3 == DRIVE_FIXED: never a USB stick or a network share
            if ctypes.windll.kernel32.GetDriveTypeW(root) != 3:
                continue
            out.append(root)
    except Exception:
        return []
    out.sort(key=lambda r: -_free_bytes(r))
    return out


def _already_saved(base):
    """Is '<base>.mp4' already in the library - on ANY shelf?

    Salvage used to ask only whether output_dir/<base>.mp4 existed. Real
    recordings live at output_dir/<Game>/Videos/<base>.mp4, so the answer was
    always no, and every launch rebuilt sessions that had finished weeks ago:
    a half-hour concat per orphan, timing out, holding its temp open, blocking
    its own promote, and leaving tens of gigabytes of duplicate welds behind.
    Three of the five stuck files on this machine were already saved."""
    want = (base + ".mp4").lower()
    out = SETTINGS.get("output_dir", "") or ""
    try:
        if os.path.isfile(os.path.join(out, base + ".mp4")):
            return True
        for d, _kind in _library_dirs(out):
            try:
                for fn in os.listdir(d):
                    if fn.lower() == want:
                        return True
            except OSError:
                continue
    except Exception:
        pass
    return False


def _salvage_skip(d):
    return os.path.isfile(os.path.join(d, "_discarded.flag"))


def _salvage_interrupted():
    """A previous run died mid-save (force-kill, crash, power cut). NEVER
    just sweep its remains - they are the user's footage:
      * '<name>.mp4.__assembling__.mp4' whose weld actually FINISHED (it
        probes to a real duration) only missed its final rename - promote it
        into the library.
      * a session folder still holding seg_*.mp4 gets a best-effort re-weld:
        video concat + whatever audio the run captured, muxed from zero.
        (The wall-clock anchors died with the process, so sync is within a
        few hundred ms - imperfect footage beats deleted footage.)
    Anything truly unreadable is parked in .lore_cache\\lost, never deleted.
    Born of a real loss: a 69-minute session was welding when the process
    was killed, and the next boot swept its segments."""
    out = SETTINGS.get("output_dir", "")
    if not out or not os.path.isdir(out):
        return
    ff = SETTINGS.get("ffmpeg_path") or "ffmpeg"
    lost = os.path.join(_work_dir(), "lost")

    def _fresh(path):
        # younger than a minute = something LIVE is writing it, not a corpse
        try:
            return time.time() - os.path.getmtime(path) < 60
        except Exception:
            return True
    # 1) finished-but-unrenamed assemblies. Scan the library root AND every
    #    per-game shelf (<Game>/Videos, <Game>/Clips): real recordings assemble
    #    INSIDE their shelf, so a root-only scan left a completed weld orphaned
    #    forever - the exact bug that stranded a finished session as a stuck
    #    '.__assembling__.mp4' the app never recovered.
    scan_dirs = {out}
    try:
        for _d, _kind in _library_dirs(out):
            scan_dirs.add(_d)
    except Exception:
        pass
    for d in scan_dirs:
        try:
            entries = list(os.listdir(d))
        except Exception:
            continue
        for name in entries:
            if not name.endswith(".__assembling__.mp4"):
                continue
            p = os.path.join(d, name)
            if _fresh(p):
                continue
            final = os.path.join(d, name[:-len(".__assembling__.mp4")])
            try:
                base0 = os.path.splitext(os.path.basename(final))[0]
                if _already_saved(base0):
                    os.remove(p)         # a duplicate of a shelved recording
                    log(f"Cleared a duplicate rebuild: {name}")
                    continue
                if (_probe_duration(p) or 0) > 1.0 and not os.path.exists(final):
                    os.replace(p, final)
                    _record_made_file(final)
                    log("Recovered an interrupted save: "
                        + os.path.basename(final))
                else:
                    os.makedirs(lost, exist_ok=True)
                    os.replace(p, os.path.join(lost, name))
                    log("An interrupted save could not be read; parked in "
                        ".lore_cache\\lost: " + name)
            except Exception as e:
                log(f"Salvage skipped for {name}: {e}")
    # 2) orphaned session folders with real segments -> best-effort weld
    for cache in _work_dirs_all():
      try:
        for name in list(os.listdir(cache)):
            d = os.path.join(cache, name)
            if not os.path.isdir(d) or name == "lost":
                continue
            if _salvage_skip(d):
                # HE THREW THIS ONE AWAY. The tombstone goes down before the
                # discard starts; welding these segments back into a video
                # would resurrect a recording he explicitly binned.
                shutil.rmtree(d, ignore_errors=True)
                continue
            # A weld that already finished is sitting right there. Re-running
            # it costs half an hour of disk, times out, holds the file open,
            # and blocks the promote that would have finished the job - every
            # single launch. Look before rebuilding.
            try:
                done = os.path.join(out, name + ".mp4.__assembling__.mp4")
                fin = os.path.join(out, name + ".mp4")
                if _already_saved(name):
                    # finished long ago and shelved - the leftovers are just
                    # leftovers. Clear them instead of rebuilding the film.
                    for junk in (done, os.path.join(out, name + ".mp4.__tmp.mp4")):
                        try:
                            if os.path.isfile(junk):
                                sz = os.path.getsize(junk)
                                os.remove(junk)
                                log(f"Cleared a duplicate rebuild of {name} "
                                    f"({sz / (1 << 30):.1f} GB) - it was saved "
                                    f"already.")
                        except OSError:
                            pass
                    shutil.rmtree(d, ignore_errors=True)
                    continue
                if os.path.isfile(done) and (_probe_duration(done) or 0) > 1.0:
                    os.replace(done, fin)
                    _record_made_file(fin)
                    log(f"Recovered an interrupted save: {name}.mp4")
                    continue
            except Exception:
                pass
            # and a folder that has already refused twice is not going to
            # start working on the third launch - leave it for the sweep
            if _SALVAGE_FAILS.get(name, 0) >= 2:
                continue
            segs = _list_segments(d)
            if not segs or _fresh(segs[-1]):
                continue
            final = os.path.join(out, name + ".mp4")
            if os.path.exists(final):
                final = os.path.join(out, name + "_recovered.mp4")
            tmp = final + ".__assembling__.mp4"
            try:
                # WAVs are tagged per RUN (system_00/mic_00, system_01/...):
                # a session that auto-paused even once has 2+ runs, and the
                # old blind sorted()[:2] then amixed mic_00 with mic_01 -
                # two mic tracks, game audio discarded. Group by KIND in run
                # order: runs are sequential in time exactly like the video
                # segments, so same-kind WAVs concat, then the kinds amix.
                allw = sorted(w for w in os.listdir(d)
                              if w.endswith(".wav")
                              and os.path.getsize(os.path.join(d, w)) > 64_000)
                sysw = [os.path.join(d, w) for w in allw if w.startswith("system")]
                micw = [os.path.join(d, w) for w in allw if w.startswith("mic")]
                if not sysw and not micw:      # unexpected names: best effort
                    sysw = [os.path.join(d, w) for w in allw[:1]]
                lst = os.path.join(d, "concat.txt")
                with open(lst, "w", encoding="utf-8") as fh:
                    for s in segs:
                        fh.write("file '" + s.replace("'", "'\\''") + "'\n")
                cmd = [ff, "-y", "-hide_banner", "-loglevel", "error",
                       "-f", "concat", "-safe", "0", "-i", lst]
                for w in sysw + micw:
                    cmd += ["-i", w]
                cmd += ["-map", "0:v", "-c:v", "copy"]
                if sysw or micw:
                    fg, k = [], 1
                    if len(sysw) > 1:
                        fg.append("".join(f"[{k + i}:a]" for i in range(len(sysw)))
                                  + f"concat=n={len(sysw)}:v=0:a=1[sa]")
                    elif sysw:
                        fg.append(f"[{k}:a]anull[sa]")
                    k += len(sysw)
                    if len(micw) > 1:
                        fg.append("".join(f"[{k + i}:a]" for i in range(len(micw)))
                                  + f"concat=n={len(micw)}:v=0:a=1[ma]")
                    elif micw:
                        fg.append(f"[{k}:a]anull[ma]")
                    if sysw and micw:
                        fg.append("[sa][ma]amix=inputs=2:duration=longest[a]")
                        out_lbl = "[a]"
                    else:
                        out_lbl = "[sa]" if sysw else "[ma]"
                    cmd += ["-filter_complex", ";".join(fg), "-map", out_lbl]
                    cmd += ["-c:a", "aac", "-b:a", "192k"]
                cmd += ["-movflags", "+faststart", tmp]
                flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
                r = subprocess.run(cmd, stdout=subprocess.DEVNULL,
                                   stderr=subprocess.PIPE, creationflags=flags,
                                   timeout=1800)
                if r.returncode == 0 and os.path.isfile(tmp) \
                        and os.path.getsize(tmp) > 100_000:
                    os.replace(tmp, final)
                    _record_made_file(final)
                    log("Recovered an interrupted recording: "
                        + os.path.basename(final))
                    shutil.rmtree(d, ignore_errors=True)
                else:
                    for ln in (r.stderr or b"").decode("utf-8", "ignore") \
                            .splitlines()[-2:]:
                        log("  ffmpeg(salvage): " + ln)
                    os.makedirs(lost, exist_ok=True)
                    os.replace(d, os.path.join(lost, name))
                    log("Couldn't re-weld a leftover session; parked in "
                        ".lore_cache\\lost: " + name)
            except Exception as e:
                log(f"Salvage failed for {name}: {e}")
                try:
                    if os.path.isfile(tmp):
                        os.remove(tmp)
                except Exception:
                    pass
      except Exception as e:
        # one unreadable cache dir (AV lock, degraded volume) used to abort
        # the WHOLE walk in silence, deferring every remaining rescue
        log(f"Salvage stopped early in {cache}: {e} - its remaining "
            "leftovers wait for the next launch.")


def _migrate_library_layout():
    """One-time (and self-healing) shelving: move flat legacy recordings into
    per-game folders - <Game>/Videos and <Game>/Clips - and keep the storage
    manifest, finish queue and cached thumbnails pointing at the moved files.
    Skips anything younger than 3 minutes (it may still be being written)."""
    out = SETTINGS.get("output_dir", "")
    if not out or not os.path.isdir(out):
        return
    remap = {}

    def _shelve(src_dir, kind):
        if not os.path.isdir(src_dir):
            return
        for f in list(os.listdir(src_dir)):
            p = os.path.join(src_dir, f)
            try:
                if (not os.path.isfile(p) or not f.lower().endswith(".mp4")
                        or ".__" in f or f.startswith(".")):
                    continue
                if time.time() - os.path.getmtime(p) < 180:
                    continue
                base = _parse_clip_name(f)
                nd = _game_shelf(base, kind)
                np = os.path.join(nd, f)
                if os.path.abspath(np) == os.path.abspath(p) or os.path.exists(np):
                    continue
                os.rename(p, np)
                remap[os.path.normcase(os.path.abspath(p))] = np
                # thumbnails already live in ONE root cache keyed by the
                # (unique) filename, so a moved recording keeps its thumb -
                # nothing to relocate.
            except Exception as e:
                log(f"shelving skipped {f}: {e}")
    _shelve(out, "session")
    _shelve(os.path.join(out, "Clips"), "clip")
    # SELF-HEAL stale records: if something else moved files onto their
    # shelves (a helper, a hand), manifest/queue entries still pointing at
    # the old flat spots are re-aimed at wherever the file actually lives.
    try:
        with _MANIFEST_LOCK:
            paths, _ = _load_manifest()
            if paths is None:
                raise OSError("manifest unreadable")
            healed = set()
            changed = False
            for p in paths:
                if os.path.isfile(p):
                    healed.add(p)
                    continue
                bn = os.path.basename(p)
                kind = "clip" if ("_clip_" in bn or "_cut_" in bn) else "session"
                cand = os.path.join(_game_shelf(_parse_clip_name(bn), kind,
                                                make=False), bn)
                if os.path.isfile(cand):
                    healed.add(os.path.normcase(os.path.abspath(cand)))
                    changed = True
                else:
                    healed.add(p)
            if changed:
                _save_manifest(healed)
                log("Re-aimed ownership records at the shelved files.")
    except Exception:
        pass
    try:
        q = _load_finish_queue(strict=True)
        qchanged = False
        for it in q:
            fp = it.get("path", "")
            if fp and not os.path.isfile(fp):
                bn = os.path.basename(fp)
                cand = os.path.join(_game_shelf(_parse_clip_name(bn),
                                                "session", make=False), bn)
                if os.path.isfile(cand):
                    it["path"] = os.path.abspath(cand)
                    qchanged = True
        if qchanged:
            _save_finish_queue(q)
    except Exception:
        pass
    if not remap:
        return
    log(f"Shelved {len(remap)} recordings into per-game folders.")
    # ownership manifest follows the files
    try:
        with _MANIFEST_LOCK:
            paths, _ = _load_manifest()
            if paths is None:
                raise OSError("manifest unreadable")
            changed = False
            for old_p, new_p in remap.items():
                if old_p in paths:
                    paths.discard(old_p)
                    paths.add(os.path.normcase(os.path.abspath(new_p)))
                    changed = True
            if changed:
                _save_manifest(paths)
    except Exception:
        pass
    # pending HDR restorations follow too
    try:
        q = _load_finish_queue(strict=True)
        changed = False
        for it in q:
            k = os.path.normcase(os.path.abspath(it.get("path", "")))
            if k in remap:
                it["path"] = os.path.abspath(remap[k])
                changed = True
        if changed:
            _save_finish_queue(q)
    except Exception:
        pass


def _sweep_orphan_temp():
    """Tidy TRUE leftovers from previous runs - but salvage runs FIRST, and
    on its OWN thread: a rescue weld can take minutes of ffmpeg, and the
    watcher must never wait on it (a recorder that boots late records
    late). What's swept here synchronously is only empty scratch, legacy
    '.tmp_*' litter and half-written SDR conversions (whose HDR originals
    still exist untouched)."""
    def _salvage_guarded():
        try:
            _salvage_interrupted()
        except Exception as e:
            log(f"Salvage crashed: {e} - leftovers wait for the next launch.")
    threading.Thread(target=_salvage_guarded, daemon=True).start()
    removed = 0
    try:
      now0 = time.time()
      for cache in _work_dirs_all():
        for name in os.listdir(cache):
            if name == "lost":
                continue          # parked salvage evidence - never touch
            p = os.path.join(cache, name)
            if os.path.isdir(p) and not _list_segments(p):
                shutil.rmtree(p, ignore_errors=True)
                removed += 1
            # transcription scratch is written HERE, not in the library - the
            # old sweep looked for it beside the videos and never found it
            # the reader's output is '<wav>.json', i.e. 'stt_..._....wav.json'
            # - it does not end '_out.json', so the old test never matched it
            # and a kill between the reader finishing and the cleanup running
            # left one behind for good. Any stt_ scratch, either extension.
            elif (os.path.isfile(p)
                    and (name.startswith("stt_")
                         or name.startswith("laugh_"))
                    and name.rsplit(".", 1)[-1] in
                    ("wav", "json", "ctl", "prog", "tmp")):
                try:
                    if now0 - os.path.getmtime(p) > 600:
                        os.remove(p)
                        removed += 1
                except OSError:
                    pass
    except Exception:
        pass
    # legacy location: '.tmp_<game>_<stamp>' folders directly in the output dir
    try:
        out = SETTINGS.get("output_dir", "")
        if out and os.path.isdir(out):
            for name in os.listdir(out):
                if name.startswith(".tmp_"):
                    p = os.path.join(out, name)
                    if os.path.isdir(p):
                        shutil.rmtree(p, ignore_errors=True)
                        removed += 1
    except Exception:
        pass
    # half-written work temps from a crash/kill: '<name>.mp4.__sdr__.mp4'
    # (conversion) and '<base>_cut_<stamp>.__tmp.mp4' (trim). The temps live on
    # the per-game SHELVES now, not just the flat legacy dirs - sweep every
    # folder a recording can live in (the same single source of truth the
    # scanner uses), and only LORE's own '.__' work names, nothing else.
    # Age-gate 10 minutes so a temp a LIVE worker is writing right now survives.
    try:
        out = SETTINGS.get("output_dir", "")
        dirs = [d for d, _k in _library_dirs(out)] if out else []
        now = time.time()
        for d in dirs:
            if os.path.isdir(d):
                for name in os.listdir(d):
                    if ".__sdr__." in name or ".__tmp" in name \
                            or (name.startswith("stt_")
                                and (name.endswith(".wav")
                                     or name.endswith("_out.json"))):
                        p = os.path.join(d, name)
                        try:
                            if now - os.path.getmtime(p) > 600:
                                os.remove(p)
                                removed += 1
                        except Exception:
                            pass
    except Exception:
        pass
    if removed:
        log(f"Cleaned up {removed} leftover temp folder(s) from a previous run.")


def _clip_in_flight(session):
    """Is a 'save the last minute' clip being assembled right now?

    save_replay holds this lock for the whole build, and every intermediate it
    writes lives in the folder discard() deletes."""
    lk = getattr(session, "_replay_lock", None)
    if lk is None:
        return False
    if lk.acquire(blocking=False):
        lk.release()
        return False
    return True


def _discard_soon(session):
    """Throw the recording away - but not while a clip is still being written
    into the same folder. Off the watch loop, which must keep detecting
    games while we wait.

    The tombstone goes down FIRST: if the app dies before the discard
    finishes, the boot salvage would otherwise re-weld the surviving
    segments into a finished video - resurrecting a recording that was
    explicitly thrown away."""
    try:
        with open(os.path.join(session.tmp, "_discarded.flag"), "w") as fh:
            fh.write("1")
    except Exception:
        pass

    def work():
        for _ in range(900):                 # up to ~90s, then give up waiting
            if not _clip_in_flight(session):
                break
            time.sleep(0.1)
        try:
            session.discard()
        except Exception as e:
            log(f"Could not discard the recording: {e}")
    threading.Thread(target=work, daemon=True).start()


def _fmt_secs(n):
    n = int(n or 0)
    if n < 60:
        return f"{n} second" + ("" if n == 1 else "s")
    m, sec = divmod(n, 60)
    return f"{m}m {sec:02d}s"


def _captured_seconds(session):
    """Seconds of footage actually on disk for this session.

    Counted from the segments, not the clock: a session paused for an hour has
    an hour of wall time and none of it is footage."""
    try:
        seg = max(2, int(SETTINGS.get("segment_seconds", 4)))
        return len(_list_segments(session.tmp)) * seg
    except Exception:
        return 0


def _not_worth_keeping(session, manual):
    """A game opened and closed again straight away.

    Only ever asked about a recording that ended BY ITSELF. If you pressed
    record, or pressed stop, you meant it - length is none of our business."""
    if manual:
        return False
    lim = int(SETTINGS.get("min_keep_seconds", 45) or 0)
    if lim <= 0:
        return False
    if _clip_in_flight(session) or getattr(session, "_clip_saved", False):
        return False          # you asked for something out of this one
    return _captured_seconds(session) < lim


def _list_segments(seg_dir):
    """All finished+current capture segments in order (oldest -> newest)."""
    try:
        names = [f for f in os.listdir(seg_dir)
                 if f.startswith("seg_") and f.endswith(".mp4")]
    except Exception:
        return []
    return [os.path.join(seg_dir, f) for f in sorted(names)]


def _watch_concat_progress(out_path, want_bytes):
    """Publish a stream-copy's progress by watching the output file grow.
    ffmpeg's -progress needs a decode pipeline to report against; a pure
    `-c copy` concat has none, but the file size IS the progress."""
    _CONCAT_WATCH["stop"] = True          # retire any previous watcher
    if want_bytes <= 0:
        return
    stop = threading.Event()
    _CONCAT_WATCH["stop"] = False
    _CONCAT_WATCH["ev"] = stop
    name = os.path.basename(out_path).replace(".__assembling__.mp4", "")
    _BIND_TOK[0] += 1
    tok = _BIND_TOK[0]
    _BINDING.update({"name": name, "pct": 0, "eta": None, "mbps": None,
                     "t0": time.time(), "total": want_bytes / 1e6,
                     "tok": tok})

    def _run():
        last_sz, last_t = 0, time.time()
        while not stop.is_set():
            stop.wait(1.0)
            if stop.is_set():
                break
            try:
                sz = os.path.getsize(out_path)
            except OSError:
                continue
            if _BINDING.get("tok") != tok:
                break              # a newer bind owns the card now
            now = time.time()
            pct = max(0, min(99, int(sz * 100 / want_bytes)))
            spent = now - _BINDING["t0"]
            _BINDING["pct"] = pct
            if pct > 0 and spent > 2:
                _BINDING["eta"] = max(0, int(spent * (100 - pct) / pct))
            if now > last_t:
                _BINDING["mbps"] = max(0.0, (sz - last_sz) / 1e6 / (now - last_t))
            last_sz, last_t = sz, now
            try:
                if _TRAY_ICON[0] is not None:
                    _TRAY_ICON[0].title = f"Lore - saving {name} ({pct}%)"
            except Exception:
                pass

    threading.Thread(target=_run, daemon=True).start()


def _stop_concat_progress():
    ev = _CONCAT_WATCH.get("ev")
    _CONCAT_WATCH["stop"] = True
    if ev is not None:
        ev.set()
    _CONCAT_WATCH["ev"] = None


def _edit_watch(proc):
    """Remember a child of the export so a Stop can actually reach it. The
    stitch used to spawn ffmpeg through a helper nothing tracked, so cancelling
    left five of them grinding the disk against a file nobody wanted."""
    try:
        _EDIT_JOB.setdefault("procs", []).append(proc)
    except Exception:
        pass
    return proc


def _edit_kill_children():
    """Stop everything this export started, and say how many there were."""
    procs = _EDIT_JOB.get("procs") or []
    killed = 0
    for pr in list(procs):
        try:
            if pr.poll() is None:
                pr.kill()
                killed += 1
        except Exception:
            pass
    try:
        for pr in list(procs):
            try:
                pr.wait(timeout=5)
            except Exception:
                pass
    except Exception:
        pass
    _EDIT_JOB["procs"] = []
    return killed


_DRIFT = {"busy": False, "cancel": False, "done": 0, "total": 0,
          "fixed": 0, "name": "", "scanned": False, "hits": [],
          # scan or repair. The tome used to GUESS this from a flag it set on
          # the click, and lost the guess in the gap between the call
          # returning and the worker thread setting busy - so a repair came
          # out labelled 'checking'. The engine knows; it says.
          "mode": ""}


def _av_durations(path):
    """(video seconds, audio seconds) or None."""
    try:
        d = os.path.dirname(SETTINGS["ffmpeg_path"])
        probe = os.path.join(d, "ffprobe.exe" if os.name == "nt" else "ffprobe")
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([probe, "-v", "error", "-show_entries",
                            "stream=codec_type,duration", "-of", "json", path],
                           capture_output=True, text=True, timeout=40,
                           creationflags=flags)
        v = a = None
        for st in (json.loads(r.stdout or "{}").get("streams") or []):
            if st.get("codec_type") == "video" and v is None:
                v = float(st.get("duration") or 0)
            elif st.get("codec_type") == "audio" and a is None:
                a = float(st.get("duration") or 0)
        if v and a and v > 1 and a > 1:
            return v, a
    except Exception:
        pass
    return None


def _drift_repair_one(path):
    """Stretch the picture's clock onto the sound's. Nothing is re-encoded, so
    a two-gigabyte recording takes about half a minute and loses nothing."""
    got = _av_durations(path)
    if not got:
        return False
    vd, ad = got
    if abs(ad - vd) < 0.5:
        return False                      # already in step
    ratio = ad / vd
    if not (0.9 < ratio < 1.1):
        return False                      # not drift; leave it well alone
    tmp = path + ".__sync__.mp4"
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    try:
        # input 0 carries the picture with its timestamps stretched; input 1 is
        # the same file untouched and carries the sound.
        pr = _popen(
            [SETTINGS["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error",
             "-itsscale", f"{ratio:.9f}", "-i", path, "-i", path,
             "-map", "0:v:0", "-map", "1:a:0", "-c", "copy",
             "-movflags", "+faststart", tmp],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=flags)
        _DRIFT["proc"] = pr
        try:
            pr.wait(timeout=3600)
        except subprocess.TimeoutExpired:
            # the generic except below cannot kill it - it must die HERE or
            # it grinds the library disk for another hour and holds the tmp
            pr.kill()
            pr.wait(timeout=30)
            raise RuntimeError("re-sync took over an hour; stopped")
        if pr.returncode != 0 or not os.path.isfile(tmp):
            raise RuntimeError("ffmpeg refused")
        # NEVER replace the original until the new one is checked
        if os.path.getsize(tmp) < os.path.getsize(path) * 0.9:
            raise RuntimeError("the repaired copy came out too small")
        chk = _av_durations(tmp)
        if not chk or abs(chk[1] - chk[0]) > 0.5:
            raise RuntimeError("still adrift")
        try:
            st = os.stat(path)
        except OSError:
            st = None
        os.replace(tmp, path)
        if st is not None:
            try:
                # keep the original mtime: the transcript, marks and review
                # still describe this same content, and a bumped clock made
                # one drift repair silently queue HOURS of AI redo
                os.utime(path, (st.st_atime, st.st_mtime))
            except OSError:
                pass
        log(f"Re-synced {os.path.basename(path)}: was {ad - vd:+.2f}s adrift.")
        return True
    except Exception as e:
        log(f"Could not re-sync {os.path.basename(path)}: {e}")
        try:
            os.remove(tmp)
        except OSError:
            pass
        return False
    finally:
        _DRIFT["proc"] = None


# which sidecars a job owns. 'listening' owns TWO - the gold moments and the
# sound curve underneath them - and redoing the moments without the curve
# would leave the graph drawn from the old measurements.
_JOB_SIDES = {"listening": ("hl", "lvl"), "hearing": ("stt",),
              "thinking": ("ins", "aud"),
              # the audit alone: corrections live on the transcript lines
              # (was/pin), so forgetting the .aud loses no history
              "auditing": ("aud",)}


def _redo_sweep(kinds):
    """Delete the sidecars for these jobs so the ordinary queue redoes them.
    Nothing is recomputed here - this only forgets."""
    sides = []
    for k in kinds:
        sides.extend(_JOB_SIDES.get(k, ()))
    if not sides:
        return 0
    gone = 0
    try:
        for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
            for v in _scan_dir_mp4s(d, kind):
                for side in sides:
                    p = _ai_sidecar(v["path"], side)
                    try:
                        if os.path.isfile(p):
                            os.remove(p)
                            gone += 1
                    except OSError:
                        pass
    except Exception:
        pass
    _AI.pop("_tally", None)          # the counts are stale the moment we start
    return gone


# window CLASS names and engine furniture. None of these is ever a game.
_NOT_A_GAME = {"d3dproxywindow", "unrealwindow", "ue4window", "ue5window",
               "sdlapp", "glfw30", "winclass", "mainwindow", "gamewindow",
               "directx", "renderwindow", "splashscreen", "launcher"}
_BUILD_TAG_RE = (r"^(?:\d+[- ]?bit|x64|x86|dx\d+|d3d\d*|vulkan|opengl|cooked|"
                 r"shipping|release|debug|development|final|retail|steam|epic|"
                 r"demo|beta|alpha|win(?:64|32)?|64|32)$")


def _clean_stored_name(name, raw):
    """What survives of a stored name once you actually look at it. None means
    nothing did - go and ask properly."""
    import re
    n = str(name or "").strip()
    if not n:
        return None
    if _norm_game_key(n) in _NOT_A_GAME:
        return None                       # a window class, not a game
    tag = re.compile(_BUILD_TAG_RE, re.I)

    def _debracket(m):
        parts = [p.strip() for p in re.split(r"[,;/]| - ", m.group(1))
                 if p.strip()]
        return "" if parts and all(tag.match(p) for p in parts) else m.group(0)

    n = re.sub(r"\s*\(([^()]*)\)", _debracket, n).strip()
    n = re.sub(r"\s+\d{3,6}$", "", n).strip()      # 'yuzu 1734'
    if len(n) < 3:
        return None
    # STRIP THE BUILD TAGS OFF THE EXECUTABLE FIRST. Comparing against the raw
    # stem rejected every good name too: 'theinvincible-win64-shipping' starts
    # with 'theinvincible', so The Invincible looked like a truncation of
    # itself. Against the de-tagged stem the test does what it is meant to.
    # peel the build tags off the executable one at a time. The regex that
    # was here kept silently not matching; a loop is duller and it is obvious
    # what it does, which is worth more than the cleverness was.
    parts = [p for p in re.split(r"[-_ ]+", str(raw or "")) if p]
    while parts and parts[-1].lower() in (
            "win64", "win32", "shipping", "cooked", "release", "debug",
            "final", "retail", "x64", "x86", "64", "32", "exe"):
        parts.pop()
    key, rk = _norm_game_key(n), _norm_game_key("".join(parts))
    # 'Pal' for palworld: a strict truncation of its own executable is the
    # title bar being lazy, not the game's name
    if rk and key and key != rk and rk.startswith(key) and len(key) < len(rk):
        return None
    return n


def _game_names_sweep(force=False):
    """Re-derive every game's name. Free sources first; the paid last resort
    only fires for the ones that still come back as their own executable."""
    changed, dropped, looked = [], [], 0
    if force:
        _AI["named"] = set()         # ask again about ones already asked
    try:
        seen = set()
        for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
            for v in _scan_dir_mp4s(d, kind):
                raw = _parse_clip_name(os.path.basename(v["path"]))
                key = _norm_game_key(raw)
                if not key or key in seen:
                    continue
                seen.add(key)
                looked += 1
                if looked > 150:     # a check, not an audit
                    break
                stored = None
                try:
                    stored = _auto_name_for_raw(raw)
                except Exception:
                    pass
                kept = _clean_stored_name(stored, raw) if stored else None
                if stored and not kept:
                    # the stored answer did not survive being looked at
                    auto = _load_auto_game_names()
                    for kk in (key, _norm_game_key(raw + ".exe")):
                        auto.pop(kk, None)
                    _save_auto_game_names(auto)
                    dropped.append((raw, stored))
                    kept = _claude_game_name("", "", raw) if force else None
                if kept and _norm_game_key(kept) != _norm_game_key(stored or ""):
                    auto = _load_auto_game_names()
                    auto[key] = {"name": kept, "source": "checked"}
                    _save_auto_game_names(auto)
                if kept and _norm_game_key(kept) != key:
                    changed.append((raw, kept))
    except Exception:
        pass
    _persist_setting("names_last_sweep", int(time.time()))
    if dropped:
        log("Game names: threw out " + str(len(dropped)) + " bad title(s) - "
            + ", ".join(f"{a} was '{b}'" for a, b in dropped[:6]))
    if changed:
        log("Game names: " + ", ".join(f"{a} -> {b}" for a, b in changed[:12])
            + (f" (+{len(changed) - 12} more)" if len(changed) > 12 else ""))
    if not changed and not dropped:
        log(f"Game names: checked {looked}, nothing to correct.")
    return {"looked": looked, "changed": changed, "dropped": dropped}


# Bumped when the results on disk stop being worth keeping. 3 = the reader
# became Qwen3-ASR, which reads English and Arabic together; every whisper-era
# transcript is a single-language guess and cannot be trusted.
_ENGINE_GENERATION = 3


def _free_now_so_turn_it_on():
    """Describing used to cost money per recording, so it was off. It is local
    and free now - but a settings file written before today still says off,
    and a default only helps a fresh install. Flip it once."""
    if SETTINGS.get("insights_auto"):
        return
    if SETTINGS.get("insights_auto_freed"):
        return                       # he turned it off himself afterwards
    _persist_setting("insights_auto", True)
    _persist_setting("insights_auto_freed", True)
    log("Describing recordings is free now that it runs on your own machine, "
        "so it has been switched on. Settings > Video to turn it back off.")


_HL_GENERATION = 1


# a slate walk in progress: the AI tick must not spawn on a half-cleared
# shelf (a describe started mid-wipe resurrects exactly what the slate is
# clearing)
_SLATE_BUSY = [0]


def _hl_slate_if_needed():
    """Every gold sidecar written before 2.68 was chosen deaf to laughter.
    Wipe the marks once (the loudness CURVE stays - the editor's sound canvas
    keeps working); the sweep re-marks each video with the laughter ear as
    it works through the shelf."""
    mark = os.path.join(_data_dir(), "hl.gen")
    try:
        with open(mark, encoding="utf-8") as fh:
            if int((fh.read() or "0").strip() or 0) >= _HL_GENERATION:
                return
    except Exception:
        pass

    def work():
        gone = 0
        done_walk = False
        _SLATE_BUSY[0] += 1
        try:
            for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
                for v in _scan_dir_mp4s(d, kind):
                    p = _ai_sidecar(v["path"], "hl")
                    try:
                        if os.path.isfile(p):
                            os.remove(p)
                            gone += 1
                    except OSError:
                        pass
            done_walk = True
        except Exception as e:
            log(f"Gold slate stopped early: {e} - no marker written; it "
                "finishes next launch.")
        finally:
            _SLATE_BUSY[0] -= 1
        if done_walk:
            try:
                _atomic_write_json(mark, _HL_GENERATION)
            except Exception:
                pass
        if gone:
            log(f"GOLD SLATE: cleared {gone} mark set(s) - they were chosen "
                "before the tome could hear laughter. Each will be re-marked "
                "as the tome works.")
    threading.Thread(target=work, daemon=True).start()


_INS_GENERATION = 3

# WHICH READER WROTE A TRANSCRIPT. Bump this whenever ai/asr_worker.py
# learns to hear something it could not hear before; 2 is the reader
# whose transliteration wall faces both ways.
_STT_READER = 2


def _stt_reader_note():
    """Say ONCE how many transcripts predate the reader on disk.

    A .stt.json is fresh if it is newer than its recording, and that is
    the only question anything asks - so a wall added to the reader
    today never reaches a night that was read yesterday. That was not
    merely undone, it was INVISIBLE: nothing on disk recorded which
    reader had written a transcript, so there was no way to tell
    whether a fix had ever touched his library.

    Every transcript carries the number now. This counts the ones that
    do not and says so plainly. It does NOT re-read them behind his
    back: the tome's own Re-do card already prices that honestly
    ("MINUTES per recording - the whole library is DAYS of work"), and
    that is his call to make, not this function's."""
    mark = os.path.join(_data_dir(), "stt.reader")
    try:
        with open(mark, encoding="utf-8") as fh:
            if int((fh.read() or "0").strip() or 0) >= _STT_READER:
                return
    except Exception:
        pass

    def work():
        old = new = 0
        try:
            d = _thumb_dir(SETTINGS.get("output_dir", ""))
            for fn in os.listdir(d):
                if not fn.endswith(".stt.json"):
                    continue
                try:
                    # the version sits in the first line of the file,
                    # ahead of the segments - reading 4 KB of a
                    # multi-megabyte transcript is the whole cost
                    with open(os.path.join(d, fn),
                              encoding="utf-8") as fh:
                        head = fh.read(4096)
                except OSError:
                    continue
                m = re.search(r'"reader"\s*:\s*(\d+)', head)
                if m and int(m.group(1)) >= _STT_READER:
                    new += 1
                else:
                    old += 1
        except Exception as e:
            log(f"Could not count the transcripts' reader: {e}")
            return
        if old:
            log(f"{old} transcript(s) here were read before the current "
                f"reader ({new} with it). A transcript already on disk "
                "is never read again on its own, so the reader's newest "
                "hearing reaches only recordings transcribed from now "
                "on - Re-do the words on a recording to get it there.")
        try:
            with open(mark, "w", encoding="utf-8") as fh:
                fh.write(str(_STT_READER))
        except OSError:
            pass

    threading.Thread(target=work, daemon=True).start()


def _ins_slate_if_needed():
    """Nothing is ever wiped again. Reviews carry the generation that wrote
    them; an older-generation finished review keeps serving while the sweep
    rebuilds it into a .new side file, and only a COMPLETE new review
    replaces the old - his design: 'until the update finishes the new one,
    the old one stays.'"""
    return


def _clean_slate_if_needed():
    """Throw away results built by an engine LORE no longer has. Once."""
    mark = os.path.join(_data_dir(), "engine.gen")
    try:
        with open(mark, encoding="utf-8") as fh:
            if int((fh.read() or "0").strip() or 0) >= _ENGINE_GENERATION:
                return
    except Exception:
        pass

    def work():
        gone, kept = 0, 0
        done_walk = False
        _SLATE_BUSY[0] += 1
        try:
            for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
                for v in _scan_dir_mp4s(d, kind):
                    for side in ("stt", "hl", "lvl", "ins", "aud"):
                        p = _ai_sidecar(v["path"], side)
                        try:
                            if os.path.isfile(p):
                                os.remove(p)
                                gone += 1
                        except OSError:
                            kept += 1
            done_walk = True
        except Exception as e:
            log(f"Clean slate stopped early: {e} - no marker written; it "
                "finishes next launch.")
        finally:
            _SLATE_BUSY[0] -= 1
        _AI.pop("_tally", None)
        _AI["index"] = None
        _AI["failed"] = {}
        if done_walk:
            try:
                with open(mark, "w", encoding="utf-8") as fh:
                    fh.write(str(_ENGINE_GENERATION))
            except Exception:
                pass
        log(f"CLEAN SLATE: cleared {gone:,} old result(s) written by the "
            f"previous reader"
            + (f" ({kept} could not be removed)" if kept else "")
            + ". Your recordings are untouched. The tome starts again from "
              "the newest recording and works backwards.")
    threading.Thread(target=work, daemon=True).start()


def _names_daily():
    """Once a day, in the background, never while a game is on."""
    def work():
        try:
            last = int(SETTINGS.get("names_last_sweep") or 0)
        except Exception:
            last = 0
        if time.time() - last < 86_400:
            return
        try:
            _game_names_sweep(False)
        except Exception as e:
            log(f"Game-name check failed: {e}")
    threading.Thread(target=work, daemon=True).start()


def _self_check_daily():
    """One health line a day in the log - the library's size, where each
    job stands, and the room left on the drives the tome depends on. Grep
    the log for 'Self-check' to see the trend."""
    try:
        last = float(SETTINGS.get("selfcheck_last") or 0)
    except (TypeError, ValueError):
        last = 0.0
    if time.time() - last < 86_400:
        return
    try:
        ctl = _AI.get("ctl")
        if ctl is not None and ctl.session is not None:
            return                # not while a recording is being written
    except Exception:
        pass
    SETTINGS["selfcheck_last"] = time.time()   # claim the day BEFORE the
    #                             thread runs - two beats must not log twice

    def work():
        try:
            _persist_setting("selfcheck_last", int(time.time()))
        except Exception:
            pass
        try:
            import shutil
            t = _ai_tally()

            def free(p):
                try:
                    return (f"{shutil.disk_usage(p).free / 1e9:,.0f}"
                            f" GB free")
                except Exception:
                    return "unreadable"
            parts = []
            for kind, word in (("listening", "sound"),
                               ("hearing", "words"),
                               ("thinking", "reviews")):
                k = t.get(kind) or {}
                g = (t.get("gaveup") or {}).get(kind) or 0
                parts.append(f"{word} {k.get('done', 0)} done"
                             f"/{k.get('left', 0)} owed"
                             + (f"/{g} given up" if g else ""))
            lib = SETTINGS.get("output_dir", "") or "."
            log(f"Self-check: {t.get('total', 0)} recordings; "
                + "; ".join(parts)
                + f"; library {free(lib)}; scratch {free(_work_dir())}.")
        except Exception as e:
            log(f"Self-check failed: {e}")
    threading.Thread(target=work, daemon=True).start()


def _lost_dirs():
    """Every place abandoned assemblies pile up. The work dirs ARE the
    .lore_cache folders already - joining '.lore_cache' onto them again
    built a doubled path (.lore_cache inside .lore_cache) that never
    exists, so the staging UI only ever saw the legacy library-drive
    location."""
    out = []
    lib = SETTINGS.get("output_dir", "")
    if lib:
        d = os.path.join(lib, ".lore_cache", "lost")
        if os.path.isdir(d):
            out.append(d)
    for w in _work_dirs_all():
        d = os.path.join(w, "lost")
        if os.path.isdir(d) and d not in out:
            out.append(d)
    return out


def _lost_base(name):
    """The recording a leftover belongs to."""
    n = name.lower()
    for suf in (".mp4.__assembling__.mp4", ".__assembling__.mp4", ".mp4",
                ".wav", ".txt"):
        if n.endswith(suf):
            n = n[:-len(suf)]
            break
    return n


def _dir_size(p):
    if os.path.isfile(p):
        try:
            return os.path.getsize(p)
        except OSError:
            return 0
    t = 0
    for dp, _, fs in os.walk(p):
        for f in fs:
            try:
                t += os.path.getsize(os.path.join(dp, f))
            except OSError:
                pass
    return t


def _cache_survey():
    """What is in the staging folder, and which of it is safe to lose."""
    saved = set()
    try:
        for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
            for v in _scan_dir_mp4s(d, kind):
                saved.add(os.path.splitext(os.path.basename(v["path"]))[0].lower())
    except Exception:
        pass
    safe, orphan = [], []
    for lost in _lost_dirs():
        try:
            names = os.listdir(lost)
        except OSError:
            continue
        for name in names:
            p = os.path.join(lost, name)
            row = {"path": p, "name": name, "size": _dir_size(p),
                   "base": _lost_base(name)}
            # a folder of seg_*.mp4 can be welded back into a real recording
            row["salvageable"] = (os.path.isdir(p) and any(
                f.startswith("seg_") and f.endswith(".mp4")
                for f in (os.listdir(p) if os.path.isdir(p) else [])))
            (safe if row["base"] in saved else orphan).append(row)
    return safe, orphan


def _concat_copy(ffmpeg, seg_files, out_path, watch=None):
    # `watch`, when given, is handed each ffmpeg child so the caller can end
    # it. Recording saves pass nothing and behave exactly as before.
    """Concatenate segments into out_path with no re-encode (instant). If the
    join fails - which usually means the final segment was truncated by a crash
    or a force-kill - retry once without that last segment, so a long recording
    is never lost to one bad tail file."""
    if not seg_files:
        return False

    def _run(files):
        list_path = out_path + ".list.txt"
        try:
            with open(list_path, "w", encoding="utf-8") as fh:
                for f in files:
                    p = os.path.abspath(f).replace("\\", "/").replace("'", "'\\''")
                    fh.write(f"file '{p}'\n")
        except Exception:
            return False
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        cmd = [ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
               "-f", "concat", "-safe", "0", "-i", list_path, "-c", "copy", out_path]
        # `watch` lets the caller keep a handle on this child. Without it the
        # export's stitch was unreachable by Stop.
        # The stitch of a PAUSED recording lands here, and for a long session
        # that is tens of gigabytes moving for many minutes. It used to run
        # blind - nothing in the tome, nothing in the tray, no way to tell
        # whether it was working or wedged. Report it like every other bind.
        want_bytes = 0
        for f in files:
            try:
                want_bytes += os.path.getsize(f)
            except OSError:
                pass
        _watch_concat_progress(out_path, want_bytes)
        # Popen, not run: a blocking run leaves NOBODY holding the process,
        # so a Stop had nothing to stop and the weld carried on against a file
        # that was already being thrown away.
        r = None
        try:
            pr = _popen(cmd, stdout=subprocess.DEVNULL,
                                  stderr=subprocess.PIPE, creationflags=flags)
            if watch:
                watch(pr)
            try:
                err = pr.communicate(timeout=1800)[1]
            except subprocess.TimeoutExpired:
                pr.kill()
                err = pr.communicate()[1]
            r = subprocess.CompletedProcess(cmd, pr.returncode, None, err)
        except Exception as e:
            log(f"Concat error: {e}")
            r = None
        finally:
            _stop_concat_progress()      # every exit, or the card hangs at 99%
        try:
            os.remove(list_path)
        except Exception:
            pass
        return bool(r) and r.returncode == 0 and os.path.isfile(out_path)

    if _run(seg_files):
        return True
    if len(seg_files) > 1:
        log("Concat failed; retrying without the final (likely truncated) segment.")
        return _run(seg_files[:-1])
    return False


def _is_lore_recording(name):
    """Heuristic 'looks unmistakably like a file Lore made', used ONLY to SEED
    the ownership manifest on first run after an upgrade. Lore names its files
    '<base>_YYYYMMDD_HHMMSS.mp4' (and clips '<base>_clip_...'), where <base> is a
    real game/app name. We deliberately REJECT names with no base before the
    date+time (e.g. a stock Android camera clip '20240101_120000.mp4') and common
    phone/camera/screen-recorder prefixes, because those share the date+time
    signature. Day-to-day deletion is driven by the explicit manifest
    (_record_made_file), NOT this heuristic, so a user's own videos sharing the
    folder are never at risk."""
    base = name[:-4] if name.lower().endswith(".mp4") else name
    parts = base.split("_")
    # require at least one base segment BEFORE the date+time, so a bare
    # 'YYYYMMDD_HHMMSS.mp4' camera export (len 2) is rejected outright.
    if not (len(parts) >= 3
            and len(parts[-1]) == 6 and parts[-1].isdigit()
            and len(parts[-2]) == 8 and parts[-2].isdigit()):
        return False
    prefix = "_".join(parts[:-2]).strip().lower()
    if not prefix:
        return False
    # prefixes that collide with the signature but are NOT Lore files
    CAMERA = {"vid", "img", "pxl", "mvimg", "mov", "dsc", "dscn", "dji", "gopro",
              "gx", "burst", "pano", "screenrecording", "screen-recording",
              "screenrec", "rec", "capture", "video", "wp", "signal", "whatsapp"}
    return prefix not in CAMERA


_MANIFEST_LOCK = threading.Lock()


def _manifest_path():
    return os.path.join(_data_dir(), "created_files.json")


def _load_manifest():
    """The set of absolute paths Lore itself created (recordings + clips), plus
    a flag saying whether the manifest existed at all. Returns (set, existed);
    (None, True) when the manifest EXISTS but could not be read - callers must
    then skip their write, or one transient read failure (AV lock, disk
    hiccup) persists a manifest that has disowned every prior recording."""
    p = _manifest_path()
    if not os.path.isfile(p):
        return set(), False
    try:
        with open(p, encoding="utf-8") as fh:
            data = json.load(fh)
        return {os.path.normcase(os.path.abspath(x)) for x in data}, True
    except Exception as e:
        log(f"The ownership manifest could not be read ({e}) - "
            "leaving it exactly as it is.")
        return None, True


def _save_manifest(paths):
    try:
        _atomic_write_json(_manifest_path(), sorted(paths))
    except Exception:
        pass


def _record_made_file(path):
    """Remember that Lore created this file, so the storage cap can later delete
    it WITHOUT ever touching a user's unrelated videos in the same folder. This is
    the authoritative ownership record; the name heuristic above is only a seed."""
    if not path:
        return
    try:
        with _MANIFEST_LOCK:      # two finalizes/clips can land at the same moment
            paths, _existed = _load_manifest()
            if paths is None:
                return    # unreadable: adding one would disown the rest
            paths.add(os.path.normcase(os.path.abspath(path)))
            _save_manifest(paths)
    except Exception:
        pass


# ---------------------------------------------------------------------------
#  The Vault (2.76) - disk truth, cap pins, cold shelf, one-button tidy and
#  the audio echo test. Read-mostly: walks run on workers, results cached.
# ---------------------------------------------------------------------------
_VAULT = {"busy": False, "res": None, "t": 0.0}
_TIDY = {"busy": False, "step": "", "report": [], "t": 0.0}
_ECHO = {"busy": False, "res": None, "t": 0.0}
_OPENS_LOCK = threading.Lock()
_OPENS = {"map": None}


def _opens_path():
    return os.path.join(_data_dir(), "opened.json")


def _opens_load():
    """Last-opened times keyed by normcased absolute path. Written by the
    player's stream_url from 2.76 on; the cold-shelf view prefers this truth
    over mtime (Windows last-access times are unreliable and unused)."""
    with _OPENS_LOCK:
        if _OPENS["map"] is None:
            try:
                with open(_opens_path(), encoding="utf-8") as fh:
                    _OPENS["map"] = {str(k): float(v)
                                     for k, v in json.load(fh).items()}
            except Exception:
                _OPENS["map"] = {}
        return dict(_OPENS["map"])


def _note_open(path):
    try:
        k = os.path.normcase(os.path.abspath(path))
        _opens_load()
        with _OPENS_LOCK:
            _OPENS["map"][k] = time.time()
            snap = dict(_OPENS["map"])
        _atomic_write_json(_opens_path(), snap)
    except Exception:
        pass


def _cap_pinned_keys():
    """Games pinned on the vault page: the cap counts them, never takes them.
    Keys are the library's chapter keys (display name, lowercased)."""
    try:
        return {str(x).strip().lower()
                for x in (SETTINGS.get("cap_pinned_games") or [])
                if str(x).strip()}
    except Exception:
        return set()


def _cap_game_key(path):
    """The chapter key a recording belongs to - the same display-name key
    scan_library groups by, so a pin made in the UI matches here exactly."""
    try:
        return _display_name(_parse_clip_name(os.path.basename(path))).lower()
    except Exception:
        return ""


def _vault_walk():
    """One pass of disk truth: the library per game, the staging scratch, the
    parked 'lost' evidence, the thumbnail cache, and free space per drive.
    Walks real folders, which is why it runs on a worker and is cached."""
    out = SETTINGS.get("output_dir", "") or ""
    totals = {"library": 0, "staging": 0, "lost": 0, "thumbs": 0}
    games, loose_b, loose_n = [], 0, 0
    covered = set()
    try:
        for name in os.listdir(out):
            p = os.path.join(out, name)
            try:
                if name == ".lore_thumbs":
                    totals["thumbs"] += _dir_size(p)
                elif name == ".lore_cache":
                    lp = os.path.join(p, "lost")
                    lb = _dir_size(lp) if os.path.isdir(lp) else 0
                    totals["lost"] += lb
                    totals["staging"] += max(0, _dir_size(p) - lb)
                    covered.add(os.path.normcase(os.path.abspath(p)))
                elif name.startswith("."):
                    pass                      # someone else's dot-folder
                elif os.path.isdir(p):
                    b, n = 0, 0
                    for _dp, _dn, fs in os.walk(p):
                        for f in fs:
                            try:
                                b += os.path.getsize(os.path.join(_dp, f))
                            except OSError:
                                continue
                            if f.lower().endswith(".mp4"):
                                n += 1
                    totals["library"] += b
                    if name in ("Clips", "Old"):
                        loose_b += b
                        loose_n += n
                    else:
                        games.append({"name": name, "bytes": b, "n": n})
                else:
                    sz = os.path.getsize(p)
                    totals["library"] += sz
                    if name.lower().endswith(".mp4"):
                        loose_b += sz
                        loose_n += 1
            except Exception:
                continue
    except Exception:
        pass
    for w in _work_dirs_all():
        k = os.path.normcase(os.path.abspath(w))
        if k in covered:
            continue
        covered.add(k)
        lp = os.path.join(w, "lost")
        lb = _dir_size(lp) if os.path.isdir(lp) else 0
        totals["lost"] += lb
        totals["staging"] += max(0, _dir_size(w) - lb)
    games.sort(key=lambda g: -g["bytes"])
    top, rest = games[:12], games[12:]
    drives, seen = [], set()
    for p in [out] + _work_dirs_all():
        try:
            drv = os.path.splitdrive(os.path.abspath(p))[0].upper()
            if not drv or drv in seen:
                continue
            seen.add(drv)
            u = shutil.disk_usage(p)
            drives.append({"drive": drv, "free": u.free, "total": u.total})
        except Exception:
            continue
    return {"totals": totals, "games": top,
            "rest_bytes": sum(g["bytes"] for g in rest) + loose_b,
            "rest_n": sum(g["n"] for g in rest) + loose_n,
            "drives": drives, "t": time.time()}


def _echo_analyze(path):
    """Peak/average level percentages plus ~200 ms peak buckets from a short
    wav - enough to drive an honest meter from ONE capture. Deliberately no
    continuous live tap: the recorder owns the devices when it matters."""
    try:
        import array
        wf = wave.open(path, "rb")
        try:
            ch = max(1, wf.getnchannels())
            rate = max(1, wf.getframerate())
            if wf.getsampwidth() != 2:
                return None
            raw = wf.readframes(wf.getnframes())
        finally:
            wf.close()
        if not raw:
            return None
        a = array.array("h")
        a.frombytes(raw[:len(raw) - (len(raw) % 2)])
        if not len(a):
            return None
        full = 32768.0
        step = max(1, int(rate * ch * 0.2))
        bars, peak = [], 0
        for i in range(0, len(a), step):
            seg = a[i:i + step]
            m = max(max(seg), -min(seg))
            bars.append(round(m / full, 3))
            peak = max(peak, m)
        acc, cnt = 0.0, 0
        stride = max(1, len(a) // 200000)  # sparse rms: instant in pure python
        for i in range(0, len(a), stride):
            v = a[i] / full
            acc += v * v
            cnt += 1
        rms = (acc / max(1, cnt)) ** 0.5
        return {"peak_pct": round(min(100.0, peak / full * 100.0), 1),
                "rms_pct": round(min(100.0, rms * 100.0), 1),
                "bars": bars[:60], "bucket_s": 0.2}
    except Exception:
        return None


def enforce_storage_cap():
    """If a storage cap is set, delete the oldest Lore-made full recordings in
    the output folder until under the limit. Ownership comes from an explicit
    manifest written whenever Lore saves a file (_record_made_file), so this can
    NEVER delete a user's unrelated videos that merely share the folder - the exact
    promise the old name-pattern check couldn't keep (it collided with phone/camera
    exports like 'VID_20240101_120000.mp4'). On the first run the manifest is seeded
    from existing files whose name unmistakably matches Lore' own signature
    (camera/phone exports excluded). If ownership is unknown, nothing is deleted."""
    cap_gb = SETTINGS.get("max_storage_gb", 0) or 0
    if cap_gb <= 0:
        return
    out = SETTINGS["output_dir"]
    with _MANIFEST_LOCK:
        owned, existed = _load_manifest()
        if owned is None:
            return             # unreadable manifest: delete NOTHING today
        if not existed:
            # one-time seed from existing, unmistakably-ours files, so the cap keeps
            # managing pre-upgrade recordings without ever matching a camera clip.
            seed = set()
            try:
                for f in os.listdir(out):
                    fp = os.path.join(out, f)
                    if f.lower().endswith(".mp4") and _is_lore_recording(f) \
                            and os.path.isfile(fp):
                        seed.add(os.path.normcase(os.path.abspath(fp)))
            except Exception:
                pass
            owned = seed
            _save_manifest(owned)
    if not owned:
        return     # nothing is known to be ours -> never delete anything (fail-safe)
    # Recordings at the top level AND saved clips in the Clips subfolder both count
    # toward the cap (clips are manifest-owned too - excluding them let the Clips
    # folder grow without bound while the cap starved the main recordings).
    files = []
    for folder, _kind in _library_dirs(out):
        try:
            for f in os.listdir(folder):
                fp = os.path.join(folder, f)
                if f.lower().endswith(".mp4") \
                        and os.path.normcase(os.path.abspath(fp)) in owned \
                        and os.path.isfile(fp):
                    files.append(fp)
        except Exception:
            continue

    def _mtime_safe(p):
        try:
            return os.path.getmtime(p)
        except OSError:
            return 0.0             # vanished mid-scan: sorts first, delete no-ops
    files.sort(key=_mtime_safe)    # oldest first
    try:
        total = sum(os.path.getsize(p) for p in files)
    except Exception:
        return
    # pinned games hold real shelf space, so they COUNT toward the total -
    # but the cap may never take them (the vault page's per-game pin)
    pinned = _cap_pinned_keys()
    if pinned:
        files = [p for p in files if _cap_game_key(p) not in pinned]
    cap = cap_gb * (1024 ** 3)
    i = 0
    deleted = set()
    while total > cap and i < len(files):
        p = files[i]
        try:
            sz = os.path.getsize(p)
            os.remove(p)
            total -= sz
            deleted.add(os.path.normcase(os.path.abspath(p)))
            log(f"Storage cap: deleted oldest clip {os.path.basename(p)}")
        except Exception:
            pass
        i += 1
    if deleted:
        with _MANIFEST_LOCK:      # re-read: saves may have added entries meanwhile
            cur, _e = _load_manifest()
            if cur is not None:
                _save_manifest(cur - deleted)


def _audio_track_names(path):
    """What each audio track of a recording calls itself, in order.

    A layered (2.81+) file names its tracks Mix / System / Mic; anything
    older, or anything the tome did not record, comes back as a list of
    empty strings. THE POSITION IS THE POINT - it is what -map 0:a:N
    counts - so codec_type is asked for as well as the tags, to keep one
    row per audio stream whatever ffprobe decides to print for a stream
    that carries no tags at all."""
    try:
        d = os.path.dirname(SETTINGS["ffmpeg_path"])
        probe = os.path.join(d, "ffprobe.exe" if os.name == "nt"
                             else "ffprobe")
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([probe, "-v", "error", "-select_streams", "a",
                            "-show_entries",
                            "stream=codec_type:stream_tags=title,name",
                            "-of", "json", path],
                           capture_output=True, text=True, timeout=30,
                           creationflags=flags)
        streams = (json.loads(r.stdout or "{}") or {}).get("streams") or []
        # the mp4 muxer files a stream title under 'name'
        return [str((st.get("tags") or {}).get("title")
                    or (st.get("tags") or {}).get("name") or "").lower()
                for st in streams]
    except Exception:
        return []


def _mic_track(path, names=None):
    """The Mic layer's audio-stream index in a layered (2.81+) recording,
    or None for older mixed files - callers then read the default track
    exactly as they always did. Pass `names` when the caller has already
    probed: two probes of the same file can disagree if one of them times
    out on a cold disk, and then the mic gets extracted beside a mix that
    was never built."""
    names = _audio_track_names(path) if names is None else names
    return names.index("mic") if "mic" in names else None


def _mix_audio_args(path, names=None):
    """The ffmpeg arguments that extract EVERYTHING AUDIBLE from a
    recording - what a player would hear, him included.

    ffmpeg picks a default audio stream when you do not name one: the
    lowest-numbered track of the widest layout. On a layered file that IS
    the Mix (checked byte for byte against the default pick on
    hearthstone_20260816_153823), but with audio_mode="separate" there is
    no Mix track at all and the default lands on System - the one track
    his own microphone is not in. Measured on a 120s slice of that same
    night remuxed as separate: the default pick gave the voice detector
    6.4s of speech and NONE of the 7.2s his mic had actually captured;
    summing the layers gives 13.7s and all 7.2s of it, matching the real
    Mix track to a thousandth of a peak.

    The sum uses normalize=0 because that is exactly how the recorder
    builds its own Mix track (see _record_cmd), so this is at parity with
    it and not louder. A file the tome did not record keeps the old
    behaviour untouched: we only build a mix out of layers we can name."""
    names = _audio_track_names(path) if names is None else names
    if "mix" in names:
        return ["-vn", "-map", "0:a:%d" % names.index("mix")]
    if len(names) < 2 or "mic" not in names:
        return ["-vn"]
    ins = "".join("[0:a:%d]" % i for i in range(len(names)))
    return ["-vn", "-filter_complex",
            ins + ("amix=inputs=%d:duration=longest:normalize=0[a]"
                   % len(names)),
            "-map", "[a]"]


def _probe_duration(path):
    """Return the media duration in seconds via ffprobe, or None."""
    if not path or not os.path.isfile(path):
        return None
    d = os.path.dirname(SETTINGS["ffmpeg_path"])
    name = "ffprobe.exe" if os.name == "nt" else "ffprobe"
    exe = os.path.join(d, name) if d else "ffprobe"
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run(
            [exe, "-v", "error", "-show_entries", "format=duration",
             "-of", "default=nw=1:nokey=1", path],
            capture_output=True, text=True, creationflags=flags, timeout=15)
        return float(r.stdout.strip())
    except Exception:
        return None


def build_mux_cmd(video, system_wav, mic_wav, out_final, offset_ms=0, mic_offset_ms=None,
                  video_is_concat=False):
    """offset_ms shifts the system track; mic_offset_ms the mic track (defaults to
    the same). Each stream gets its OWN correction because they start at slightly
    different wall-clock moments. video_is_concat=True treats `video` as a concat
    list file (the segments are read directly - saves writing the multi-GB merged
    intermediate, which doubled save time on hard drives)."""
    s = SETTINGS
    vin = (["-f", "concat", "-safe", "0", "-i", video] if video_is_concat
           else ["-i", video])
    cmd = [s["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "warning"] + vin

    audio_inputs = []  # (label, path, offset_ms)
    if system_wav and os.path.isfile(system_wav):
        cmd += ["-i", system_wav]
        audio_inputs.append(("System", system_wav, offset_ms))
    if mic_wav and os.path.isfile(mic_wav):
        cmd += ["-i", mic_wav]
        audio_inputs.append(("Mic", mic_wav,
                             offset_ms if mic_offset_ms is None else mic_offset_ms))

    n = len(audio_inputs)
    if n == 0:
        cmd += ["-map", "0:v", "-c:v", "copy", out_final]
        return cmd

    # A/V sync correction, BAKED INTO THE SAMPLES. We used to delay the audio with
    # -itsoffset, but that records the shift as an MP4 edit-list / start-time, which
    # many players silently ignore - so the audio still played early. Prepending real
    # silence (adelay) for a positive offset, or trimming the head (atrim) for a
    # negative one, physically moves the audio and survives every player.
    def _sync(ms):
        off = int(round(ms))
        if off > 0:
            return f",adelay=delays={off}:all=1"        # audio starts late -> pad its head
        if off < 0:
            return (f",atrim=start={(-off) / 1000.0:.3f},"
                    "asetpts=PTS-STARTPTS")             # audio starts early -> trim its head
        return ""

    # Normalize EVERY audio input to clean stereo 48 kHz before doing anything
    # else. Capturing a virtual surround device (e.g. SteelSeries Sonar - Gaming)
    # yields 8ch @ 96kHz; left as-is the file is 7.1/96kHz, which a player has to
    # downmix on the fly - that's the hollow/harsh "tunnel" sound. Resampling to
    # 48k and doing a proper stereo downmix here once makes it play clean
    # everywhere.
    pre = [f"[{i + 1}:a]aresample=48000,aformat=channel_layouts=stereo"
           f"{_sync(audio_inputs[i][2])}[a{i}]" for i in range(n)]

    if n >= 2 and s["audio_mode"] == "mix":
        # THE LAYERED BIND (2.81). Track 0 stays the mix - every player and
        # the tome hear exactly what they always did - but System and Mic
        # ride along as their own tracks, so the AI can tell HIS voice from
        # the game's without un-mixing guesswork. asplit, because a filter
        # pad may only feed one consumer.
        ins = "".join(f"[s{i}]" for i in range(n))
        split = ";".join(f"[a{i}]asplit=2[s{i}][t{i}]" for i in range(n))
        graph = ";".join(pre + [split,
                                f"{ins}amix=inputs={n}"
                                f":duration=longest:normalize=0[a]"])
        cmd += ["-filter_complex", graph, "-map", "0:v", "-map", "[a]"]
        for i in range(n):
            cmd += ["-map", f"[t{i}]"]
        cmd += ["-c:v", "copy", "-c:a", "aac", "-b:a", "192k",
                "-metadata:s:a:0", "title=Mix"]
        for i, (label, _p, _o) in enumerate(audio_inputs):
            cmd += [f"-metadata:s:a:{i + 1}", f"title={label}"]
        cmd += [out_final]
    else:
        cmd += ["-filter_complex", ";".join(pre), "-map", "0:v"]
        for i in range(n):
            cmd += ["-map", f"[a{i}]"]
        cmd += ["-c:v", "copy", "-c:a", "aac", "-b:a", "192k"]
        if n >= 2:
            for i, (label, _p, _o) in enumerate(audio_inputs):
                cmd += [f"-metadata:s:a:{i}", f"title={label}"]
        cmd += [out_final]
    return cmd


# ---------------------------------------------------------------------------
#  SDR finishing - convert native-HDR files to normal SDR AFTER the session
#  (never during gameplay: no live conversion of the float16 source can keep up
#  at high resolutions, so the conversion is done offline instead)
# ---------------------------------------------------------------------------
# 'path'/'t0'/'pct' are read by the dashboard to show a live "Converting..."
# badge (with real percent progress) on the file's card while ffmpeg works.
_FINISHING = {"proc": None, "path": None, "t0": 0.0, "pct": None,
              "busy": False, "aborted": False}

# Live BIND (save-mux) progress, read by state() for the tome's saving card:
# pct from ffmpeg's -progress out_time vs the session's known length, MB/s from
# the growing temp file. Also the instrumentation for "why was that save slow" -
# the completion log line records wall time, size and speed for every bind.
_BIND_TOK = [0]     # concurrent binds (chapter split + game close + a clip)
#                     used to co-write one card - percentages flapping between
#                     two names. The newest owner writes; elders go silent.
_BINDING = {"name": None, "pct": None, "eta": None, "mbps": None,
            "t0": 0.0, "total": 0.0}
_CONCAT_WATCH = {"stop": True, "ev": None}   # the stream-copy progress watcher
_SALVAGE_FAILS = {}    # session folder -> how many launches its re-weld failed
_TRAY_ICON = [None]    # the pystray icon, stashed so the bind loop can whisper
                       # progress into the tooltip without threading ctl through
_FINISH_FAILS = {}     # path -> genuine failure count (interruptions don't count)

# Files the user is actively READING right now (the in-tome player streaming,
# the trim tool cutting). The SDR finisher must not try to replace these:
# Windows os.replace fails while any plain handle is open, and that failure
# used to burn the 3-strike budget for what was really just "you were
# watching it". Refcounted because the player issues overlapping range reads.
_ACTIVE_SOURCES = {}
_ACTIVE_LOCK = threading.Lock()


def _source_busy_add(path):
    ap = os.path.abspath(path)
    with _ACTIVE_LOCK:
        _ACTIVE_SOURCES[ap] = _ACTIVE_SOURCES.get(ap, 0) + 1


def _source_busy_done(path):
    ap = os.path.abspath(path)
    with _ACTIVE_LOCK:
        n = _ACTIVE_SOURCES.get(ap, 0) - 1
        if n <= 0:
            _ACTIVE_SOURCES.pop(ap, None)
        else:
            _ACTIVE_SOURCES[ap] = n


def _source_busy(path):
    with _ACTIVE_LOCK:
        return os.path.abspath(path) in _ACTIVE_SOURCES


def _finish_queue_path():
    return os.path.join(_data_dir(), "finish_queue.json")


# the queue is edited from the worker, the watcher tick, trims, deletes and
# Discord copies - like the manifest, its read-modify-write pairs need a lock
# or two writers interleave and one update is silently lost (RLock: the pairs
# below hold it across their load+save while load/save also take it solo)
_FINISH_Q_LOCK = threading.RLock()


def _load_finish_queue(strict=False):
    """Queue entries are dicts {'path', 'nits'}: nits = the Windows SDR white
    level when the file was recorded, because the conversion must use the value
    from RECORD time even if the user moves the slider (or turns HDR off) before
    the conversion gets its idle moment. Plain-string entries from 1.23 are
    accepted and upgraded (their nits defaults at convert time).

    strict: an EXISTING queue file that cannot be read RAISES instead of
    returning [] - a read-modify-write caller must never persist emptiness
    over a real queue because of one transient read failure (that silently
    dropped every pending HDR conversion, forever)."""
    try:
        with _FINISH_Q_LOCK:
            with open(_finish_queue_path(), encoding="utf-8") as fh:
                raw = json.load(fh)
        out = []
        for it in raw:
            if isinstance(it, str):
                out.append({"path": it, "nits": None})
            elif isinstance(it, dict) and isinstance(it.get("path"), str):
                out.append({"path": it["path"], "nits": it.get("nits")})
        return out
    except FileNotFoundError:
        return []
    except Exception as e:
        if strict and os.path.isfile(_finish_queue_path()):
            log(f"The SDR queue could not be read ({e}) - "
                "leaving it exactly as it is.")
            raise
        return []


def _save_finish_queue(items):
    try:
        with _FINISH_Q_LOCK:
            _atomic_write_json(_finish_queue_path(), items)
        _FINISH_Q_CACHE["t"] = 0.0   # every writer lands here - wake the read cache
    except Exception:
        pass


def _queue_sdr_finish(path):
    """Remember that this recording/clip is HDR and should be converted to SDR
    once nothing is recording. Persisted, so it survives a restart. The current
    SDR white level is captured HERE (seconds after the recording ended) - see
    _load_finish_queue for why it rides along."""
    try:
        if not SETTINGS.get("sdr_finish", True) or not path:
            return
        ap0 = os.path.normcase(os.path.abspath(path))
        if any(os.path.normcase(os.path.abspath(str(x))) == ap0
               for x in (SETTINGS.get("sdr_optout") or [])):
            return                 # he chose to keep this one HDR
        if not _is_hdr_trc(_probe_color_trc(path)):
            return                     # already SDR
        dur = _probe_duration(path) or 0
        cap_min = int(SETTINGS.get("sdr_finish_max_min", 30) or 30)
        if dur > cap_min * 60:
            log(f"SDR finish skipped ({dur / 60:.0f} min > {cap_min} min cap): "
                + os.path.basename(path))
            return
        # one locked unit: a delete's queue rewrite racing this append used to
        # overwrite the new entry - the file then stayed HDR forever, silently
        with _FINISH_Q_LOCK:
            q = _load_finish_queue(strict=True)
            ap = os.path.abspath(path)
            if not any(it["path"] == ap for it in q):
                q.append({"path": ap, "nits": _sdr_white_nits() or 240})
                _save_finish_queue(q)
                log("Queued for SDR conversion: " + os.path.basename(path))
    except Exception:
        pass


def _sdr_finish_abort():
    """A recording is starting: stop any in-flight conversion immediately (the
    file stays queued and is retried later). GPU belongs to the game.
    STICKY: the flag is set whenever the worker is busy - during its probe
    window there is no proc yet, and the old proc-only version silently
    no-opped there, letting a full re-encode fight the whole game session."""
    if not _FINISHING["busy"]:
        return
    _FINISHING["aborted"] = True
    p = _FINISHING.get("proc")
    if p is not None and p.poll() is None:
        try:
            p.terminate()
        except Exception:
            pass


_FINISH_Q_CACHE = {"t": 0.0, "q": []}


def _queued_finish_paths():
    """The queue as plain paths, through a small cache. state() polls every
    ~.6s and the badge scans hit this per file - each used to be a fresh file
    read + json parse. 5s is safe: _save_finish_queue zeroes the clock, so a
    real change still shows on the very next tick."""
    now = time.time()
    if now - _FINISH_Q_CACHE["t"] > 5.0:
        _FINISH_Q_CACHE["q"] = ([it["path"] for it in _load_finish_queue()]
                                if SETTINGS.get("sdr_finish", True) else [])
        _FINISH_Q_CACHE["t"] = now
    return _FINISH_Q_CACHE["q"]


def _finish_badge(path):
    """What the dashboard should say on this file's card:
        ('Making standard version - 43%', 'conv')  while ffmpeg works on it
        ('Fine to watch - converts when idle', 'wait')  while it waits its turn
        None                                        for a normal file
    Wording matters here: the recording is a CORRECT HDR file that already
    plays well in modern players - the conversion only makes it a smaller,
    standard video that works everywhere. The badge must not imply the file
    is broken while it waits (that read as 'what is it even converting?').
    The file stays clickable the whole time - conversion writes to a temp name
    and swaps in atomically. Queue reads ride the ~5s
    _queued_finish_paths cache (writes wake it) - the cards poll every second
    and the queue is a file on disk."""
    try:
        ap = os.path.abspath(path)
        if _FINISHING["busy"] and _FINISHING["path"] == ap:
            pct = _FINISHING.get("pct")
            if pct is not None:
                return (f"Restoring true colour — {pct:.0f}%", "conv")
            el = max(0, int(time.time() - (_FINISHING["t0"] or time.time())))
            return (f"Restoring true colour — {el // 60}:{el % 60:02d}", "conv")
        if ap in _queued_finish_paths():
            return ("Fine to watch — restores colour when idle", "wait")
    except Exception:
        pass
    return None


def _sdr_finish_worker(item, ctl=None):
    """Convert one HDR file to SDR in place with the measured-correct chain
    (_hdr_to_sdr_vf at the record-time SDR white level), re-encode with the
    machine's hardware encoder, copy the audio untouched, verify the result,
    then replace ATOMICALLY. The original is never at risk: any failure keeps
    it exactly as it was. A file that genuinely fails 3 times is dropped from
    the queue (with its HDR original intact) rather than retried forever."""
    path = item["path"]
    tmp_out = path + ".__sdr__.mp4"
    ok = False
    aborted = False
    try:
        # RE-CHECK before burning an idle hour: a queue entry can go stale (the
        # file was trim-replaced with an SDR cut while its dequeue was racing
        # another writer). Tone-mapping an already-SDR file crushes its colours.
        trc = _probe_color_trc(path)
        if not _is_hdr_trc(trc):
            ok = True          # nothing to do; the finally-block dequeues it
            return
        dur = _probe_duration(path) or 0
        vf = (_hdr_to_sdr_vf(trc, item.get("nits"))
              + ",format=nv12")
        enc = _current_encoder()
        br = int(SETTINGS.get("bitrate_mbps", 25))
        # Below-normal priority so this HDR->SDR re-encode NEVER starves video
        # playback, the editor or the UI. The conversion is a background nicety;
        # the app must stay responsive while it runs (at normal priority it fought
        # the in-tome player for CPU/GPU/disk, which is what made everything
        # stutter and feel like "saving is still happening").
        flags = ((subprocess.CREATE_NO_WINDOW
                  | getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0))
                 if os.name == "nt" else 0)
        _FINISHING["pct"] = None
        if _FINISHING["aborted"]:
            # the abort landed during the probes above (it is sticky now) -
            # honor it before spawning a full-length re-encode into a game
            # session. The entry stays queued; no strike.
            aborted = True
            return
        cmd = [SETTINGS["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error",
               "-progress", "pipe:1", "-nostats",
               "-i", path, "-vf", vf, "-c:v", enc,
               *encoder_quality_flags(enc, br),
               "-color_primaries", "bt709", "-color_trc", "bt709",
               "-colorspace", "bt709",
               # no +faststart here: it re-writes the ENTIRE multi-GB file at
               # the end (a whole extra disk pass) and only matters for web
               # streaming - local players and Discord's own re-encode don't care.
               "-c:a", "copy", tmp_out]
        proc = _popen(cmd, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, creationflags=flags)
        _FINISHING["proc"] = proc
        err_tail = bytearray()

        def _read_err():
            # drain stderr as it comes: a decode-error-spamming source would
            # otherwise fill the 64K pipe and wedge ffmpeg until the watchdog
            # kills it - a stall billed as a strike the file didn't earn
            try:
                for raw_e in proc.stderr:
                    err_tail.extend(raw_e)
                    del err_tail[:-4096]
            except Exception:
                pass
        threading.Thread(target=_read_err, daemon=True).start()

        def _read_progress():
            # ffmpeg -progress emits 'out_time_ms=<microseconds>' lines; against
            # the known duration that's an honest percent for the card badge.
            try:
                for raw in proc.stdout:
                    ln = raw.decode("ascii", "ignore").strip()
                    if ln.startswith("out_time_ms=") and dur > 0:
                        try:
                            done = int(ln.split("=", 1)[1]) / 1_000_000.0
                            _FINISHING["pct"] = max(0, min(99, done / dur * 100))
                        except ValueError:
                            pass
            except Exception:
                pass
        threading.Thread(target=_read_progress, daemon=True).start()
        try:
            proc.wait(timeout=max(600, dur * 6 + 120))
        except subprocess.TimeoutExpired:
            proc.kill()
        aborted = _FINISHING["aborted"]
        if proc.returncode == 0 and os.path.isfile(tmp_out):
            new_dur = _probe_duration(tmp_out) or 0
            if dur <= 0 or abs(new_dur - dur) <= max(2.0, dur * 0.02):
                try:
                    os.replace(tmp_out, path)  # atomic: SDR takes the file's place
                    ok = True
                except PermissionError:
                    # The user is watching or cutting this exact file right
                    # now - that's not a conversion failure, so it must not
                    # burn a strike. Leave the queue entry for the next idle.
                    aborted = True
                    log("SDR conversion finished but the file is in use "
                        "(playing or being cut); will retry later: "
                        + os.path.basename(path))
            if ok:
                log("SDR conversion done: " + os.path.basename(path))
                # Refresh the cached thumbnail: the file's colours just changed.
                try:
                    tp = os.path.join(
                        _thumb_dir(os.path.dirname(path)),
                        os.path.splitext(os.path.basename(path))[0] + ".jpg")
                    if os.path.isfile(tp):
                        os.remove(tp)
                except Exception:
                    pass
                if ctl is not None:
                    try:
                        ctl.notify("Ready to share",
                                   os.path.basename(path) + " is now normal colour.")
                    except Exception:
                        pass
            elif not aborted:
                log(f"SDR conversion length mismatch ({new_dur:.1f}s vs "
                    f"{dur:.1f}s); keeping the HDR original.")
        elif aborted:
            log("SDR conversion paused (recording started); will retry later.")
        else:
            err = bytes(err_tail)
            for ln in err.decode("utf-8", "ignore").strip().splitlines()[-2:]:
                log("  ffmpeg(sdr): " + ln)
            log("SDR conversion attempt failed; keeping the HDR original for now.")
    except Exception as e:
        log(f"SDR conversion error ({e}); keeping the HDR original.")
    finally:
        _FINISHING["proc"] = None
        _FINISHING["path"] = None
        _FINISHING["pct"] = None
        try:
            if os.path.isfile(tmp_out):
                os.remove(tmp_out)
        except Exception:
            pass
        # Success (or a vanished source) leaves the queue. An ABORT keeps the entry
        # for the next idle. A genuine failure counts toward a 3-strike drop, so a
        # machine that can't convert doesn't spin ffmpeg forever. The whole
        # load->filter->save is one locked unit so a trim/delete editing the
        # queue at the same moment can't have its update overwritten.
        try:
            with _FINISH_Q_LOCK:
                q = _load_finish_queue(strict=True)
                ap = os.path.abspath(path)
                if ok or not os.path.isfile(path):
                    q = [x for x in q if x["path"] != ap]
                    _save_finish_queue(q)
                    _FINISH_FAILS.pop(ap, None)
                elif not aborted:
                    n = _FINISH_FAILS.get(ap, 0) + 1
                    _FINISH_FAILS[ap] = n
                    if n >= 3:
                        q = [x for x in q if x["path"] != ap]
                        _save_finish_queue(q)
                        log("SDR conversion given up after 3 attempts "
                            "(file stays HDR): " + os.path.basename(path))
        except Exception:
            pass            # unreadable queue: leave it exactly as it is
        _FINISHING["busy"] = False


def _sdr_finish_tick(ctl):
    """Called from the watcher's idle beat: start ONE queued conversion when
    nothing is recording or saving. The moment a game appears, the watcher
    calls _sdr_finish_abort() and the GPU is the game's again."""
    if _FINISHING["busy"] or not SETTINGS.get("sdr_finish", True):
        return
    if ctl.session is not None or ctl.saving > 0:
        return
    # Don't fight interactive playback/editing: if the media server streamed a
    # chunk in the last 20s the user is watching or scrubbing a video - leave the
    # machine to them and resume the conversion once they've stopped.
    if time.time() - _MEDIA.get("last_read", 0) < 20:
        return
    try:
        with _FINISH_Q_LOCK:
            q = _load_finish_queue(strict=True)
            q = [it for it in q if os.path.isfile(it["path"])]
            if not q:
                return
            _save_finish_queue(q)
    except Exception:
        return              # unreadable queue: convert nothing, erase nothing
    # Never convert a file the user is watching or cutting right now - the
    # final os.replace would fail against their open handle anyway.
    pick = next((it for it in q if not _source_busy(it["path"])), None)
    if pick is None:
        return
    _FINISHING["aborted"] = False    # armed fresh for THIS job; sticky after
    _FINISHING["busy"] = True
    _FINISHING["path"] = pick["path"]     # dashboard badge reads these two
    _FINISHING["t0"] = time.time()
    threading.Thread(target=_sdr_finish_worker, args=(pick, ctl), daemon=True).start()


def _drain_stderr(proc, first_frame, tail):
    """Continuously drain ffmpeg's stderr so its pipe never blocks (which would
    freeze long recordings), and signal as soon as the first frame appears.
    Keeps a rolling tail of ALL stderr (in the `tail` bytearray) so that if the
    encoder dies - even during start-up, before any frame - we can log WHY."""
    try:
        while True:
            chunk = proc.stderr.read1(65536)
            if not chunk:
                break
            if not first_frame.is_set() and b"frame=" in chunk:
                first_frame.set()
            tail += chunk
            if len(tail) > 8000:           # keep only the last ~8 KB
                del tail[:-8000]
    except Exception:
        pass


# ---------------------------------------------------------------------------
#  Recording session
# ---------------------------------------------------------------------------
class Session:
    """One recording. Internally it can span several capture 'runs' (Pause stops
    a run keeping the footage; Continue starts the next run). At the end the runs
    are stitched into a single file with the paused gaps removed. Each run is
    muxed with its own A/V sync, so pause joints stay in sync; a normal one-run
    recording takes the simple proven path."""

    def __init__(self, game_name):
        self.game = game_name
        base = os.path.splitext(game_name)[0]
        try:
            _learn_game_display_name(game_name)
        except Exception:
            pass
        stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        # NOTE: the output_dir is created in start(), not here, so an unwritable /
        # disconnected save folder surfaces inside _safe_start's try (where it can be
        # explained to the user) instead of escaping Session() construction.
        self.base = base
        self.tmp = os.path.join(_work_dir(), f"{base}_{stamp}")
        os.makedirs(self.tmp, exist_ok=True)
        self.seg_pattern = os.path.join(self.tmp, "seg_%06d.mp4")
        self.final = os.path.join(_game_shelf(base, "session", make=False),
                                  f"{base}_{stamp}.mp4")
        self.vproc = None
        self.audio = None
        self.monitor_idx = None        # which screen to capture (resolved at start)
        self.win = None                # window-only capture rect (see _game_window_rect)
        self.win_paused = False        # auto-paused: the game window is minimised
        self._win_pend = None          # rect waiting to settle (move/resize debounce)
        self._win_lost = 0.0           # when the game's window first went missing
        self._rotating = False         # mid rotate-run swap (blocks replay clips)
        self._gone_polls = 0           # consecutive polls the game looked closed
        self._pause_toasted = False    # auto-pause toast shown (once per session)
        self.afk_paused = False        # auto-paused: the user is away
        self.cap_wh = None             # frame size this file is locked to
        self.file_hdr = None           # HDR mode this file is locked to
        self._restart_streak = 0       # capture restarts, decayed (see _note_restart)
        self._last_restart = 0.0
        self._wgc = None               # live _WGCFeed when WGC transports this run
        self._first_frame = threading.Event()
        self._err = bytearray()        # rolling tail of the encoder's stderr
        self._replay_lock = threading.Lock()
        self.suspended = False
        self._hdr_used = False          # did the active run use HDR tone-mapping?
        self.runs = []                 # finished runs: {"sys","mic","nseg"}
        self._run_index = 0
        self._seg_start = 0            # next segment number (continues across pauses)
        self._run_vstart = 0          # first segment number of the current run

    # ---- capture run lifecycle --------------------------------------------
    def _start_run(self):
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        self._first_frame = threading.Event()
        self._err = bytearray()
        self._run_vstart = self._seg_start
        # Remember whether THIS run is doing HDR capture, so the watcher can tell
        # an HDR path failure (recoverable by falling back to plain) from a dead
        # encoder. Mirror build_video_cmd's guard exactly: float16 HDR runs only
        # on a 10-bit-capable AMF encoder - any other encoder records PLAIN even
        # in auto mode, so it must not be flagged as HDR (wrong toast, wasted
        # ladder step, delayed encoder recovery).
        strat = _hdr_strategy()
        enc_now = _current_encoder()
        if strat == "native" and not (enc_now.endswith("_amf")
                                      and _enc_supports_10bit(enc_now)):
            strat = None
        self._hdr_used = bool(strat and _HDR_LEVEL[0] < 1)
        # THE FILE'S LAWS, enforced at the ONE door every transport uses:
        # a file with committed segments never accepts a run of a different
        # frame size or HDR mode - the -c copy weld would produce a broken
        # video reported as 'Saved'. Raising here makes resume/restart FAIL,
        # which the watcher's health check turns into a clean chapter split.
        if _list_segments(self.tmp):
            if (self.file_hdr is not None
                    and self._hdr_used != self.file_hdr):
                raise RuntimeError(
                    "HDR mode changed mid-session; this file is "
                    f"{'HDR' if self.file_hdr else 'SDR'}")
        else:
            self.file_hdr = self._hdr_used
        # AUDIO FIRST: the microphone and system streams open in well under a
        # second, while ffmpeg takes 1-3s to produce its first frame. Starting
        # audio first means the opening seconds of the game are never lost, and
        # the wall-clock sync anchors trim the surplus head off precisely.
        # (The old order started audio ~3s late and relied on a duration guess
        # to compensate - see _assemble for why that broke.)
        self.audio = None
        if SETTINGS["capture_system"] or SETTINGS["capture_mic"]:
            try:
                # re-resolve the tap target EVERY run: a crash-relaunched
                # game keeps its exe name (same session) but a new pid
                if SETTINGS.get("game_audio_only") and SETTINGS.get("capture_system"):
                    try:
                        pid_now = None
                        if self.win and self.win.get("hwnd"):
                            import ctypes as _ct
                            from ctypes import wintypes as _wt
                            _p = _wt.DWORD()
                            _ct.windll.user32.GetWindowThreadProcessId(
                                self.win["hwnd"], _ct.byref(_p))
                            pid_now = _p.value or None
                        if not pid_now and self.game.lower() != "screen":
                            pid_now = _pid_for_exe(self.game)
                        if pid_now:
                            self.game_pid = pid_now
                    except Exception:
                        pass
                self.audio = AudioRecorder(self.tmp, tag=f"{self._run_index:02d}",
                                           game_pid=getattr(self, "game_pid", None))
                self.audio.start()
            except Exception as e:
                log(f"Audio init failed ({e}); recording video only.")
                # Unwind any HALF-started capture (e.g. system opened, mic failed):
                # without this the orphaned stream + writer thread would keep the
                # device busy and grow a WAV in the tmp dir for the whole session.
                try:
                    if self.audio is not None:
                        self.audio.stop()
                except Exception:
                    pass
                self.audio = None
        # LORE 2.0: window scope prefers Windows Graphics Capture - the
        # WINDOW is the source, so overlays can't appear, the feed follows
        # the window anywhere, and alt-tab can't kill it. Falls back to the
        # proven ddagrab subrect when: forced by setting, the desktop is HDR
        # (WGC is SDR-only; ddagrab keeps the float16 HDR path), the window
        # is too large for the raw pipe (>4.2MP measured ceiling), the
        # module is missing, or WGC never shows a first frame (exclusive
        # fullscreen). A resumed run must match the file's locked size.
        self._wgc = None
        # Say WHY when the real window capture is not used. This was silent,
        # and it hid a shipping bug for a whole release: the updater never
        # copied _internal, so `import windows_capture` failed on the user's
        # machine and LORE quietly served the old screen-region crop while
        # the settings page still promised window capture.
        if self.win and self.win.get("hwnd"):
            why = None
            if str(SETTINGS.get("capture_backend", "auto")) != "auto":
                why = "the setting forces the screen-region capture"
            elif not _wgc_available():
                why = ("the windows-capture module is missing from this "
                       "install - reinstall LORE to get true window capture")
            elif _hdr_active():
                why = "the desktop is in HDR (window capture is SDR-only)"
            elif self.win["w"] * self.win["h"] > 4_200_000:
                why = (f"the window is {self.win['w']}x{self.win['h']} - too "
                       f"large for the frame pipe (limit ~4.2 megapixels)")
            if why and why != getattr(self, "_wgc_said", None):
                self._wgc_said = why
                log(f"Window capture: recording the SCREEN REGION because "
                    f"{why}. Things in front of the window will be recorded.")
        if (self.win and self.win.get("hwnd")
                and str(SETTINGS.get("capture_backend", "auto")) == "auto"
                and _wgc_available() and not _hdr_active()
                and self.win["w"] * self.win["h"] <= 4_200_000):
            try:
                feed = _WGCFeed(self.win["hwnd"], int(SETTINGS["framerate"]))
                size = feed.begin()
                if size and size[0] * size[1] <= 4_200_000 and (
                        self.cap_wh is None or not _list_segments(self.tmp)
                        or (size[0], size[1]) == tuple(self.cap_wh)):
                    self.vproc = _popen(
                        build_wgc_cmd(size[0], size[1],
                                      int(SETTINGS["framerate"]),
                                      self.seg_pattern,
                                      start_number=self._seg_start),
                        stdin=subprocess.PIPE, stdout=subprocess.DEVNULL,
                        stderr=subprocess.PIPE, creationflags=flags,
                        bufsize=0,
                    )
                    feed.attach(self.vproc.stdin)
                    self._wgc = feed
                    self.cap_wh = (size[0], size[1])
                    self._hdr_used = False        # WGC frames are SDR
                    log(f"Window capture via Windows Graphics Capture: "
                        f"{size[0]}x{size[1]} (overlay-proof).")
                elif size:
                    feed.stop()
                    log("WGC size differs from this file's format; using the "
                        "screen-region capture for this run.")
                else:
                    log("WGC saw no frames from this window (exclusive "
                        "fullscreen?); using the screen-region capture.")
            except Exception as e:
                log(f"WGC unavailable ({e}); using the screen-region capture.")
                try:
                    feed.stop()        # a live capture session must not linger
                except Exception:
                    pass
                self._wgc = None
        if self._wgc is None:
            if _list_segments(self.tmp) and self.cap_wh:
                intend = ((self.win["w"], self.win["h"]) if self.win
                          else _screen_capture_wh(self.monitor_idx))
                if intend and tuple(intend) != tuple(self.cap_wh):
                    # a WGC-recorded file must not continue at ddagrab's
                    # (differently-aligned) size - end the chapter instead
                    raise RuntimeError(
                        f"capture size changed ({intend} vs {self.cap_wh})")
            self.vproc = _popen(
                build_video_cmd(self.seg_pattern, start_number=self._seg_start,
                                # window scope already carries a real
                                # output index; screen scope converts here
                                monitor_index=(self.win["mon"] if self.win
                                               else _capture_output_idx(
                                                   self.monitor_idx)),
                                window_rect=((self.win["x"], self.win["y"],
                                              self.win["w"], self.win["h"])
                                             if self.win else None)),
                stdin=subprocess.PIPE, stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE, creationflags=flags,
            )
        threading.Thread(target=_drain_stderr,
                         args=(self.vproc, self._first_frame, self._err),
                         daemon=True).start()
        self._first_frame.wait(timeout=1.5)

    def err_text(self):
        """The encoder's recent stderr (so a crash can be diagnosed)."""
        try:
            return bytes(self._err).decode("utf-8", "ignore").strip()
        except Exception:
            return ""

    def _stop_run(self):
        """Stop the current capture run cleanly and record what it produced."""
        v_end_wall = None
        if self.audio:
            self.audio.signal_stop()
        if getattr(self, "_wgc", None) is not None:
            try:
                self._wgc.stop()           # stops capture, closes stdin -> EOF
                v_end_wall = time.time()
            except Exception:
                pass
            self._wgc = None
        elif self.vproc and self.vproc.poll() is None:
            try:
                self.vproc.stdin.write(b"q")
                self.vproc.stdin.flush()
                v_end_wall = time.time()   # capture halts ~here; flush adds no PTS
            except Exception:
                pass
        else:
            # Salvage path: the encoder died up to a poll earlier. The newest
            # segment's mtime is when video really ended - anchoring on 'now'
            # would shift the whole audio track early by the detection delay.
            try:
                segs = _list_segments(self.tmp)
                if segs:
                    v_end_wall = os.path.getmtime(segs[-1])
            except Exception:
                pass
        if self.audio:
            self.audio.finalize()
        if self.vproc and self.vproc.poll() is None:
            try:
                self.vproc.wait(timeout=20)
            except subprocess.TimeoutExpired:
                # ffmpeg ignored the graceful 'q'; terminate, and if it STILL
                # hasn't exited shortly after, kill it so a stuck encoder can't
                # wedge the rest of the save.
                try:
                    self.vproc.terminate()
                    self.vproc.wait(timeout=8)
                except Exception:
                    try:
                        self.vproc.kill()
                    except Exception:
                        pass
        if v_end_wall is None:
            v_end_wall = time.time()  # last-resort anchor (no 'q' sent, no segments)
        total = len(_list_segments(self.tmp))
        nseg = max(0, total - self._run_vstart)
        sysw = (self.audio.system_wav if self.audio and self.audio.system_wav
                and os.path.isfile(self.audio.system_wav) else None)
        micw = (self.audio.mic_wav if self.audio and self.audio.mic_wav
                and os.path.isfile(self.audio.mic_wav) else None)
        if nseg > 0 or sysw or micw:
            self.runs.append({
                "sys": sysw, "mic": micw, "nseg": nseg,
                "v_end_wall": v_end_wall,
                "sys_t0": self.audio.first_sample_wallclock("system") if self.audio else None,
                "mic_t0": self.audio.first_sample_wallclock("mic") if self.audio else None,
            })
        self._seg_start = total
        self._run_index += 1
        self.vproc = None
        self.audio = None

    def start(self):
        # Create the save folder here (not in __init__) so a permission/offline-drive
        # error is caught by _safe_start and shown to the user in plain language.
        os.makedirs(SETTINGS["output_dir"], exist_ok=True)
        os.makedirs(os.path.dirname(self.final), exist_ok=True)
        self.monitor_idx = _resolve_capture_monitor()
        # Experimental window-only scope: crop the GPU screen capture to the
        # game's own window (manual desktop recordings use the whole screen).
        if (str(SETTINGS.get("capture_scope", "screen")) == "window"
                and self.game and self.game.lower() != "screen"):
            w = _game_window_rect(self.game)
            if w and not w.get("iconic"):
                self.win = w
                log(f"Window capture (experimental): {w['w']}x{w['h']} at "
                    f"+{w['x']},+{w['y']} on screen #{w['mon'] + 1}.")
            else:
                # No usable window right now - minimised (iconic), still
                # launching, or hidden to the tray. Recording the desktop
                # instead would betray "only the game window", so start
                # PAUSED and let the tracker begin capture the moment a real
                # window appears (any size is fine then: nothing committed
                # yet). If the window never comes, the process eventually
                # exits and the game-gone check finalises the empty session.
                self.win = {"hwnd": (w or {}).get("hwnd"), "mon": 0,
                            "x": 0, "y": 0, "w": 0, "h": 0}
                self.win_paused = True
                self.suspended = True
                log("Window capture: waiting for the game's window before "
                    "recording (no desktop is captured).")
        log(f"Detected '{self.game}'. Recording -> {self.final}")
        # who to tap for game-audio-only: the window's owner when we have it
        # (exact), else the first process wearing the game's name
        self.game_pid = None
        if SETTINGS.get("game_audio_only") and SETTINGS.get("capture_system"):
            try:
                if self.win and self.win.get("hwnd"):
                    import ctypes
                    from ctypes import wintypes
                    _p = wintypes.DWORD()
                    ctypes.windll.user32.GetWindowThreadProcessId(
                        self.win["hwnd"], ctypes.byref(_p))
                    self.game_pid = _p.value or None
                if not self.game_pid and self.game.lower() != "screen":
                    self.game_pid = _pid_for_exe(self.game)
            except Exception:
                self.game_pid = None
        # the frame size this file is locked to: every later run must match
        # it, or a capture restart would splice two sizes into one stream
        self.cap_wh = ((self.win["w"], self.win["h"]) if self.win
                       else _screen_capture_wh(self.monitor_idx))
        if self.suspended:
            return                     # born paused: no capture run yet
        if not self.win:
            log(f"Capturing screen #{self.monitor_idx + 1} (output {self.monitor_idx}).")
        self._start_run()

    def suspend(self):
        """Pause: stop the current run but keep all footage for Continue."""
        if self.suspended:
            return
        self._stop_run()
        self.suspended = True
        log("Recording paused (footage kept).")

    def resume(self):
        """Continue: start a new run that appends to the same recording."""
        if not self.suspended:
            return
        self.suspended = False
        self._start_run()
        log("Recording resumed.")

    # ---- finalise ---------------------------------------------------------
    def stop(self):
        log("Finalising...")
        if not self.suspended and (self.vproc or self.audio):
            self._stop_run()
        all_segs = _list_segments(self.tmp)
        if not all_segs:
            # None means "there was nothing to save" (e.g. Cancel during warm-up) -
            # callers must NOT show a scary "couldn't save your video" for this.
            log("No video captured; nothing saved.")
            self._cleanup()
            return None

        ok = False
        if len(self.runs) <= 1:
            # Common path: a single uninterrupted run. Concatenate the segments and
            # mux the audio in (see _assemble), writing straight to the final file.
            run = self.runs[0] if self.runs else {}
            ok = self._assemble(all_segs, run.get("sys"), run.get("mic"), self.final,
                                run)
        else:
            # Pauses happened: assemble each run on its own (so each stays in sync),
            # then concatenate the runs into one gap-free file.
            run_finals = []
            start = 0
            for k, run in enumerate(self.runs):
                cnt = run.get("nseg", 0)
                rsegs = all_segs[start:start + cnt]
                start += cnt
                if not rsegs:
                    continue
                rfin = os.path.join(self.tmp, f"_runf{k}.mp4")
                if self._assemble(rsegs, run["sys"], run["mic"], rfin, run):
                    run_finals.append(rfin)
                else:
                    # A run that won't assemble is silently missing from the
                    # finished video (and from the length check below, which
                    # only measures the runs that DID make it) - say so loudly
                    # so lost footage is never invisible. Sessions now gain a
                    # run on every alt-tab, so this path matters.
                    lost = sum((_probe_duration(s) or 0) for s in rsegs)
                    log(f"Run {k + 1} of {len(self.runs)} could not be "
                        f"assembled - about {lost:.0f}s is missing from this "
                        f"recording (the rest is saved normally).")
            if len(run_finals) == 1:
                # scratch lives on E: and the library on D: - os.replace
                # across volumes fails EVERY time on this machine. Land on
                # the destination volume first, then swap atomically,
                # exactly like the many-run path below.
                ok = False
                try:
                    tmp_final = self.final + ".__assembling__.mp4"
                    shutil.move(run_finals[0], tmp_final)
                    for _try in range(3):   # AV/indexer touch-locks pass
                        try:
                            os.replace(tmp_final, self.final)
                            ok = True
                            break
                        except OSError:
                            time.sleep(1.0)
                    if not ok:
                        raise OSError("the library file stayed locked")
                except Exception as e:
                    log(f"Could not move the finished video into the "
                        f"library: {e}")
                    ok = False
            elif len(run_finals) > 1:
                tmp_final = self.final + ".__assembling__.mp4"
                if _concat_copy(SETTINGS["ffmpeg_path"], run_finals, tmp_final):
                    # _concat_copy salvages a bad join by DROPPING the last file and
                    # still returns True - which would silently lose the entire final
                    # run of a paused recording. Verify the stitched length first.
                    want = sum((_probe_duration(f) or 0) for f in run_finals)
                    got = _probe_duration(tmp_final) or 0
                    if want <= 0 or got >= want - max(1.0, want * 0.04):
                        try:
                            os.replace(tmp_final, self.final)
                            ok = True
                        except Exception:
                            ok = False
                    else:
                        log(f"Paused-recording stitch dropped footage "
                            f"({got:.0f}s of {want:.0f}s); keeping the raw runs.")
                if not ok:
                    try:                       # never leave a half-file beside the videos
                        if os.path.isfile(tmp_final):
                            os.remove(tmp_final)
                    except Exception:
                        pass

        if ok and os.path.isfile(self.final):
            log(f"Saved: {self.final}")
            try:
                buf = getattr(self, "_inp", None)
                if buf and len(buf) > 10:
                    os.makedirs(os.path.dirname(
                        _ai_sidecar(self.final, "inp")), exist_ok=True)
                    _atomic_write_json(_ai_sidecar(self.final, "inp"),
                                       {"v": 1, "s": buf})
            except Exception:
                pass
            _record_made_file(self.final)   # own it before the cap can consider it
            _queue_sdr_finish(self.final)   # HDR file? convert to SDR once idle
            enforce_storage_cap()
            self._cleanup()
            return True
        else:
            log("Merge failed; your raw files are kept in: " + self.tmp)
            return False

    def discard(self):
        """Stop capture and throw the whole recording away - no file saved."""
        log("Discarding current recording.")
        if getattr(self, "_wgc", None) is not None:
            try:
                self._wgc.stop()
            except Exception:
                pass
            self._wgc = None
        if self.audio:
            try:
                self.audio.signal_stop()
            except Exception:
                pass
        if self.vproc and self.vproc.poll() is None:
            try:
                self.vproc.terminate()
            except Exception:
                pass
            try:
                self.vproc.wait(timeout=10)
            except Exception:
                try:
                    self.vproc.kill()
                except Exception:
                    pass
        if self.audio:
            try:
                self.audio.finalize()
            except Exception:
                pass
        self._cleanup()

    def save_replay(self, seconds=None):
        """Grab roughly the last `seconds` of the live session and save it as a
        standalone clip in the Clips subfolder - the 'save last minute' feature.
        Saves whatever is buffered so far (so it works even seconds into a game).
        Returns the saved path, or None."""
        if seconds is None:
            seconds = SETTINGS.get("replay_seconds", 60)
        if not self._replay_lock.acquire(blocking=False):
            log("Replay: a save is already in progress.")
            return None
        try:
            segs = _list_segments(self.tmp)
            closed = segs[:-1] if len(segs) >= 1 else []   # newest is still open
            if not closed:
                log("Replay: nothing buffered yet - give it a few seconds.")
                return None
            seg = max(2, int(SETTINGS.get("segment_seconds", 4)))
            n = max(1, int(round(seconds / seg)) + 1)
            use = closed[-n:]                              # fewer => shorter clip, still saves
            stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
            clip_video = os.path.join(self.tmp, f"clip_{stamp}.mp4")
            if not _concat_copy(SETTINGS["ffmpeg_path"], use, clip_video):
                log("Replay: failed to assemble clip video.")
                return None
            d = _probe_duration(clip_video) or float(seconds)
            sys_wav = mic_wav = None
            ends = {}
            seg = max(2, int(SETTINGS.get("segment_seconds", 4)))
            aud = self.audio          # snapshot: _stop_run nulls self.audio racily
            if aud:
                # Dump MORE audio than the clip needs (the ring runs ~a segment
                # past the video's end and we want spare head too): the anchor
                # below trims the head to the exact frame, and -t cuts the tail
                # at the video's length - aligned at BOTH ends, no guessing.
                sys_wav, mic_wav, ends = aud.dump_ring(self.tmp, d + 2 * seg,
                                                       trim_tail=0.0)
            clips_dir = _game_shelf(self.base, "clip")
            out_final = os.path.join(clips_dir, f"{self.base}_clip_{stamp}.mp4")
            flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
            # WALL-CLOCK sync, same idea as full recordings: the last closed
            # segment's mtime IS the video's end moment (the segment muxer
            # finalises it right then), so video t0 = mtime - duration; each
            # wav's end moment comes from its ring. The old fixed 'trim half a
            # segment' guess was wrong by up to +-2s depending on how young the
            # open segment was - that's the 'clip sound is 1-2s early' bug.
            user_ms = int(SETTINGS.get("audio_offset_ms", 0))
            off_sys = off_mic = user_ms
            lo = -int((2 * seg + 6) * 1000)     # head-trim can legitimately be ~2 segments
            try:
                v_t0 = os.path.getmtime(use[-1]) - d
                def _off(wav, kind):
                    if not wav or kind not in ends:
                        return user_ms
                    adur = _probe_duration(wav)
                    if adur is None:
                        return user_ms
                    o = int(round((ends[kind] - adur - v_t0) * 1000)) + user_ms
                    # The ceiling must clear the whole clip: when the capture
                    # restarted part-way through (alt-tab), this run's audio
                    # legitimately belongs tens of seconds in, and the old
                    # flat 8s cap dropped it near the start - sound from
                    # after the alt-tab laid over footage from before it.
                    # (_assemble raised the same ceiling for this reason.)
                    return max(lo, min(max(8000, int(d * 1000) + 2000), o))
                off_sys = _off(sys_wav, "system")
                off_mic = _off(mic_wav, "mic")
                if sys_wav or mic_wav:
                    log(f"Clip A/V sync: system {off_sys:+d} ms, mic {off_mic:+d} ms")
            except Exception:
                pass
            cmd = build_mux_cmd(clip_video, sys_wav, mic_wav, out_final,
                                off_sys, off_mic)
            cmd = cmd[:-1] + ["-t", f"{d:.3f}", cmd[-1]]   # end audio WITH the video
            try:
                # Bounded so a stuck encoder can't hold the replay lock (and wedge
                # cleanup/quit) indefinitely. A real clip muxes in a few seconds.
                r = subprocess.run(cmd, stdout=subprocess.DEVNULL,
                                   stderr=subprocess.PIPE, creationflags=flags, timeout=180)
            except subprocess.TimeoutExpired:
                log("Replay: clip mux timed out; skipping this clip.")
                return None
            for p in (clip_video, sys_wav, mic_wav):
                if p and os.path.isfile(p):
                    try:
                        os.remove(p)
                    except Exception:
                        pass
            if r.returncode == 0 and os.path.isfile(out_final):
                self._clip_saved = True     # this session mattered to him
                log(f"Clip saved ({d:.0f}s): {out_final}")
                _record_made_file(out_final)
                _queue_sdr_finish(out_final)   # converted after the game session
                enforce_storage_cap()          # clips count toward the cap too
                return out_final
            log("Replay: final mux failed.")
            err = (r.stderr or b"").decode("utf-8", "ignore").strip().splitlines()
            for line in err[-3:]:
                log("  ffmpeg: " + line)
            return None
        finally:
            self._replay_lock.release()

    def _assemble(self, segs, sys_wav, mic_wav, out, run=None):
        """Turn the captured segments + audio into one finished file. Two proven
        steps: (1) concatenate the segments with no re-encode into a single file -
        this is the codec-safe route that survives every encoder, including AMD's
        hardware AV1 (muxing straight from the segment list can fail to identify a
        hardware-AV1 stream); (2) mux that file with the audio, correcting each
        audio stream's start skew. Written to a temp name and renamed on success so
        the finished recording appears atomically. Returns True; never raises.

        SYNC: each stream's offset comes from WALL-CLOCK anchors - the moment its
        first sample was captured vs the moment the video's first frame was
        captured (video-end wallclock minus video duration). The old way guessed
        the skew from (video length - audio length), which silently included every
        second the loopback device spent idle (WASAPI sends nothing during
        silence) and over-delayed the whole track - the '4-6 seconds late' bug.
        The duration guess remains only as a fallback when anchors are missing."""
        if not segs:
            return False
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        # FAST PATH: mux STRAIGHT from the segment list (concat demuxer input).
        # The old route wrote a multi-GB '_merged.mp4' first and then copied all
        # of it AGAIN into the final - two full disk passes, which is most of
        # why a 10-minute recording took ~2 minutes to save on a hard drive.
        # If the direct route fails on some machine (ancient concat quirks),
        # the proven two-step below still runs - nothing is ever lost.
        list_path = os.path.join(self.tmp, "_final.list.txt")
        merged = None
        try:
            with open(list_path, "w", encoding="utf-8") as fh:
                for f in segs:
                    p = os.path.abspath(f).replace("\\", "/").replace("'", "'\\''")
                    fh.write(f"file '{p}'\n")
        except Exception:
            list_path = None
        video_src, src_is_concat = (list_path, True) if list_path else (None, False)
        if not list_path:
            merged = os.path.join(self.tmp, "_merged.mp4")
            try:
                if os.path.isfile(merged):
                    os.remove(merged)
            except Exception:
                pass
            if not _concat_copy(SETTINGS["ffmpeg_path"], segs, merged):
                return False
            video_src = merged
        # 2. Per-stream A/V offsets from wall-clock anchors.
        user_ms = int(SETTINGS.get("audio_offset_ms", 0))
        off_sys = off_mic = user_ms
        run = run or {}
        if sys_wav or mic_wav:
            # Video t0, wallclock. Preferred: the FIRST segment's own clock -
            # its mtime is the moment the muxer finalised it (= its last frame),
            # so mtime - duration = the first captured frame. One cheap probe,
            # exact per run, and it works without the merged intermediate
            # (ffprobe reports N/A for a concat list's total duration).
            v_t0 = None
            vdur = None
            try:
                d0 = _probe_duration(segs[0])
                if d0 is not None:
                    v_t0 = os.path.getmtime(segs[0]) - d0
            except Exception:
                v_t0 = None
            if v_t0 is None:
                # legacy anchor: video-end wallclock minus total duration
                vdur = _probe_duration(video_src) if not src_is_concat else None
                v_end = run.get("v_end_wall")
                if vdur is not None and v_end is not None:
                    v_t0 = v_end - vdur
            if v_t0 is not None and (run.get("sys_t0") or run.get("mic_t0")):
                if sys_wav and run.get("sys_t0"):
                    off_sys = int(round((run["sys_t0"] - v_t0) * 1000)) + user_ms
                if mic_wav and run.get("mic_t0"):
                    off_mic = int(round((run["mic_t0"] - v_t0) * 1000)) + user_ms
                # A LARGE positive offset is legitimate: a game silent through a
                # long splash/menu means the first loopback sample genuinely
                # arrives that late, and the audio belongs exactly there. Only
                # the negative side (trimming audio head) stays tightly bounded.
                segsec = max(2, int(SETTINGS.get("segment_seconds", 4)))
                hi = max(8000, int((vdur if vdur else len(segs) * segsec) * 1000))
                off_sys = max(-8000, min(hi, off_sys))
                off_mic = max(-8000, min(hi, off_mic))
                log(f"A/V sync: video t0 anchored; system {off_sys:+d} ms, "
                    f"mic {off_mic:+d} ms")
            else:
                # fallback: the legacy duration guess (anchors unavailable).
                # Needs the total video length - probe FIRST + LAST segment and
                # extrapolate the uniform middle. The old way probed EVERY
                # segment: a 30-minute session is ~450 ffprobe SPAWNS, minutes
                # of pure process churn before the mux even started.
                if vdur is None:
                    if src_is_concat:
                        try:
                            dfirst = _probe_duration(segs[0])
                            dlast = _probe_duration(segs[-1]) if len(segs) > 1 else 0
                            if dfirst is not None and dlast is not None:
                                vdur = dfirst * max(1, len(segs) - 1) + dlast
                        except Exception:
                            vdur = None
                    else:
                        vdur = _probe_duration(video_src)
                adur = _probe_duration(sys_wav or mic_wav)
                if vdur is not None and adur is not None:
                    off_sys = off_mic = max(-6000, min(6000,
                        int(round((vdur - adur) * 1000)) + user_ms))
                    log(f"A/V sync (fallback): video {vdur:.2f}s vs audio "
                        f"{adur:.2f}s -> {off_sys:+d} ms")
        # 3. Mux to a temp file, then rename so the final appears atomically.
        tmp_out = out + ".__assembling__.mp4"

        # the session's length for the progress card - cheap: first + last
        # segment, uniform middle extrapolated
        bind_total = 0.0
        try:
            d0 = _probe_duration(segs[0])
            dl = _probe_duration(segs[-1]) if len(segs) > 1 else 0
            if d0 is not None and dl is not None:
                bind_total = d0 * max(1, len(segs) - 1) + dl
        except Exception:
            pass
        _BIND_TOK[0] += 1
        _btok = _BIND_TOK[0]
        _BINDING.update({"name": os.path.basename(out), "pct": None, "eta": None,
                         "mbps": None, "t0": time.time(), "total": bind_total,
                         "tok": _btok})

        def _mux(src, is_concat):
            cmd = build_mux_cmd(src, sys_wav, mic_wav, tmp_out, off_sys, off_mic,
                                video_is_concat=is_concat)
            # live progress on stdout (out_time_us lines); stderr kept for errors
            cmd[1:1] = ["-progress", "pipe:1", "-nostats"]
            t_start = time.time()
            try:
                p = _popen(cmd, stdout=subprocess.PIPE,
                                     stderr=subprocess.PIPE, creationflags=flags)
            except Exception as e:
                log(f"Mux failed to start ({e}); raw footage kept in the cache.")
                return False
            err_tail = []

            def _drain_err():
                try:
                    for ln in iter(p.stderr.readline, b""):
                        err_tail.append(ln)
                        if len(err_tail) > 8:
                            err_tail.pop(0)
                except Exception:
                    pass
            threading.Thread(target=_drain_err, daemon=True).start()
            last_size_t = t_start
            last_size = 0
            try:
                for ln in iter(p.stdout.readline, b""):
                    if time.time() - t_start > 1800:
                        p.kill()
                        log("Mux exceeded 30 minutes; killed. Raw footage kept in the cache.")
                        return False
                    s_ln = ln.decode("utf-8", "ignore").strip()
                    if s_ln.startswith("out_time_us=") or s_ln.startswith("out_time_ms="):
                        try:
                            done_s = int(s_ln.split("=")[1]) / 1e6
                            if bind_total > 1 \
                                    and _BINDING.get("tok") == _btok:
                                pct = max(0, min(99, int(done_s / bind_total * 100)))
                                if pct != _BINDING["pct"] and _TRAY_ICON[0] is not None:
                                    # the tray answers "how far along?" without opening the tome
                                    try:
                                        _TRAY_ICON[0].title = f"Lore - binding {pct}%"
                                    except Exception:
                                        pass
                                _BINDING["pct"] = pct
                                spent = time.time() - _BINDING["t0"]
                                if pct >= 3:
                                    _BINDING["eta"] = max(0, int(spent * (100 - pct) / pct))
                        except Exception:
                            pass
                        now = time.time()
                        if now - last_size_t >= 1.5 \
                                and _BINDING.get("tok") == _btok:
                            try:
                                sz = os.path.getsize(tmp_out) if os.path.isfile(tmp_out) else 0
                                _BINDING["mbps"] = max(0.0, (sz - last_size) / 1e6
                                                       / max(0.2, now - last_size_t))
                                last_size, last_size_t = sz, now
                            except Exception:
                                pass
                p.wait(timeout=60)
            except Exception as e:
                try:
                    p.kill()
                except Exception:
                    pass
                log(f"Mux failed/stalled ({e}); raw footage kept in the cache.")
                return False
            good = (p.returncode == 0 and os.path.isfile(tmp_out)
                    and os.path.getsize(tmp_out) > 0)
            if good:
                # the honest ledger: every bind states its wall time and speed,
                # so a slow save is a MEASURED fact with a size attached
                try:
                    secs = max(0.1, time.time() - t_start)
                    gb = os.path.getsize(tmp_out) / 1e9
                    log(f"Bound {os.path.basename(out)}: {gb:.2f} GB in "
                        f"{secs:.0f}s ({gb * 1000 / secs:.0f} MB/s)")
                except Exception:
                    pass
            else:
                err = b"".join(err_tail).decode("utf-8", "ignore").strip().splitlines()
                for line in err[-4:]:
                    log("  ffmpeg: " + line)
            return good

        ok = _mux(video_src, src_is_concat)
        if not ok and src_is_concat:
            # Direct route rejected on this machine: fall back to the proven
            # two-step (write merged, then mux from it).
            log("Direct save failed; using the two-step route.")
            merged = os.path.join(self.tmp, "_merged.mp4")
            if _concat_copy(SETTINGS["ffmpeg_path"], segs, merged):
                ok = _mux(merged, False)
        for p in (list_path, merged):
            if p:
                try:
                    if os.path.isfile(p):
                        os.remove(p)
                except Exception:
                    pass
        if ok:
            # Atomic finalise. A transient handle - antivirus scanning the fresh
            # file, the search indexer - can make os.replace fail; retry before
            # giving up, and if it STILL won't budge never delete the finished
            # weld. Leave it as an orphaned '.__assembling__.mp4' so
            # _salvage_interrupted promotes it next boot. Losing a good recording
            # to a 200ms lock is the worst possible outcome.
            for _attempt in range(25):
                try:
                    os.replace(tmp_out, out)
                    return True
                except Exception as e:
                    if _attempt >= 24:
                        log(f"Could not finalise file: {e}; kept "
                            f"{os.path.basename(tmp_out)} for recovery on restart.")
                        return False
                    time.sleep(0.4)
        try:
            if os.path.isfile(tmp_out):
                os.remove(tmp_out)
        except Exception:
            pass
        return False

    def _cleanup(self):
        # Remove the whole temp folder (segments, wavs, concatenated video). Take
        # the replay lock first so we never delete the scratch dir out from under a
        # 'save last minute' clip that's still being assembled.
        got = False
        try:
            got = self._replay_lock.acquire(timeout=120)
        except Exception:
            got = False
        try:
            if got:
                shutil.rmtree(self.tmp, ignore_errors=True)
            else:
                # A 'save clip' is still using this scratch dir - don't delete it out
                # from under the clip. The next-launch orphan sweep clears it safely.
                log("Cleanup deferred: a clip is still saving; the next launch will sweep it.")
        except Exception:
            pass
        finally:
            if got:
                try:
                    self._replay_lock.release()
                except Exception:
                    pass


# ---------------------------------------------------------------------------
#  Watch loop
# ---------------------------------------------------------------------------
class _Ctl:
    """Shared control state between the tray UI and the watcher thread."""
    def __init__(self):
        self.quit = threading.Event()
        self.watching = threading.Event()
        self.watching.set()
        self.stop_now = threading.Event()     # "stop this recording but keep watching"
        self.drop_now = threading.Event()     # "stop it and throw it away"
        self.force_record = threading.Event()  # manual "record now" (even with no game)
        self.lock = threading.Lock()
        self.session = None
        self.suppressed_game = None            # game we manually stopped; don't re-grab
        self.status = "starting"
        self.icon = None
        self.icon_idle = None
        self.icon_rec = None
        self.ui_enqueue = None     # set by the tray app: run a fn on the UI thread
        self.ui_root = None        # the hidden Tk root, parent for popups
        self.rec_t0 = None         # time the current recording started (live timer)
        self.wake = threading.Event()    # poke the watch loop to react to a click NOW
        self.muted_until = 0.0     # briefly silence the loop's sound after a click sound
        self.skip_loop_on = False  # consume-once: the click already played the start beep
        self.skip_loop_off = False # consume-once: the click already played the stop beep
        self.optimistic = None     # show this state instantly on click until reality catches up
        self.optimistic_t = 0.0
        self._dash_refresh = None  # dashboard registers a fn to repaint its state instantly
        self.saving = 0            # number of recordings finalising in the background

    def click_feedback(self, sound, optimistic, secs=4.0):
        """Instant feedback when the user presses a control: play the sound now,
        silence the loop's (delayed) duplicate, show the new state immediately, and
        poke the loop so the real action happens with minimal lag."""
        import time as _t
        try:
            _play_sound(sound)
        except Exception:
            pass
        # The loop's matching beep can land seconds later (after ffmpeg warms up),
        # so a short time-mute isn't enough - flag it to be skipped exactly once.
        if sound == "on":
            self.skip_loop_on = True
        elif sound == "off":
            self.skip_loop_off = True
        self.muted_until = _t.time() + 1.2
        self.optimistic = optimistic
        self.optimistic_t = _t.time() + secs
        self.wake.set()
        if self._dash_refresh:
            try:
                if self.ui_enqueue:
                    self.ui_enqueue(self._dash_refresh)
                else:
                    self._dash_refresh()
            except Exception:
                pass

    def eff_status(self):
        """Real status, except briefly overridden by an optimistic one right after a
        click so the UI feels instant. The live timer still uses rec_t0 (never faked)."""
        import time as _t
        opt = self.optimistic
        if opt:
            rec = ("recording", "paused", "starting")
            if _t.time() > self.optimistic_t or (self.status in rec) == (opt in rec):
                self.optimistic = None
            else:
                return opt
        return self.status

    def set_status(self, s):
        if s == self.status:
            return          # no change: skip the tray icon/menu churn every poll
        if s == "recording":
            if self.rec_t0 is None:
                import time as _t
                self.rec_t0 = _t.time()
        elif s in ("watching", "stopped", "idle", "saving"):
            self.rec_t0 = None     # paused keeps the clock; stop/idle/saving resets it
        self.status = s
        ic = self.icon
        if ic is not None:
            try:
                ic.title = f"Lore - {s}"
                img = self.icon_rec if (s == "recording" and self.icon_rec) else self.icon_idle
                if img is not None:
                    ic.icon = img
                ic.update_menu()
            except Exception:
                pass

    def notify(self, title, message, force=False):
        # Every action's notification is shown as Lore' own on-top popup, so it
        # is visible during a fullscreen game (Windows hides its own there).
        self.toast(title, message, force)

    def toast(self, title, sub, force=False):
        """Show Lore's own on-top popup. Unlike a Windows notification, this is
        visible over a fullscreen game (where Windows hides notifications via Focus
        Assist). Safe no-op when there's no UI thread (e.g. console mode).
        While a recording is WRITING, automatic mid-write chatter (clip
        saved, conversion ready, storage notes) is held by default (the
        quiet_popups setting) - a card sliding over the game mid-fight was
        exactly the wrong moment; the chimes still speak. LIFECYCLE moments
        pass `force=True` and ALWAYS show: recording started/stopped,
        paused/resumed - the user was explicit that "Now recording" must
        appear every time, tome open or not."""
        if not force and SETTINGS.get("quiet_popups", True) and self.status == "recording":
            log(f"(whisper held while writing) {title} - {sub}")
            return
        fn = self.ui_enqueue
        root = self.ui_root
        if fn is None or root is None:
            return
        try:
            fn(lambda: _show_toast(root, title, sub))
        except Exception:
            pass


def _tray_font(size):
    from PIL import ImageFont
    for name in ("segoeuib.ttf", "arialbd.ttf", "calibrib.ttf", "ariblk.ttf",
                 "DejaVuSans-Bold.ttf"):
        try:
            return ImageFont.truetype(name, size)
        except Exception:
            continue
    try:
        return ImageFont.load_default()
    except Exception:
        return None


# ---------------------------------------------------------------------------
#  Sound effects (synthesized once to temp WAVs - reliable winsound playback)
# ---------------------------------------------------------------------------
_SOUND_RATE = 44100
_SOUND_FILES = {}


def _env_exp(n, attack_ms, decay_tau):
    """A smooth volume envelope: quick fade-in, then an exponential fade-out.
    Exponential decay (not linear) is what makes a tone sound 'real' not 'beep'."""
    import math
    a = max(1, int(_SOUND_RATE * attack_ms / 1000))
    out = []
    for i in range(n):
        if i < a:
            out.append(i / a)
        else:
            out.append(math.exp(-(i - a) / max(1.0, n * decay_tau)))
    return out


def _tone(freq, ms, harmonics=(1.0, 0.22, 0.07), detune_cents=5.0,
          attack_ms=4.0, decay_tau=0.30, vol=0.7):
    """A warm musical tone: the fundamental plus a couple of soft harmonics, with
    two very slightly detuned voices layered for warmth, and an exponential
    decay. Returns a list of floats (combined/normalised later)."""
    import math
    n = int(_SOUND_RATE * ms / 1000)
    env = _env_exp(n, attack_ms, decay_tau)
    det = 2 ** (detune_cents / 1200.0)        # a few cents sharp = chorus warmth
    hsum = sum(harmonics) or 1.0
    out = []
    for i in range(n):
        t = i / _SOUND_RATE
        s = 0.0
        for k, amp in enumerate(harmonics, start=1):
            s += amp * 0.5 * (math.sin(2 * math.pi * freq * k * t)
                              + math.sin(2 * math.pi * freq * k * det * t))
        out.append(s * vol * env[i] / hsum)
    return out


def _overlay(a, b, offset_ms=0, gain_b=1.0):
    """Lay sound b over sound a, starting offset_ms in (so notes can overlap and
    ring into each other instead of playing as separate beeps)."""
    off = int(_SOUND_RATE * offset_ms / 1000)
    out = list(a)
    if len(out) < off + len(b):
        out += [0.0] * (off + len(b) - len(out))
    for i, v in enumerate(b):
        out[off + i] += v * gain_b
    return out


def _to_i16(samples, peak=0.82):
    """Normalise a float buffer to a comfortable peak and convert to int16."""
    m = max(1e-6, max((abs(s) for s in samples), default=0.0))
    g = peak / m
    return [int(max(-1.0, min(1.0, s * g)) * 32767) for s in samples]


def _silence(ms):
    return [0.0] * int(_SOUND_RATE * ms / 1000)


def _shutter_burst(ms, tau, vol, low_mix=0.0, low_f=180):
    """A short filtered-noise transient with optional low 'body' resonance -
    the building block of a mechanical camera click. Returns floats."""
    import math
    import random
    n = int(_SOUND_RATE * ms / 1000)
    out = []
    prev = 0.0
    for i in range(n):
        env = math.exp(-i / max(1.0, n * tau))
        white = random.uniform(-1, 1)
        prev = prev * 0.55 + white * 0.45        # light low-pass: a "click" not a "tss"
        s = prev * vol * env
        if low_mix:
            s += math.sin(2 * math.pi * low_f * (i / _SOUND_RATE)) * vol * low_mix * env
        out.append(s)
    return out


def _sound_samples(kind):
    if kind == "on":
        # confident rising two-note (E6 -> B6, a perfect fifth), warm + overlapped
        a = _tone(1318.5, 150, decay_tau=0.30, vol=0.55)
        b = _tone(1975.5, 200, decay_tau=0.34, vol=0.72)
        return _to_i16(_overlay(a, b, offset_ms=62, gain_b=1.0))
    if kind == "off":
        # gentle falling two-note (G5 -> C5), softer and a touch longer
        a = _tone(784.0, 165, decay_tau=0.36, vol=0.50)
        b = _tone(523.3, 240, decay_tau=0.46, vol=0.62)
        return _to_i16(_overlay(a, b, offset_ms=74, gain_b=0.92))
    if kind == "shutter":
        # DSLR "k-chnk": crisp mirror-up snap, short gap, fuller shutter-close
        # with low body, plus a faint metallic ring on the tail.
        snap = _shutter_burst(7, 0.18, 1.0, low_mix=0.22, low_f=240)
        close = _shutter_burst(13, 0.26, 0.85, low_mix=0.48, low_f=160)
        ring = _tone(2300, 70, harmonics=(1.0, 0.0, 0.0), detune_cents=0,
                     attack_ms=1, decay_tau=0.10, vol=0.10)
        seq = snap + _silence(30) + close
        seq = _overlay(seq, ring, offset_ms=(len(snap) * 1000 // _SOUND_RATE) + 8)
        return _to_i16(seq)
    return []


_SFX_VER = "3"   # bump when a sound changes so stale cached files are rebuilt


def _sound_path(kind):
    """Render a sound to a temp WAV once per volume level; return its path."""
    vol = SETTINGS.get("sfx_volume", DEFAULTS["sfx_volume"])
    try:
        vol = max(0, min(100, int(vol)))
    except Exception:
        vol = DEFAULTS["sfx_volume"]
    key = f"{kind}:{vol}"
    p = _SOUND_FILES.get(key)
    if p and os.path.isfile(p):
        return p
    try:
        import wave as _wave
        import array
        import tempfile
        d = os.path.join(tempfile.gettempdir(), "lore_sfx")
        os.makedirs(d, exist_ok=True)
        p = os.path.join(d, f"{kind}_v{_SFX_VER}_{vol}.wav")
        samples = _sound_samples(kind)
        if not samples:
            return None
        g = vol / 100.0
        samples = [int(s * g) for s in samples]
        w = _wave.open(p, "wb")
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(_SOUND_RATE)
        w.writeframes(array.array("h", samples).tobytes())
        w.close()
        _SOUND_FILES[key] = p
        return p
    except Exception as e:
        log(f"Sound build failed ({e})")
        return None


def _play_sound(kind):
    """Play a short effect (non-blocking). Windows only; silent elsewhere."""
    if os.name != "nt":
        return
    if int(SETTINGS.get("sfx_volume", DEFAULTS["sfx_volume"]) or 0) <= 0:
        return                                   # muted
    try:
        import winsound
    except Exception:
        return
    p = _sound_path(kind)
    if not p:
        return
    try:
        winsound.PlaySound(p, winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT)
    except Exception:
        pass


# ---------------------------------------------------------------------------
#  Autostart (login) shortcut - togglable from Settings
# ---------------------------------------------------------------------------
def _autostart_path():
    base = os.environ.get("APPDATA")
    if not base:
        return None
    return os.path.join(base, "Microsoft", "Windows", "Start Menu",
                        "Programs", "Startup", "Lore.lnk")


def _is_autostart_enabled():
    p = _autostart_path()
    return bool(p and os.path.isfile(p))


def _set_autostart(enabled):
    p = _autostart_path()
    if not p:
        return
    if enabled:
        if getattr(sys, "frozen", False):
            target = sys.executable          # the installed Lore.exe
            args = "--hidden"
            workdir = os.path.dirname(target)
        else:
            # Running from source: point at pythonw.exe + the script path. Targeting
            # the bare interpreter (as before) made the login shortcut launch Python
            # with no script, so Lore never started.
            exe_dir = os.path.dirname(sys.executable)
            pyw = os.path.join(exe_dir, "pythonw.exe")
            target = pyw if os.path.isfile(pyw) else sys.executable
            script = os.path.abspath(__file__)
            args = f'"{script}" --hidden'
            workdir = os.path.dirname(script)

        def _q(s):                           # escape ' for a PowerShell single-quoted literal
            return str(s).replace("'", "''")
        ps = ("$ws=New-Object -ComObject WScript.Shell;"
              f"$l=$ws.CreateShortcut('{_q(p)}');"
              f"$l.TargetPath='{_q(target)}';"
              f"$l.Arguments='{_q(args)}';"
              f"$l.WorkingDirectory='{_q(workdir)}';"
              "$l.Save()")
        try:
            flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
            subprocess.run(["powershell", "-NoProfile", "-Command", ps],
                           creationflags=flags, timeout=15)
        except Exception as e:
            log(f"Could not enable autostart: {e}")
    else:
        try:
            if os.path.isfile(p):
                os.remove(p)
        except Exception as e:
            log(f"Could not disable autostart: {e}")


# ---------------------------------------------------------------------------
#  Global hotkeys (Win32 RegisterHotKey - no dependency, no admin)
# ---------------------------------------------------------------------------
def _parse_hotkey(spec):
    """'ctrl+alt+f9' -> (modifiers, vk) for RegisterHotKey, or None."""
    if not spec:
        return None
    MODS = {"ctrl": 0x0002, "control": 0x0002, "alt": 0x0001, "shift": 0x0004,
            "win": 0x0008, "super": 0x0008, "cmd": 0x0008}
    SPECIAL = {"space": 0x20, "enter": 0x0D, "return": 0x0D, "esc": 0x1B,
               "escape": 0x1B, "tab": 0x09, "home": 0x24, "end": 0x23,
               "insert": 0x2D, "delete": 0x2E, "del": 0x2E, "pageup": 0x21,
               "pagedown": 0x22, "up": 0x26, "down": 0x28, "left": 0x25,
               "right": 0x27, "printscreen": 0x2C, "prtsc": 0x2C}
    mods, vk = 0, None
    for part in spec.lower().replace(" ", "").split("+"):
        if not part:
            continue
        if part in MODS:
            mods |= MODS[part]
        elif len(part) == 1 and part.isalnum():
            vk = ord(part.upper())
        elif part.startswith("f") and part[1:].isdigit() and 1 <= int(part[1:]) <= 24:
            vk = 0x6F + int(part[1:])        # F1 = 0x70
        elif part in SPECIAL:
            vk = SPECIAL[part]
        else:
            return None
    if vk is None:
        return None
    return (mods | 0x4000, vk)                # MOD_NOREPEAT


def _hotkey_listener(ctl, actions, stop_when=None):
    """actions: list of (spec, callable). Registers global hotkeys and runs a
    Win32 message loop in this thread, firing callables on press. stop_when
    (optional callable) makes the loop return early - the shell uses it to
    re-register combos the moment the user inscribes new ones."""
    if os.name != "nt":
        return
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32
    registered = {}
    failed = []
    idn = 1
    for spec, fn in actions:
        parsed = _parse_hotkey(spec)
        if not parsed:
            if spec:
                log(f"Hotkey '{spec}' not understood; skipped.")
                failed.append(spec)
            continue
        mods, vk = parsed
        if user32.RegisterHotKey(None, idn, mods, vk):
            registered[idn] = (spec, fn)
            log(f"Hotkey registered: {spec}")
            idn += 1
        else:
            log(f"Hotkey '{spec}' couldn't be registered (already used by another app?).")
            failed.append(spec)
    # If a combo couldn't be claimed, tell the user once (after the window has had a
    # moment to come up) - so a conflict (e.g. AMD/NVIDIA overlay owning the key)
    # shows up clearly instead of looking like the hotkey is simply broken.
    if failed:
        def _warn_failed():
            time.sleep(2.5)
            try:
                ctl.notify("A hotkey is in use",
                           ", ".join(failed) + " couldn't be registered - another app may "
                           "own it. Pick a different combo in Settings \u203a Hotkeys.")
            except Exception:
                pass
        threading.Thread(target=_warn_failed, daemon=True).start()
    if not registered:
        return
    msg = wintypes.MSG()
    try:
        while not ctl.quit.is_set() and not (stop_when and stop_when()):
            if user32.PeekMessageW(ctypes.byref(msg), None, 0, 0, 1):   # PM_REMOVE
                if msg.message == 0x0312:                              # WM_HOTKEY
                    entry = registered.get(msg.wParam)
                    if entry:
                        spec, fn = entry
                        log(f"Hotkey pressed: {spec}")
                        try:
                            fn()
                        except Exception as e:
                            log(f"Hotkey action error: {e}")
            else:
                time.sleep(0.03)
    finally:
        for hid in registered:
            try:
                user32.UnregisterHotKey(None, hid)
            except Exception:
                pass


def _discord_target_dims(iw, ih, v_kbps, fps=60.0):
    """Output size for the Discord copy: scale by AREA so the bitrate budget is
    actually enough per pixel (>= ~0.045 bits/px/frame - below that H.264 turns to
    mush). The old cap ('height <= 1080') let a 5120x1440 ultrawide through at
    3840x1080 = 4.1 Mpx on a ~3.7 Mbps budget = 0.015 bpp = the 'quality is so
    bad' complaint. Keeps aspect, never upscales, rounds to even."""
    try:
        iw, ih = int(iw), int(ih)
        if iw <= 0 or ih <= 0:
            return None
        budget_px = max(320 * 180, int(v_kbps * 1000 / (fps * 0.045)))
        max_px = min(budget_px, 1920 * 1080)          # never bigger than ~2 Mpx
        if iw * ih <= max_px:
            return None                               # small enough already
        s = (max_px / (iw * ih)) ** 0.5
        w = max(2, int(iw * s / 2) * 2)
        h = max(2, int(ih * s / 2) * 2)
        return (w, h)
    except Exception:
        return None


def _probe_dims(path):
    """(width, height) of the first video stream, or None."""
    try:
        d = os.path.dirname(SETTINGS["ffmpeg_path"])
        probe = os.path.join(d, "ffprobe.exe" if os.name == "nt" else "ffprobe") if d else "ffprobe"
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([probe, "-v", "error", "-select_streams", "v:0",
                            "-show_entries", "stream=width,height", "-of", "csv=p=0", path],
                           capture_output=True, text=True, timeout=15, creationflags=flags)
        w, h = (r.stdout or "").strip().split(",")[:2]
        return int(w), int(h)
    except Exception:
        return None


def _compress_for_discord(clip_path, max_mb, length_s=0, quality_mbps=0,
                          start_s=None):
    """Make a small, GOOD-looking copy of a clip for Discord. Optionally trims to
    the LAST `length_s` seconds, aims for `quality_mbps`, never exceeds `max_mb`.
    Quality levers (all offline - the game is long gone by now): the frame is
    scaled so the bitrate is sufficient PER PIXEL (area-based, ultrawide-aware),
    x264 runs on its 'medium' preset (near-slow quality, half the wait before
    the upload), and HDR sources get the measured-correct SDR conversion so
    embeds look right. Returns the temp file path, or None. Original is kept."""
    dur = _probe_duration(clip_path)
    if not dur or dur <= 0:
        return None
    import tempfile
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    # a UNIQUE name per send: two sends of the same file used to share one
    # temp - ffmpeg -y overwrote the upload mid-flight and the loser deleted
    # the winner's file
    out = os.path.join(tempfile.gettempdir(),
                       f"lore_share_{os.getpid()}_{threading.get_ident()}_"
                       + os.path.basename(clip_path))
    trim = []
    tail = []
    use_dur = dur
    if start_s is not None and length_s:
        # ANYWHERE IN THE FILE, not just the end - the Clipper hands over a
        # span you dragged out in the player. Fast seek before -i lands on the
        # nearest keyframe cheaply, and -t after it takes exactly the length
        # asked for (without -t it would run to the end of a two-hour file and
        # the bitrate maths would be nonsense).
        start_s = max(0.0, min(float(start_s), max(0.0, dur - 0.2)))
        use_dur = max(0.2, min(float(length_s), dur - start_s))
        trim = ["-ss", f"{start_s:.3f}"]
        tail = ["-t", f"{use_dur:.3f}"]
    elif length_s and 0 < length_s < dur:
        trim = ["-ss", f"{max(0, dur - length_s):.3f}"]   # seek to the last N sec
        use_dur = length_s
    audio_kbps = 96
    # Video-bitrate budget that fits under max_mb (95% headroom for container + AAC).
    cap_kbps = int(max_mb * 1024 * 1024 * 8 * 0.95 / use_dur / 1000) - audio_kbps
    if cap_kbps < 200:
        # Even the minimum quality can't fit this length under the size limit. Say so
        # plainly rather than encode an over-size file and blame the webhook later.
        log(f"Discord: {use_dur:.0f}s can't fit under {max_mb} MB "
            f"(budget {cap_kbps} kbps). Lower the clip seconds or raise the limit.")
        return None
    want_kbps = int(quality_mbps * 1000) if quality_mbps else cap_kbps
    v_kbps = max(200, min(want_kbps, cap_kbps))
    # Area-based downscale sized to the budget (see _discord_target_dims).
    dims = _probe_dims(clip_path)
    tgt = _discord_target_dims(dims[0], dims[1], v_kbps) if dims else None
    vf = f"scale={tgt[0]}:{tgt[1]}" if tgt else "scale=-2:'min(1080,ih)'"
    # HDR recordings get the SAME measured-correct SDR conversion as the finishing
    # queue - a shared recipe, so the Discord copy can never look different from
    # the finished file (npl=100+hable here is what 'mega blew out' 1.21-1.23).
    trc = _probe_color_trc(clip_path)
    if _is_hdr_trc(trc):
        vf += "," + _hdr_to_sdr_vf(trc)

    def _encode(vbk):
        # preset medium: within ~5% of slow's quality at these bitrates, but the
        # upload starts about twice as soon after the hotkey ('clip is slightly
        # delayed' feedback - most of that wait was this encode).
        cmd = [SETTINGS["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error",
               *trim, "-i", clip_path, "-vf", vf,
               "-c:v", "libx264", "-preset", "medium", "-b:v", f"{vbk}k",
               "-maxrate", f"{int(vbk * 1.35)}k", "-bufsize", f"{int(vbk * 2)}k",
               "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", f"{audio_kbps}k",
               *tail, "-movflags", "+faststart", out]
        try:
            rr = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
                                creationflags=flags, timeout=600)
        except subprocess.TimeoutExpired:
            log("Discord: compression timed out; upload skipped.")
            return None
        if rr.returncode != 0 or not os.path.isfile(out):
            err = (rr.stderr or b"").decode("utf-8", "ignore").strip().splitlines()
            for ln in err[-2:]:
                log("  ffmpeg(share): " + ln)
            return None
        return os.path.getsize(out) / (1024 * 1024)

    size_mb = _encode(v_kbps)
    if size_mb is None:
        return None
    # ABR can overshoot on short, high-motion clips. If the copy came out over the
    # limit, re-encode ONCE at a bitrate scaled to the achieved size; if it still
    # won't fit, give up honestly instead of uploading something Discord rejects.
    if size_mb > max_mb:
        v2 = max(150, int(v_kbps * (max_mb / size_mb) * 0.9))
        log(f"Discord copy {size_mb:.1f} MB > {max_mb} MB; retrying at {v2} kbps.")
        size_mb = _encode(v2)
        if size_mb is None or size_mb > max_mb:
            log("Discord: couldn't get the clip under the size limit.")
            try:
                if os.path.isfile(out):
                    os.remove(out)
            except Exception:
                pass
            return None
        v_kbps = v2
    log(f"Discord copy: {size_mb:.1f} MB, {use_dur:.0f}s at {v_kbps} kbps")
    return out


def _post_to_discord(file_path, content=""):
    """Upload a file to a Discord webhook (multipart). Returns True on success."""
    url = SETTINGS.get("discord_webhook", "").strip()
    if not url:
        return False
    # Only ever POST a clip to an actual Discord webhook address - guards against a
    # mistyped/pasted URL quietly sending your video somewhere else.
    try:
        from urllib.parse import urlparse
        host = (urlparse(url).hostname or "").lower()
    except Exception:
        host = ""
    if not (host in ("discord.com", "discordapp.com")
            or host.endswith(".discord.com") or host.endswith(".discordapp.com")):
        log("Discord upload skipped: the webhook URL isn't a discord.com address.")
        return False
    import urllib.request
    import uuid
    import json
    boundary = "----records" + uuid.uuid4().hex
    crlf = b"\r\n"
    fname = os.path.basename(file_path)
    try:
        with open(file_path, "rb") as f:
            filedata = f.read()
    except Exception:
        return False
    buf = bytearray()
    payload = json.dumps({"content": content[:1900]} if content else {})
    buf += b"--" + boundary.encode() + crlf
    buf += b'Content-Disposition: form-data; name="payload_json"' + crlf
    buf += b"Content-Type: application/json" + crlf + crlf
    buf += payload.encode() + crlf
    buf += b"--" + boundary.encode() + crlf
    buf += ('Content-Disposition: form-data; name="files[0]"; filename="%s"' % fname).encode() + crlf
    buf += b"Content-Type: video/mp4" + crlf + crlf
    buf += filedata + crlf
    buf += b"--" + boundary.encode() + b"--" + crlf
    req = urllib.request.Request(url, data=bytes(buf), method="POST")
    req.add_header("Content-Type", "multipart/form-data; boundary=" + boundary)
    req.add_header("User-Agent", "Lore/1.0")
    try:
        with urllib.request.urlopen(req, timeout=90) as resp:
            return 200 <= resp.getcode() < 300
    except Exception as e:
        log(f"Discord upload failed: {e}")
        return False


def _maybe_post_discord(ctl, clip_path):
    """Compress the clip and post it to Discord (best-effort). Only the dedicated
    'Clip + post to Discord' hotkey calls this; the plain 'Save clip' hotkey never
    uploads."""
    if not SETTINGS.get("discord_webhook", "").strip():
        ctl.notify("Discord", "No webhook set - add one in Sharing settings.")
        return
    if not clip_path or not os.path.isfile(clip_path):
        return
    ctl.notify("Discord", "Posting clip...")
    _source_busy_add(clip_path)      # the SDR finisher must not replace a
    try:                             # file mid-read
        small = _compress_for_discord(
            clip_path,
            int(SETTINGS.get("discord_max_mb", 9) or 9),
            length_s=int(SETTINGS.get("discord_clip_seconds", 0) or 0),
            quality_mbps=int(SETTINGS.get("discord_quality_mbps", 0) or 0),
        )
    finally:
        _source_busy_done(clip_path)
    if not small:
        ctl.notify("Discord", "Couldn't fit the clip under the size limit - "
                   "lower the seconds or raise the limit in Sharing.")
        return
    ok = _post_to_discord(small, content=f"\U0001F3AE New clip: {os.path.basename(clip_path)}")
    try:
        os.remove(small)
    except Exception:
        pass
    ctl.notify("Discord \u2713", "Clip posted." if ok else "Upload failed - check the webhook URL.")


def _window_track(ctl, session, current):
    """Follow the game's window while the EXPERIMENTAL window-only scope is
    recording. Called once per watcher poll:
      * minimised          -> pause the run (footage kept); resumes on
                              restore AT THE SAME SIZE (a window that comes
                              back resized ends the chapter instead)
      * window gone        -> pause too: exclusive-fullscreen games HIDE
                              their window on alt-tab, and display-mode
                              switches destroy/recreate it - both come back,
                              so the recording waits and continues into the
                              SAME file (never one file per alt-tab)
      * moved / new screen -> rotate the capture onto the new rect: same
                              file, segment numbering continues
      * RESIZED            -> return 'split' (save the chapter; the watcher
                              re-attaches at the new size) or 'restart' (a
                              seconds-old head: throw it away and re-record).
    One file must NEVER mix two frame sizes - the -c copy concat would
    produce a broken video - which is why gone/resized/restored-differently
    all end the chapter rather than rotating in place.
    Moves/resizes act only after TWO identical polls, so a drag in progress
    doesn't churn one rotation per poll. Returns None when the caller
    needn't act, else 'split'/'restart' for _apply_track_act."""
    if not getattr(session, "win", None):
        return None
    if session.suspended and not session.win_paused:
        return None                    # the USER paused; not ours to touch
    try:
        w = _game_window_rect(current or session.game,
                              hwnd=session.win.get("hwnd"))
    except Exception:
        w = None
    if w is None:
        # Window missing entirely: exclusive-fullscreen games HIDE their
        # window on alt-tab (not iconify), display-mode switches destroy and
        # recreate it, and hunts can transiently fail. Every one of these
        # comes BACK - so after one grace poll, just PAUSE and wait, exactly
        # like minimise. (The old behaviour saved the chapter after 12s,
        # which chopped a session into one file per alt-tab.) The recording
        # resumes into the SAME file when the window returns at the same
        # size; the game actually exiting is retired by the game-gone check.
        if session.win_paused or session.suspended:
            # BACKSTOP: a window that has been gone for many minutes while a
            # same-name process lingers (a wedged crash, an exit-to-tray
            # resident) is never coming back - without this, the footage
            # would sit paused forever AND the busy session would block every
            # future recording. Alt-tabs resume long before this fires.
            if (session.win_paused and session._win_lost
                    and time.time() - session._win_lost > 300
                    and _list_segments(session.tmp)
                    and not _exe_has_any_window(current or session.game)):
                log("Window capture: the game's window never came back - "
                    "saving what was recorded.")
                session.win_paused = False   # stays suspended; stop() copes
                return ("split"
                        if len(_list_segments(session.tmp)) >= 4 else "restart")
            return None
        if not session._win_lost:
            session._win_lost = time.time()
            return None                # one poll of grace: re-hunt first
        session.win_paused = True
        session._win_pend = None
        session.suspend()
        ctl.set_status("paused")
        log("Window capture: the game's window went away (alt-tab or a "
            "display switch) - paused until it returns.")
        if not getattr(session, "_pause_toasted", False):
            session._pause_toasted = True     # once per session - alt-tabbing
            ctl.notify("Recording paused",    # a lot must not toast a storm
                       f"{current or session.game}'s window went away - "
                       "recording continues when it returns.")
        return None
    session._win_lost = 0.0
    if w.get("iconic"):
        if not session.win_paused and not session.suspended:
            session.win_paused = True
            session._win_pend = None
            session.suspend()
            ctl.set_status("paused")
            log("Window capture: the game is minimised - paused until it "
                "returns.")
            if not getattr(session, "_pause_toasted", False):
                session._pause_toasted = True
                ctl.notify("Recording paused",
                           f"{current or session.game} is minimised - "
                           "recording continues when it returns.")
        return None
    if session.win_paused:
        # The window is back. Continue this file only at the SAME size (or
        # if nothing was captured yet - a session born paused has no
        # committed dimensions). A different size ends the chapter.
        first = not _list_segments(session.tmp)
        if first or (w["w"], w["h"]) == (session.win["w"], session.win["h"]):
            session.win = w            # a fresh spot/screen is fine - only
            session.win_paused = False # the frame SIZE is sacred
            try:
                session.resume()
            except Exception as e:
                log(f"Couldn't resume after minimise: {e}")
            ctl.set_status("recording")
            if first:
                # capture is beginning for the FIRST time (the session was
                # born paused because the game was minimised/windowless at
                # detection) - announce it exactly like any recording start.
                # Clear any stale start-beep flag from an earlier aborted
                # manual start so it can't swallow this genuine first chime
                # (a born-paused session skips the usual consuming _loop_sound).
                ctl.skip_loop_on = False
                _loop_sound(ctl, "on")
                if SETTINGS.get("notify_on_record", True):
                    ctl.notify("Now recording", current or session.game,
                               force=True)
                log("Window capture: the window appeared - recording started.")
            else:
                log("Window capture: the window is back - recording resumed.")
            return None
        # LET IT SETTLE FIRST. A game returning from exclusive fullscreen
        # rebuilds its swapchain, and for a poll or two its window measures
        # something that is neither the old size nor the final one. Ending
        # the chapter on that first reading is why alt-tab killed the
        # recording on some games and not others. Two identical polls, the
        # same patience the move/resize path below already applies - and
        # while it waits the run stays paused, so nothing is lost. A window
        # that settles back to the size it left at never reaches here at
        # all: the branch above resumes the same file.
        p, session._win_pend = session._win_pend, w
        if not (p and (p["w"], p["h"]) == (w["w"], w["h"])):
            return None
        session._win_pend = None
        cur0 = session.win
        if (cur0 and w["w"] == cur0["w"]
                and abs(w["h"] - cur0["h"]) <= 32):
            # the Bazaar's 20 pixels, on the away-and-return path: a
            # toolbar breathing is not a new chapter here either
            log("Window capture: the window returned a few pixels "
                "different - carrying on in the same chapter.")
            session.win = w
            session.win_paused = False
            return None
        log("Window capture: the window returned at a new size - saving "
            "this chapter and starting fresh.")
        session.win_paused = False     # stays suspended; stop()/discard cope
        return ("split"
                if len(_list_segments(session.tmp)) >= 4 else "restart")
    cur = session.win
    if (w["mon"], w["x"], w["y"], w["w"], w["h"]) == \
            (cur["mon"], cur["x"], cur["y"], cur["w"], cur["h"]):
        cur["hwnd"] = w["hwnd"]        # keep the freshest hwnd (recreated windows)
        session._win_pend = None
        return None
    p, session._win_pend = session._win_pend, w
    if not (p and (p["mon"], p["x"], p["y"], p["w"], p["h"]) ==
            (w["mon"], w["x"], w["y"], w["w"], w["h"])):
        session._win_settle = 0
        return None                    # still moving; wait for it to settle
    # THE BAZAAR'S 20 PIXELS. A same-width resize of a few dozen pixels
    # is a toolbar or a border breathing, not a new chapter - his 16
    # minute Bazaar was split for exactly this. A NEAR-SAME resize must
    # hold for six consecutive polls before the recorder acts; a real
    # resolution change (different width, or a big jump) acts on two,
    # as it always has.
    if (w["w"] == cur["w"] and w["h"] != cur["h"]
            and abs(w["h"] - cur["h"]) <= 32):
        session._win_settle = getattr(session, "_win_settle", 0) + 1
        if session._win_settle < 6:
            session._win_pend = w      # keep watching it
            return None
    session._win_settle = 0
    session._win_pend = None
    if (w["w"], w["h"]) == (cur["w"], cur["h"]):
        if getattr(session, "_wgc", None) is not None:
            session.win = w            # WGC tracks the window itself - the
            return None                # rect is bookkeeping, nothing to rotate
        log(f"Window capture: following the window to +{w['x']},+{w['y']} "
            f"on screen #{w['mon'] + 1}.")
        session.win = w
        session._rotating = True       # a replay clip must not race the swap
        try:
            session._stop_run()
            try:
                session._start_run()
            except Exception as e:
                log(f"Capture restart failed: {e}")
        finally:
            session._rotating = False
        return None
    if len(_list_segments(session.tmp)) >= 4:
        log("Window capture: the window was resized - saving this chapter "
            "and starting a fresh one at the new size.")
        return "split"
    log("Window capture: the window was resized straight away - restarting "
        "at the new size.")
    return "restart"


def _note_restart(session):
    """Count a capture restart, with a 60-second decay, and return the new
    streak. The decay is the whole point: restarts minutes apart are separate
    incidents (one alt-tab each) and must never add up to 'this encoder is
    broken', while restarts seconds apart really are a failing capture and
    must be allowed to reach the encoder ladder. Living on the SESSION also
    means a previous game's trouble can't hobble the next one."""
    now = time.time()
    if now - getattr(session, "_last_restart", 0.0) > 60.0:
        session._restart_streak = 0
    session._restart_streak = getattr(session, "_restart_streak", 0) + 1
    session._last_restart = now
    return session._restart_streak


def _restart_streak_now(session):
    """The restart streak WITH its decay applied - what the gates must read.

    The raw attribute only decays when _note_restart is next CALLED, but the
    gates read it first - so one six-alt-tab storm froze the streak at 6 for
    the rest of the session, and every later capture death (even a minute of
    clean recording later) skipped the alt-tab recovery and ended the
    chapter. Seven 'continuing the same recording' lines followed by a split
    on the eighth alt-tab: this exact bug, measured 2026-08-15."""
    if time.time() - getattr(session, "_last_restart", 0.0) > 60.0:
        session._restart_streak = 0
    return getattr(session, "_restart_streak", 0)


def _apply_track_act(ctl, session, current, act):
    """End the current chapter on _window_track's orders ('split' = save it,
    'restart' = a seconds-old head, discard it) and immediately re-attach to
    the still-running game with a fresh session. The re-attach is DIRECT -
    not left to detection - because a game that just left fullscreen (the
    usual reason for a resize) no longer passes fullscreen detection, and
    window scope exists precisely for windowed games. Returns the new
    session, or None when the game is gone / the fresh start failed (the
    normal detection loop takes over from there)."""
    _loop_sound(ctl, "off")
    with ctl.lock:
        ctl.session = None
    if act == "split":
        # A LAUNCH IS NOT A CHAPTER. A game that changes resolution a few
        # seconds after it opens - which is most of them - split the
        # recording here and filed the head, so every launch left a
        # five-second video behind. The worth-keeping mark already existed
        # for a game that opens and shuts again; a chapter the TOME ended
        # deserves the same test. What he started by hand is never judged
        # on its length.
        if _not_worth_keeping(session, ctl.force_record.is_set()):
            secs = _captured_seconds(session)
            log(f"{current or 'Screen'} changed shape after {secs}s - "
                f"that head was a launch, not a chapter, so it was not "
                f"saved.")
            _discard_soon(session)
        else:
            ctl.notify("Saving your video…", current or "Screen", force=True)
            _finalize_async(ctl, session)
    else:
        session.discard()
    if not current or _looks_gone(current):
        # The game is gone: this chapter was the end. A manual recording's
        # force_record must be cleared too, or the next poll would start an
        # endless desktop recording (manual record never auto-stops).
        ctl.force_record.clear()
        if ctl.saving <= 0:
            ctl.set_status("watching")
        return None
    # Constructing the next Session touches the disk (its scratch folder);
    # if that raises (full/again-offline drive) it must NOT escape - the
    # caller assigns our return to its `session` local, and an exception
    # would leave that local pointing at the session we JUST handed to
    # _finalize_async, risking a double stop() on one recording.
    try:
        nxt = Session(current)
    except Exception as e:
        log(f"Couldn't start the follow-up recording: {e}")
        ctl.force_record.clear()
        if ctl.saving <= 0:
            ctl.set_status("watching")
        return None
    ctl.set_status("starting")
    if not _safe_start(nxt, ctl):
        ctl.force_record.clear()
        return None
    with ctl.lock:
        ctl.session = nxt
    # Same game continuing. A live re-attach needs no second "Now recording"
    # toast (the sound cue is enough); one born paused (its window vanished)
    # stays silent until _window_track announces its real first frame.
    ctl.set_status("paused" if nxt.suspended else "recording")
    if not nxt.suspended:
        _loop_sound(ctl, "on")
    return nxt


def _trigger_replay(ctl, seconds=None, force_discord=False):
    _play_sound("shutter")
    with ctl.lock:
        sess = ctl.session
    if (sess is None or getattr(sess, "suspended", False)
            or getattr(sess, "_rotating", False)):
        log("Replay: no active recording right now.")
        ctl.notify("Lore", "Not recording right now - nothing to clip.")
        return
    secs = seconds or int(SETTINGS.get("clip_hotkey_seconds", SETTINGS.get("replay_seconds", 60)) or 60)
    ctl.notify("Clip", f"Saving the last ~{secs}s...")

    def work():
        # a clip binds on a worker thread too - wear the same honest card the
        # session bind wears (and make quit wait for it) unless a session bind
        # already owns the card and the counter
        fresh = getattr(ctl, "saving", 0) <= 0
        if fresh:
            with ctl.lock:
                ctl.saving += 1
            _BIND_TOK[0] += 1
            _BINDING.update({"name": f"last {secs}s clip", "pct": None,
                             "eta": None, "mbps": None, "tok": _BIND_TOK[0],
                             "t0": time.time(), "total": 0.0})
        try:
            path = sess.save_replay(secs)
        finally:
            if fresh:
                with ctl.lock:
                    ctl.saving -= 1
        if path:
            ctl.notify("Clip captured \u2713", os.path.basename(path))
            # Only the dedicated "Clip + post to Discord" hotkey ever uploads; the
            # plain "Save clip" hotkey is always local-only.
            if force_discord:
                _maybe_post_discord(ctl, path)
        else:
            ctl.notify("Lore", "Couldn't save the clip - give it a few more seconds.")
    threading.Thread(target=work, daemon=True).start()


def _interruptible_sleep(ctl, secs):
    # Wakes early when the user clicks something (ctl.wake), so a button press is
    # acted on within milliseconds instead of waiting out the poll interval.
    end = time.time() + secs
    while time.time() < end:
        if ctl.quit.is_set():
            return
        if getattr(ctl, "wake", None) and ctl.wake.wait(timeout=min(0.25, max(0.0, end - time.time()))):
            ctl.wake.clear()
            return


def _loop_sound(ctl, kind):
    """Play a start/stop sound from the watch loop, unless a click already played it
    (the click's sound is the instant one the user hears). A click sets a consume-once
    flag because the loop's matching beep can land seconds later, after the warm-up."""
    if kind == "on" and getattr(ctl, "skip_loop_on", False):
        ctl.skip_loop_on = False
        return
    if kind == "off" and getattr(ctl, "skip_loop_off", False):
        ctl.skip_loop_off = False
        return
    if time.time() >= getattr(ctl, "muted_until", 0.0):
        _play_sound(kind)


def _finalize_async(ctl, session):
    """Save (concat + mux) a finished recording in the BACKGROUND so the watch loop
    and the UI never freeze while a long file is written - a 50-minute capture can
    take minutes to mux. Shows 'saving' while it runs and returns to 'watching' when
    every pending save is done and nothing new is recording."""
    if session is None:
        return
    with ctl.lock:
        ctl.saving += 1
    ctl.set_status("saving")

    def work():
        ok = False
        try:
            ok = session.stop()      # True saved / False merge failed / None nothing
        except Exception as e:
            log(f"Finalise failed: {e}")
            ok = False
        try:
            # Report the REAL outcome. The watcher only fires a present-tense
            # "Saving your video..." earlier, so the user is never told a recording
            # is safe when the merge actually failed and the footage is only in the
            # hidden cache. A cancelled warm-up (nothing captured) stays quiet.
            if ok:
                ctl.notify("Saved ✓", os.path.basename(getattr(session, "final", "") or ""))
            elif ok is False:
                ctl.notify("Couldn't save your video",
                           "Your raw footage was kept - see lore.log for the folder.")
        except Exception:
            pass
        with ctl.lock:
            ctl.saving -= 1
            idle = ctl.saving <= 0 and ctl.session is None
        if idle and ctl.status == "saving":
            ctl.set_status("watching")
        # the bind is over - never leave the tooltip frozen at 99%
        ic = ctl.icon
        if ic is not None:
            try:
                ic.title = f"Lore - {ctl.status}"
            except Exception:
                pass
    threading.Thread(target=work, daemon=True).start()


def _safe_start(session, ctl):
    """Start a recording, swallowing and logging any error. A single failed
    start must never escape the watch loop - that loop has no except clause, so
    one uncaught error there would silently kill ALL future recording until the
    app is restarted. Returns True if the recording actually started."""
    try:
        session.start()
        return True
    except Exception as e:
        import traceback
        log(f"Couldn't start recording: {e}")
        log(traceback.format_exc())
        # Tell the user in plain language WHY (throttled so a transient hiccup doesn't
        # spam toasts). FileNotFoundError = ffmpeg missing/blocked; OSError/Permission
        # from makedirs = the save folder is unwritable or the drive is gone.
        if isinstance(e, FileNotFoundError):
            msg = ("Lore can't find its video tool (ffmpeg) - your antivirus may "
                   "have removed it. Reinstalling Lore fixes this.")
        elif isinstance(e, OSError):
            msg = (f"Lore can't write to your save folder:\n"
                   f"{SETTINGS.get('output_dir', '')}\n"
                   "Pick another folder in Settings, or reconnect the drive.")
        else:
            msg = "Couldn't start the recording - see lore.log for details."
        if time.time() - _LAST_START_FAIL_TOAST[0] > 30:
            _LAST_START_FAIL_TOAST[0] = time.time()
            try:
                ctl.notify("Lore can't start recording", msg)
            except Exception:
                pass
        try:
            session.discard()
        except Exception:
            pass
        with ctl.lock:
            ctl.session = None
        ctl.set_status("watching")
        return False


def _watch_core(ctl):
    """Detection + record loop, driven by ctl events. Used by the tray app
    and by the legacy console mode."""
    load_settings()
    # ONE-TIME REPAIR: compatible ('safe') capture mode used to be switched on
    # and remembered whenever a capture died mid-run - and the commonest cause
    # of that was never the encoder at all, it was alt-tabbing out of an
    # exclusive-fullscreen game (see the capture-restart branch below). Safe
    # mode drags every frame through system memory instead of staying on the
    # GPU, which on a 5120x1440/60 capture is a heavy, pointless tax. Clear it
    # once so the setting has to re-earn itself; a genuine encoder failure
    # switches it straight back on.
    # (no leading underscore: the settings bridge strips those, and the marker
    #  has to survive the user pressing Save or this repeats forever)
    if SETTINGS.get("safe_capture") and not SETTINGS.get("safe_reset_v11"):
        try:
            _persist_setting("safe_capture", False)
            _persist_setting("safe_reset_v11", True)
            SETTINGS["safe_capture"] = False
            log("Compatible capture mode cleared: it was set by the old "
                "alt-tab misdiagnosis. Full-speed GPU capture is back.")
        except Exception:
            pass
    # The first highlight pass marked every burst 8s apart - a seek bar of
    # solid gold. The picker is fixed; drop the sidecars it already wrote so
    # they are rebuilt properly on idle. (marker must not start with '_':
    # the settings bridge strips those keys)
    # Everything transcribed before 2.03 came from base.en, which on this
    # library produced near-nothing and looped. Retire those transcripts so
    # the better model rewrites them while idle.
    if not SETTINGS.get("stt_reset_v203"):
        try:
            gone = 0
            td = _thumb_dir(SETTINGS.get("output_dir", ""))
            for fn in (os.listdir(td) if os.path.isdir(td) else []):
                if fn.endswith(".stt.json"):
                    try:
                        os.remove(os.path.join(td, fn))
                        gone += 1
                    except OSError:
                        pass
            _persist_setting("stt_reset_v203", True)
            SETTINGS["stt_reset_v203"] = True
            _AI["index"] = None
            if gone:
                log(f"Cleared {gone} transcript(s) written by the old, weaker "
                    f"model. They are being re-read with the accurate one.")
        except Exception:
            pass
    # the loudness curve arrived with 2.20 and is written by the highlight
    # pass, so retire those sidecars once more to grow one for every recording
    if not SETTINGS.get("lvl_reset_v220"):
        try:
            gone = 0
            td = _thumb_dir(SETTINGS.get("output_dir", ""))
            for fn in (os.listdir(td) if os.path.isdir(td) else []):
                if fn.endswith(".hl.json"):
                    try:
                        os.remove(os.path.join(td, fn))
                        gone += 1
                    except OSError:
                        pass
            _persist_setting("lvl_reset_v220", True)
            SETTINGS["lvl_reset_v220"] = True
            if gone:
                log(f"Re-listening to {gone} recording(s) to draw their sound.")
        except Exception:
            pass
    if not SETTINGS.get("hl_reset_v201"):
        try:
            gone = 0
            td = _thumb_dir(SETTINGS.get("output_dir", ""))   # ONE cache root
            for fn in (os.listdir(td) if os.path.isdir(td) else []):
                if fn.endswith(".hl.json"):
                    try:
                        os.remove(os.path.join(td, fn))
                        gone += 1
                    except OSError:
                        pass
            _persist_setting("hl_reset_v201", True)
            SETTINGS["hl_reset_v201"] = True
            if gone:
                log(f"Cleared {gone} old highlight file(s): the marks were "
                    f"far too dense. They rebuild themselves while idle.")
        except Exception:
            pass
    # Say where footage is staged and why - a save's speed is decided here.
    try:
        _wd = _work_dir()
        _lib = SETTINGS.get("output_dir", "") or ""
        if os.path.splitdrive(_wd)[0].upper() != os.path.splitdrive(_lib)[0].upper():
            log(f"Staging recordings on {os.path.splitdrive(_wd)[0]} "
                f"({_free_bytes(_wd) / (1 << 30):.0f} GB free): the library "
                f"drive spins, so saving from a solid-state scratch is far "
                f"faster and never fights the game for the disk.")
        elif _drive_has_seek_penalty(_lib) is True:
            log("Recordings are staged on the same spinning drive they are "
                "saved to, so saving reads and writes through one head. A "
                "solid-state drive with 120+ GB free would speed this up a "
                "lot (Settings keeps a 'scratch_dir' override).")
    except Exception:
        pass
    _ENC_SAFE[0] = bool(SETTINGS.get("safe_capture", False))
    _migrate_library_layout() # shelve any flat legacy recordings first
    # Housekeeping, NOT a boot step. Since the scratch can live on another
    # drive, this walks the new cache AND the legacy one beside the library -
    # and that legacy folder can hold tens of thousands of files on a spinning
    # disk, which is exactly how long the tome took to appear. It blocks
    # nothing, so let it run behind the window.
    threading.Thread(target=_sweep_orphan_temp, daemon=True).start()
    resolve_encoder()
    gb_hr = SETTINGS["bitrate_mbps"] / 8 * 3600 / 1024
    _ai_rates_load()
    _ai_state_load()
    log(f"Watching ({SETTINGS['detection_mode']}). {SETTINGS['framerate']}fps "
        f"{SETTINGS['bitrate_mbps']}Mbps VBR (~{gb_hr:.0f} GB/hr max) "
        f"{SETTINGS['_encoder_resolved']}/{SETTINGS['amf_quality']}. "
        f"Output: {SETTINGS['output_dir']}")
    parts = []
    if SETTINGS["capture_system"]:
        parts.append("system (default device)")
    if SETTINGS["capture_mic"]:
        parts.append("mic" + (f" [{SETTINGS['mic_name_contains']}]"
                              if SETTINGS["mic_name_contains"] else ""))
    log("Audio: " + (" + ".join(parts) if parts else "none") +
        (f"  [{SETTINGS['audio_mode']}]" if len(parts) == 2 else ""))

    if SETTINGS.get("ai_transcribe", True) and _reader_paths() is None:
        log("The tome's reader isn't installed next to the app; "
            "transcription and word-search stay quietly off.")
    if not _ffmpeg_ok():
        log("ffmpeg health check failed: the video tool did not run.")
        ctl.notify("Lore can't find its video tool",
                   "ffmpeg is missing or was blocked by antivirus. Reinstall Lore.")

    session = None
    current = None
    manual = False          # True while this recording was started by hand
    enc_fails = 0           # consecutive encoder-died restarts (to stop looping)
    start_fails = 0         # consecutive start failures (spawn / output-folder errors)
    gone = 0                # consecutive polls the game looked closed (debounce)
    safe_persisted = False  # have we saved a discovered safe-capture mode yet
    try:
        while not ctl.quit.is_set():
          try:
            # STOP & SAVE: works whether actively recording or paused.
            if ctl.stop_now.is_set():
                ctl.stop_now.clear()
                ctl.force_record.clear()
                if session:
                    _loop_sound(ctl, "off")
                    ctl.suppressed_game = current
                    with ctl.lock:
                        ctl.session = None
                    # A session that never captured a frame (e.g. window scope
                    # still waiting for the game's window) has nothing to save
                    # - promising "Saving your video..." then producing no file
                    # reads as a lost recording. Discard it quietly instead.
                    if getattr(session, "win_paused", False) and not _list_segments(session.tmp):
                        ctl.notify("Recording stopped",
                                   "Nothing was captured yet.", force=True)
                        session.discard()
                    else:
                        ctl.notify("Recording stopped", "Saving your video...", force=True)
                        _finalize_async(ctl, session)   # save in background; UI stays live
                    session = current = None
                    manual = False
                # Stopping always returns to watching - otherwise a stop pressed while
                # paused would leave the app paused (and not detecting the next game).
                ctl.watching.set()

            # STOP AND THROW IT AWAY. Every other way out of a recording ends
            # in a saved file; sometimes you know within seconds that this one
            # is not worth one.
            if ctl.drop_now.is_set():
                ctl.drop_now.clear()
                ctl.force_record.clear()
                if session:
                    _loop_sound(ctl, "off")
                    ctl.suppressed_game = current
                    with ctl.lock:
                        ctl.session = None
                    secs = _captured_seconds(session)
                    ctl.notify("Recording thrown away",
                               f"{_fmt_secs(secs)} discarded - nothing was saved.",
                               force=True)
                    log(f"Recording thrown away by hand ({secs}s, nothing saved).")
                    _discard_soon(session)
                    session = current = None
                    manual = False
                ctl.watching.set()

            # PAUSE: suspend the current recording (keep footage); Continue resumes it.
            if not ctl.watching.is_set():
                if session and not session.suspended:
                    _loop_sound(ctl, "off")
                    ctl.notify("Paused", "Recording paused - footage kept.", force=True)
                    session.suspend()
                    ctl.set_status("paused")
                elif session and session.suspended:
                    ctl.set_status("paused")
                else:
                    # Nothing is recording - 'pause' has no meaning here, so don't show
                    # a misleading PAUSED state; just keep watching for the next game.
                    ctl.watching.set()
                _interruptible_sleep(ctl, 0.4)
                continue

            # Just un-paused with a suspended recording: continue it, or - if the
            # game closed while paused - finalise what we already captured.
            # (win_paused sessions live here every poll: the window-minimise
            # auto-pause keeps watching set, so only the game-gone check may
            # act - _window_track resumes when the window returns.)
            if session and session.suspended:
                # THREE THINGS HAVE TO AGREE THAT A GAME CLOSED. It used to
                # be one: a name missing from one process walk, twice. That
                # walk can come back short while he is gaming, and two short
                # walks ended a recording he was still making.
                _names = running_process_names()
                game_gone = (current is not None
                             and _process_walk_trustworthy(_names)
                             and current not in _names
                             and not _exe_has_any_window(current))
                # Debounced: a suspended session can sit here for hours (a
                # minimised game), and one incomplete process-list poll must
                # not finalise a recording whose game is merely minimised.
                session._gone_polls = session._gone_polls + 1 if game_gone else 0
                if not game_gone:
                    _afk_track(ctl, session, current)   # resumes an AFK pause
                    if not session.win_paused and not session.afk_paused:
                        if session.win:
                            # Re-aim before resuming: the window may have
                            # moved - or the display mode changed - while
                            # paused; the stale rect would kill ffmpeg at
                            # start and the death would be blamed on the
                            # encoder. Same size -> adopt; minimised -> hand
                            # to the auto-pause; resized/gone -> new chapter.
                            try:
                                fresh = _game_window_rect(
                                    current or session.game,
                                    hwnd=session.win.get("hwnd"))
                            except Exception:
                                fresh = None
                            if fresh is None or fresh.get("iconic"):
                                # The game's window is minimised or hidden
                                # (alt-tabbed exclusive fullscreen) right
                                # now: honour the Continue by handing to the
                                # auto-pause - it resumes itself, into the
                                # same file, the moment the window returns.
                                # Consume the click's start-beep flag so it
                                # can't later swallow a genuine start chime.
                                session.win_paused = True
                                ctl.skip_loop_on = False
                                ctl.notify("Lore", "Paused because the game's "
                                           "window is away - it continues "
                                           "when the window returns.")
                            elif (
                                    not _list_segments(session.tmp)
                                    or (fresh["w"], fresh["h"])
                                    == (session.win["w"], session.win["h"])):
                                session.win = fresh
                            else:
                                act = ("split"
                                       if len(_list_segments(session.tmp)) >= 4
                                       else "restart")
                                session = _apply_track_act(ctl, session,
                                                           current, act)
                                if session is None:
                                    current = None
                                    manual = False
                                _interruptible_sleep(ctl, 0.3)
                                continue
                    if not session.win_paused and not session.afk_paused:
                        try:
                            session.resume()
                        except Exception as e:
                            # leave the dead-video state to the health check below
                            log(f"Couldn't resume recording: {e}")
                        _loop_sound(ctl, "on")
                        ctl.notify("Recording resumed", current or "Screen", force=True)
                        ctl.set_status("recording")
                elif session._gone_polls >= 3:
                    ctl.force_record.clear()
                    with ctl.lock:
                        ctl.session = None
                    # A window-scope session that was still waiting for its
                    # game's window (born paused, never captured a frame) has
                    # nothing to save - don't promise a video that never comes,
                    # and don't play the stop chime for a recording that never
                    # started (no matching start chime ever sounded).
                    if session.win_paused and not _list_segments(session.tmp):
                        session.discard()
                    elif _not_worth_keeping(session, manual):
                        # this branch previously existed ONLY in the window-
                        # scope path; the ordinary screen-scope exit saved
                        # every accidental open-and-quit regardless
                        # OPENED AND SHUT AGAIN. You never asked for this one,
                        # and a file you would only have deleted later is worse
                        # than no file: it goes in the queue, gets read, gets
                        # described, and sits in the list looking like a
                        # session. Nothing was worth keeping, so nothing is.
                        secs = _captured_seconds(session)
                        log(f"{current or 'Screen'} closed after {secs}s - "
                            f"under the {int(SETTINGS.get('min_keep_seconds', 45))}s "
                            f"worth-keeping mark, so it was not saved.")
                        # SAY SO. The start was announced with a toast; an
                        # unannounced vanishing reads as a lost recording.
                        ctl.notify("Not kept",
                                   f"{current or 'Screen'} closed after "
                                   f"{_fmt_secs(secs)} - too short to file. "
                                   "Settings > Replay to change the mark.")
                        _discard_soon(session)
                    else:
                        _loop_sound(ctl, "off")
                        ctl.notify("Saving your video…", current or "Screen", force=True)
                        _finalize_async(ctl, session)
                    session = current = None
                    manual = False

            # READING WHILE RECORDING. Everything below this line lives inside
            # "if session is None", so from the instant a recording starts the
            # reader was never called at all. The Background work switch says
            # "anytime, even mid-game" and could not possibly deliver it -
            # the call site was unreachable during a recording, which is most
            # of the time on this machine.
            if session is not None and (SETTINGS.get("always_read")
                                        or _AI.get("force")
                                        or _AI.get("force_queue")):
                _ai_tick(ctl)

            if session is None:
                if ctl.saving <= 0:
                    ctl.set_status("watching")   # but keep showing 'saving' while a save runs
                g = find_active_game()
                try:
                    # THE PULSE. The log dies silently on this machine
                    # (item 11), and tonight that blinded a whole
                    # recorder diagnosis. One tiny file, rewritten in
                    # place every poll, says what the watcher saw. It
                    # lives beside settings.json - the one folder this
                    # app provably writes all day - and lands whole via
                    # replace, so a reader never catches half a json.
                    _bp = os.path.join(_data_dir(), "watch.beat")
                    _doc = {"at": round(time.time(), 1),
                            "sees": g or "",
                            "suppressed": ctl.suppressed_game or "",
                            "forced": bool(ctl.force_record.is_set())}
                    if _WATCH_NOTE["fail_g"]:
                        _doc["last_start_fail"] = {
                            "at": round(_WATCH_NOTE["fail_at"], 1),
                            "game": _WATCH_NOTE["fail_g"]}
                    if _WATCH_NOTE["learn_g"]:
                        _doc["last_learned"] = {
                            "at": round(_WATCH_NOTE["learn_at"], 1),
                            "game": _WATCH_NOTE["learn_g"]}
                    with open(_bp + ".tmp", "w", encoding="utf-8") as _bf:
                        _bf.write(json.dumps(_doc))
                    os.replace(_bp + ".tmp", _bp)
                except Exception:
                    pass
                # Forget the suppression as soon as the game we manually stopped is no
                # longer the active full-screen app (you minimised it, alt-tabbed away,
                # or closed it) - so RE-maximising it starts a fresh recording. This is
                # far more reliable than waiting for the process to exit: media apps
                # like Stremio keep a background process alive, which used to leave
                # them suppressed forever and never recording again.
                if ctl.suppressed_game and ctl.suppressed_game != g:
                    ctl.suppressed_game = None
                auto = bool(g) and g != ctl.suppressed_game and not ctl.force_record.is_set()
                if not g and not ctl.force_record.is_set():
                    if _bg_work_allowed():
                        _sdr_finish_tick(ctl)  # truly idle: HDR->SDR
                    _ai_tick(ctl)              # ...and let the tome read its books
                elif SETTINGS.get("always_read") or _AI.get("force") \
                        or _AI.get("force_queue"):
                    # a game is in front, or one is being recorded, and you have
                    # said to read anyway. It runs BELOW NORMAL and the game
                    # keeps the GPU - only the disk is shared.
                    _ai_tick(ctl)
                if auto:
                    _sdr_finish_abort()        # game first - the GPU is theirs now
                    # ...but a recording you asked for BY NAME keeps going
                    _ai_abort(force_too=False)
                    session = Session(g)
                    ctl.set_status("starting")     # honest "warming up" while ffmpeg spins up
                    if not _safe_start(session, ctl):
                        session = None
                        # the failure rides every later pulse - a note
                        # one poll wide was unreadable by design
                        _WATCH_NOTE["fail_at"] = time.time()
                        _WATCH_NOTE["fail_g"] = g or ""
                        start_fails += 1
                        if start_fails >= 4:
                            # stop hammering one game that won't start (the user was
                            # already told why by _safe_start); re-arms if they alt-tab.
                            start_fails = 0
                            ctl.suppressed_game = g
                        _interruptible_sleep(ctl, 1.0)
                        continue
                    current = g
                    manual = False
                    start_fails = 0
                    with ctl.lock:
                        ctl.session = session
                    # a window-scope session born while the game is minimised
                    # starts PAUSED - saying "recording" would be a lie
                    ctl.set_status("paused" if session.suspended else "recording")
                    if enc_fails == 0 and not session.suspended:
                        _loop_sound(ctl, "on")
                        if SETTINGS.get("notify_on_record", True):
                            # the user asked for this one ALWAYS: recording
                            # beginning is news, whatever else is happening
                            ctl.notify("Now recording", g, force=True)
                elif ctl.force_record.is_set():
                    # Manual record: capture the screen now. If a game is already
                    # fullscreen, attach to it; otherwise record the desktop and
                    # attach to the next game that goes fullscreen.
                    gg = detect_fullscreen_game()
                    name = gg or "Screen"
                    ctl.suppressed_game = None
                    _sdr_finish_abort()        # manual record also outranks conversions
                    _ai_abort(force_too=False)
                    session = Session(name)
                    ctl.set_status("starting")     # honest "warming up" while ffmpeg spins up
                    if not _safe_start(session, ctl):
                        session = None
                        start_fails += 1
                        if start_fails >= 4:
                            # manual record keeps failing; stop retrying so it doesn't
                            # churn ffmpeg forever (the user was told why by _safe_start).
                            start_fails = 0
                            ctl.force_record.clear()
                        _interruptible_sleep(ctl, 1.0)
                        continue
                    current = gg
                    manual = True
                    start_fails = 0
                    with ctl.lock:
                        ctl.session = session
                    ctl.set_status("recording")
                    if enc_fails == 0:
                        _loop_sound(ctl, "on")
                        if SETTINGS.get("notify_on_record", True):
                            # manual start = the user just pressed the sigil
                            ctl.notify("Now recording", name, force=True)
            elif session.suspended:
                # paused; wait for Continue or Stop (handled above). A window-
                # minimise auto-pause watches for the window's return here; a
                # window that comes back RESIZED - or never comes back - ends
                # the chapter instead of resuming into the wrong frame size.
                act = _window_track(ctl, session, current)
                if act:
                    session = _apply_track_act(ctl, session, current, act)
                    if session is None:
                        current = None
                        manual = False
                    _interruptible_sleep(ctl, 0.3)
                    continue
            else:
                # 'not session.vproc' matters: a failed RESUME leaves vproc=None with
                # suspended=False - that dead-video state must enter recovery too,
                # or audio records to nowhere until the user notices.
                if not session.vproc or session.vproc.poll() is not None:
                    # Window-scope deaths FIRST - almost never the encoder's
                    # fault. Alt-tabbing out of an exclusive-fullscreen game
                    # flips the display mode and Windows tears down the
                    # desktop duplication ddagrab reads, so ffmpeg exits with
                    # a generic external error. This is COMMON - measured 104
                    # times in one day - so it must cost nothing: keep the
                    # session and the file, and only end the chapter when the
                    # window genuinely comes back a different SIZE (one file
                    # can never hold two frame sizes).
                    if getattr(session, "win", None):
                        streak_ok = _restart_streak_now(session) < 6
                        _note_restart(session)
                        for ln in session.err_text().splitlines()[-2:]:
                            if ln.strip():
                                log("  ffmpeg: " + ln.strip())
                        proven = False
                        for _sp in _list_segments(session.tmp):
                            try:
                                if os.path.getsize(_sp) > 4096:
                                    proven = True
                                    break
                            except OSError:
                                pass
                        game_alive = ((not _looks_gone(current))
                                      if current else bool(manual))
                        try:
                            fresh = _game_window_rect(
                                current or session.game,
                                hwnd=session.win.get("hwnd"))
                        except Exception:
                            fresh = None
                        if streak_ok and proven and game_alive:
                            if fresh is None or fresh.get("iconic"):
                                # the window is away right now (that IS the
                                # alt-tab): pause and let the tracker resume
                                # into this same file when it comes back
                                session.win_paused = True
                                session._win_pend = None
                                session._win_lost = time.time()
                                session.suspend()
                                ctl.set_status("paused")
                                log("Window capture stopped and the window is "
                                    "away - paused; the same recording "
                                    "continues when it returns.")
                                if not getattr(session, "_pause_toasted", False):
                                    session._pause_toasted = True
                                    ctl.notify("Recording paused",
                                               f"{current or session.game}'s window "
                                               "went away - recording continues "
                                               "when it returns.")
                                _interruptible_sleep(ctl, 0.4)
                                continue
                            if ((fresh["w"], fresh["h"]) == (session.win["w"],
                                                             session.win["h"])
                                    and _hdr_run_flag() == getattr(
                                        session, "_hdr_used", False)):
                                # same size AND same HDR mode: start
                                # capturing again into the SAME file (a new
                                # run, exactly like Continue after a pause)
                                session.win = fresh
                                log("Window capture stopped mid-run (display "
                                    "change) - continuing the same recording.")
                                session._rotating = True   # a clip must not
                                try:                       # race the swap
                                    session._stop_run()
                                    session._start_run()
                                except Exception as e:
                                    log(f"Capture restart failed: {e}")
                                finally:
                                    session._rotating = False
                                _interruptible_sleep(ctl, 0.4)
                                continue
                            log("Window capture: the window came back a "
                                "different size - saving this chapter.")
                        if not streak_ok:
                            log("The capture keeps dying moments after each "
                                "restart - saving this chapter and starting "
                                "a fresh one.")
                        act = ("split"
                               if len(_list_segments(session.tmp)) >= 4
                               else "restart")
                        session = _apply_track_act(ctl, session, current, act)
                        if session is None:
                            current = None
                            manual = False
                        _interruptible_sleep(ctl, 0.5)
                        continue
                    # HDR-specific failure NEXT: if this run was handling HDR and
                    # produced no frames, that's the HDR path failing on this
                    # machine - NOT a bad encoder. Fall back to plain capture and
                    # re-record right away, so HDR can never leave you with no
                    # recording at all.
                    # ...but only when HDR has NEVER produced a frame here (or
                    # after the capture-restart budget below is spent). If
                    # earlier runs in this session recorded fine, HDR clearly
                    # works on this machine and an empty run is the display
                    # flipping mode (alt-tab), not an HDR capability failure.
                    if (getattr(session, "_hdr_used", False) and _HDR_LEVEL[0] < 1
                            and len(_list_segments(session.tmp))
                                <= getattr(session, "_run_vstart", 0)
                            and (not _list_segments(session.tmp)
                                 or _restart_streak_now(session) >= 6)):
                        err = session.err_text()
                        for ln in err.splitlines()[-4:]:
                            if ln.strip():
                                log("  ffmpeg: " + ln.strip())
                        # There is exactly ONE HDR path now (float16 zero-copy on
                        # AMF); if it can't produce frames on this driver, plain
                        # capture is the only alternative - no half-steps to try.
                        _HDR_LEVEL[0] = 1
                        log("HDR capture produced no frames here; recording "
                            "continues with plain capture.")
                        ctl.notify("Lore", "HDR isn't working on this PC - "
                                   "recording without it.")
                        # A multi-run session (pause/resume) may hold GOOD segments
                        # from earlier runs - salvage them; only a truly empty
                        # session is discarded. (Unconditional discard here deleted
                        # pre-pause footage when a resumed HDR run died at start.)
                        if _list_segments(session.tmp):
                            with ctl.lock:
                                ctl.session = None
                            _finalize_async(ctl, session)
                        else:
                            session.discard()
                            with ctl.lock:
                                ctl.session = None
                        session = None
                        # Not an encoder fault - don't count it; retry next poll.
                        if ctl.saving <= 0:
                            ctl.set_status("watching")
                        _interruptible_sleep(ctl, 0.3)
                        continue
                    # Disk full? A full output drive kills ffmpeg exactly like a bad
                    # encoder does - check before blaming (and needlessly blacklisting)
                    # the GPU, and tell the user the real, fixable cause.
                    try:
                        free = shutil.disk_usage(SETTINGS["output_dir"]).free
                    except Exception:
                        free = None
                    if free is not None and free < (1 << 30):     # under ~1 GB
                        log(f"Output drive nearly full ({free / 1e9:.1f} GB free); stopping.")
                        ctl.notify("Your drive is almost full",
                                   "Recording stopped - free up space to record again.")
                        if len(_list_segments(session.tmp)) >= 2:
                            with ctl.lock:
                                ctl.session = None
                            _finalize_async(ctl, session)         # salvage what exists
                        else:
                            session.discard()
                            with ctl.lock:
                                ctl.session = None
                        ctl.suppressed_game = current             # don't re-record into a full disk
                        ctl.force_record.clear()
                        session = current = None
                        manual = False
                        if ctl.saving <= 0:
                            ctl.set_status("watching")
                        _interruptible_sleep(ctl, 1.0)
                        continue
                    # THE ALT-TAB FIX (screen scope). The capture stopped, but
                    # this run HAD been writing frames and the game is still
                    # here - so the encoder is provably fine. What kills a
                    # healthy capture mid-run is the DESKTOP changing under
                    # it: alt-tabbing out of an exclusive-fullscreen game
                    # flips the display mode and Windows tears down the
                    # duplication ddagrab reads from, so ffmpeg exits.
                    # Blaming the encoder for that (what used to happen) saved
                    # the video, opened a new one, and permanently demoted the
                    # encoder to compatible mode - which is why one session
                    # became a pile of files and why capture got slow.
                    # Instead: keep the session and start a fresh capture run.
                    # The footage continues in the SAME file, exactly like
                    # Continue after a pause.
                    # SESSION-level frames, not this run's: a run that dies
                    # empty moments after a good one is the same display
                    # transition, and the encoder has already proven itself.
                    # 'proven' means real footage exists - a zero-byte stub
                    # from an encoder that died on its first frame must not
                    # buy six retries and turn a clean discard into a doomed
                    # salvage, so the bytes have to be there.
                    def _has_footage(sess):
                        for sp in _list_segments(sess.tmp):
                            try:
                                if os.path.getsize(sp) > 4096:
                                    return True
                            except OSError:
                                pass
                        return False
                    proven = _has_footage(session)
                    # A manual desktop recording has no game to be alive -
                    # it must still survive a display-mode change (it used to
                    # fall through and re-persist compatible mode).
                    game_alive = ((not _looks_gone(current))
                                  if current else bool(manual))
                    # ...but ONLY while the capture would come back identical.
                    # The very event that kills it (a display-mode change) can
                    # also change the desktop resolution, and stream-copying a
                    # 1080p run onto a 1440p one makes an unplayable file.
                    # (window-scope sessions are handled by their own branch
                    #  above; comparing a window size against a screen size
                    #  here would always read as "changed")
                    now_wh = (None if getattr(session, "win", None)
                              else _screen_capture_wh(session.monitor_idx))
                    same_shape = (
                        getattr(session, "cap_wh", None) is not None
                        and now_wh is not None
                        and now_wh == session.cap_wh
                        and _hdr_run_flag() == getattr(session, "_hdr_used", False))
                    if (proven and game_alive and same_shape
                            and _restart_streak_now(session) < 6):
                        _note_restart(session)
                        for ln in session.err_text().splitlines()[-2:]:
                            if ln.strip():
                                log("  ffmpeg: " + ln.strip())
                        log("Capture stopped mid-run (display-mode change or "
                            "lost desktop duplication) - continuing this same "
                            "recording.")
                        session._rotating = True    # a clip must not race it
                        try:
                            session._stop_run()     # banks the footage so far
                            session._start_run()    # same file, next run
                        except Exception as e:
                            log(f"Capture restart failed: {e}")
                        finally:
                            session._rotating = False
                        _interruptible_sleep(ctl, 0.4)
                        continue
                    if proven and game_alive and not same_shape:
                        # the screen itself changed shape: this file is
                        # finished, and the next session records the new one
                        log("The screen's capture format changed - saving "
                            "this chapter and starting a fresh one.")
                        session = _apply_track_act(
                            ctl, session, current,
                            "split" if len(_list_segments(session.tmp)) >= 4
                            else "restart")
                        if session is None:
                            current = None
                            manual = False
                        _interruptible_sleep(ctl, 0.3)
                        continue
                    # The encoder died mid-capture. Log WHY, then recover: first
                    # retry the SAME encoder on the most-compatible path ('safe'
                    # mode); if that also fails, blacklist it and try the next.
                    err = session.err_text()
                    dead = SETTINGS.get("_encoder_resolved")
                    for ln in err.splitlines()[-4:]:
                        if ln.strip():
                            log("  ffmpeg: " + ln.strip())
                    if not _ENC_SAFE[0]:
                        _ENC_SAFE[0] = True
                        log(f"Encoder '{dead}' exited early; retrying in compatible mode.")
                    else:
                        if dead:
                            _BAD_ENCODERS.add(dead)
                        SETTINGS["_encoder_resolved"] = None
                        _ENC_SAFE[0] = False
                        log(f"Encoder '{dead}' still failed; switching to another encoder.")
                    # If essentially nothing was captured (encoder died at start),
                    # throw it away rather than leaving a broken stub + temp folder.
                    # If it ran long enough to have real footage, salvage it.
                    if len(_list_segments(session.tmp)) >= 2:
                        with ctl.lock:
                            ctl.session = None
                        _finalize_async(ctl, session)   # salvage in background
                    else:
                        session.discard()     # nothing worth keeping; cleans up temp
                        with ctl.lock:
                            ctl.session = None
                    keep_game = current
                    session = None
                    enc_fails += 1
                    if enc_fails >= 8:
                        log("Several encoders failed here; pausing auto-record for this game.")
                        ctl.notify("Lore", "Couldn't find a working video encoder - check the log.")
                        ctl.suppressed_game = keep_game
                        ctl.force_record.clear()   # also stop manual retries
                        current = None
                        manual = False
                        enc_fails = 0
                    if ctl.saving <= 0:
                        ctl.set_status("watching")
                    # leave force_record/current so it re-records the same game next poll
                elif manual and current is None:
                    # Pure desktop recording - attach to a game if one appears,
                    # but never stop just because no game is running.
                    gone = 0
                    gg = detect_fullscreen_game()
                    if gg:
                        current = gg
                        log(f"Attached recording to '{gg}'.")
                elif current is not None and _looks_gone(current):
                    # Debounce: a single missed poll (alt-tab, brief hitch) shouldn't
                    # end the recording - only stop once the game is really gone.
                    # THREE polls now, and each one demands the full
                    # three-agreements test - this is the site that ended
                    # his Bazaar mid-game on two short walks.
                    gone += 1
                    if gone >= 3:
                        gone = 0
                        enc_fails = 0
                        _loop_sound(ctl, "off")
                        # the game just closed - nothing left for a card to cover
                        ctl.notify("Saving your video…", current or "Screen", force=True)
                        ctl.force_record.clear()
                        with ctl.lock:
                            ctl.session = None
                        _finalize_async(ctl, session)
                        session = current = None
                        manual = False
                else:
                    gone = 0
                    enc_fails = 0   # healthy: encoder alive and the game is running
                    _inp_beat(session)
                    _afk_track(ctl, session, current)
                    if session.suspended:              # AFK pause just landed
                        _interruptible_sleep(ctl, SETTINGS["poll_interval"])
                        continue
                    act = _window_track(ctl, session, current)
                    if act:
                        # The game window was RESIZED (or lost for good): a
                        # new frame size can't join this file. 'split' saves
                        # the chapter so far; 'restart' discards a seconds-
                        # old head. Either way the game keeps recording via
                        # the direct re-attach in _apply_track_act.
                        session = _apply_track_act(ctl, session, current, act)
                        if session is None:
                            current = None
                            manual = False
                        _interruptible_sleep(ctl, 0.3)
                        continue
                    if _ENC_SAFE[0] and not safe_persisted and not SETTINGS.get("safe_capture"):
                        # compatible mode was auto-discovered and is working - remember
                        # it so future launches skip the failed fast-path attempt.
                        _persist_setting("safe_capture", True)
                        safe_persisted = True
                        log("Saved compatibility capture mode for next time.")
            _interruptible_sleep(ctl, SETTINGS["poll_interval"])
          except Exception as _loop_err:
            # A single unexpected error (a transient Windows/psutil hiccup, etc.)
            # must NEVER kill the watcher - otherwise the tray icon stays but
            # nothing records for the rest of the session. Log it and keep going.
            log(f"Watcher hit an unexpected error; recovering: {_loop_err}")
            _interruptible_sleep(ctl, 1.0)
    finally:
        _sdr_finish_abort()       # never leave an orphan converter running after quit
        _ai_abort()
        if session:
            session.stop()        # finish the active recording (synchronous on quit)
        with ctl.lock:
            ctl.session = None
        # Wait for any background saves still finalising so quitting never drops one.
        deadline = time.time() + 590
        while ctl.saving > 0 and time.time() < deadline:
            time.sleep(0.2)
        ctl.set_status("stopped")
        log("Recorder stopped.")


def _release_lock():
    # Only delete the lock file if it still holds OUR pid, so a quitting instance can
    # never clobber a lock that another running instance legitimately owns. A garbled
    # or other-pid lock is left alone (a genuinely stale one is reclaimed on the next
    # launch by _watcher_running_pid). Flag files are transient IPC, always cleared.
    try:
        with open(_lock_path()) as fh:
            ours = fh.read().strip() == str(os.getpid())
    except Exception:
        ours = False
    if ours:
        try:
            os.remove(_lock_path())
        except Exception:
            pass
    try:
        os.remove(_show_flag_path())
    except Exception:
        pass


def _claim_lock():
    """Return True if we became the single running instance."""
    other = _watcher_running_pid()
    if other:
        log(f"Lore is already running (PID {other}). Closing this one.")
        return False
    try:
        with open(_lock_path(), "w") as fh:
            fh.write(str(os.getpid()))
    except Exception:
        pass
    try:
        if os.path.exists(_show_flag_path()):
            os.remove(_show_flag_path())
    except Exception:
        pass
    return True


def _watch_core_guarded(ctl):
    """_watch_core with a confession. An uncaught raise in its pre-loop
    section (settings load, migrations, encoder resolve) died on a daemon
    thread into a stderr the windowed exe discards - tray up, tome up, and
    nothing ever records again with no line anywhere saying why."""
    try:
        _watch_core(ctl)
    except Exception:
        import traceback
        tb = traceback.format_exc().strip().splitlines()
        log("THE WATCHER CRASHED - nothing will record until LORE is "
            "restarted: " + " | ".join(tb[-3:]))
        try:
            ctl.notify("Lore", "The recorder crashed - restart LORE to "
                       "record again. See lore.log.")
        except Exception:
            pass


def watch_loop():
    """Legacy console watcher (no tray icon). Ctrl+C to quit."""
    if not _hold_singleton_mutex() or not _claim_lock():
        return
    log("Idle. Launch a game to start. Ctrl+C to quit.")
    ctl = _Ctl()
    t = threading.Thread(target=_watch_core_guarded, args=(ctl,),
                         daemon=True)
    t.start()
    try:
        while t.is_alive():
            t.join(0.3)
    except KeyboardInterrupt:
        ctl.quit.set()
        t.join()
    finally:
        _release_lock()


